import{n as e,r as t,t as n}from"./helpers-ClX0bpsp.js";var r={building:`cache-pavilion`,overview:[n(`ElastiCache is a distributed in-memory data store or cache, DAX is a caching service for DynamoDB and MemoryDB is a durable in-memory database. Cache & Edge Breakwater explained where caches sit and the lazy-loading and write-through strategies. This building is about picking the caching service for a database: ElastiCache for general database caching, DAX for DynamoDB, and MemoryDB when the in-memory store must itself be the durable database.`,[`elasticache-what-is`,`dax`,`memorydb`],[`elasticache-what-is|Amazon ElastiCache is a web service that makes it easy to set up, manage, and scale a distributed in-memory data store or cache environment in the cloud.`,`dax|DAX is a DynamoDB-compatible caching service that enables you to benefit from fast in-memory performance for demanding applications.`,`memorydb|Amazon MemoryDB is a durable, in-memory database service that delivers ultra-fast performance.`])],bullets:[{id:`3.3-K2`,concepts:[n(`ElastiCache is an in-memory key-value store that sits between your application and the data store it accesses. Whenever the application requests data, it first asks the cache; on a miss it reads the database and populates the cache (lazy loading), and writes can update the cache too (write-through).`,`elasticache-strategies`,[`Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`A cache miss occurs when data isn't in the cache or is expired:`]),n(`ElastiCache supports the Valkey, Memcached and Redis OSS engines, and each is an in-memory key-value store. Choose Memcached for the simplest model, large nodes with multiple cores or threads, the ability to scale out and in by adding and removing nodes, and caching objects. In AWS's comparison table, Memcached has no replication, automatic failover, Pub/Sub or sorted sets, while Valkey and Redis OSS offer them. That table lists durability (through a Multi-AZ transactional log) only for cluster-mode-enabled ElastiCache for Valkey 9.0 and later; MemoryDB, below, is the service built to be a durable primary database.`,`elasticache-engines`,[`Amazon ElastiCache supports the Valkey, Memcached, and Redis OSS cache engines.`,`Each of them is an in-memory key-value store.`,`Choose Memcached if the following apply for you: You need the simplest model possible. You need to run large nodes with multiple cores or threads. You need the ability to scale out and in, adding and removing nodes as demand on your system increases and decreases. You need to cache objects.`,`High availability (replication) No Yes Yes Automatic failover No Optional Required Pub/Sub capabilities No Yes Yes Sorted sets No Yes Yes`,`Durability No No Valkey 9.0 and later (sync/async)`],{newer:[`elasticache-valkey`]}),n(`Amazon DynamoDB Accelerator (DAX) is a DynamoDB-compatible caching service that is API-compatible with DynamoDB, so it needs only minimal functional changes to use with an existing application. It reduces response times of eventually consistent reads from single-digit milliseconds to microseconds. A request that specifies strongly consistent reads is passed through to DynamoDB, so DAX does not speed those up. For read-heavy or bursty workloads it can reduce the need to overprovision read capacity units.`,[`dax`,`dax-concepts`],[`dax|DAX addresses three core scenarios: As an in-memory cache, DAX reduces the response times of eventually consistent read workloads by an order of magnitude from single-digit milliseconds to microseconds.`,`dax-concepts|If the request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`,`DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`,`Therefore, it requires only minimal functional changes to use with an existing application.`,`For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`]),n(`Amazon MemoryDB is a durable, in-memory database compatible with Valkey and Redis OSS: all data is stored in memory for microsecond reads and single-digit millisecond writes, and stored durably across multiple Availability Zones using a Multi-AZ transactional log. It can be used as a high-performance primary database, eliminating the need to separately manage both a cache and durable database.`,`memorydb`,[`Amazon MemoryDB is a durable, in-memory database service that delivers ultra-fast performance.`,`Delivering both in-memory performance and Multi-AZ durability, MemoryDB can be used as a high-performance primary database for your microservices applications, eliminating the need to separately manage both a cache and durable database.`,`With MemoryDB, all of your data is stored in memory, which enables you to achieve microsecond read and single-digit millisecond write latency and high throughput.`,`MemoryDB also stores data durably across multiple Availability Zones (AZs) using a Multi-AZ transactional log to enable fast failover, database recovery, and node restarts.`],{newer:[`elasticache-valkey`]})],services:[`Amazon ElastiCache`,`Amazon DynamoDB`],design:[n(`Cue to service: microsecond reads from a cache alongside your database → ElastiCache; eventually consistent DynamoDB reads that need microsecond latency, with only minimal functional changes → DAX; a Valkey- or Redis OSS-compatible database that must be durable → MemoryDB.`,[`database-decision`,`dax`,`memorydb`],[`dax|DAX addresses three core scenarios: As an in-memory cache, DAX reduces the response times of eventually consistent read workloads by an order of magnitude from single-digit milliseconds to microseconds.`,`dax|Therefore, it requires only minimal functional changes to use with an existing application.`,`memorydb|Amazon MemoryDB is compatible with the popular open source data stores Valkey and Redis OSS, enabling you to quickly build applications using the same flexible and friendly data structures, APIs, and commands that they already use.`,`database-decision|If your workload requires extremely high read performance with a response time measured in microseconds (rather than single-digit milliseconds), you might want to consider using in- memory caching solutions such as Amazon ElastiCache alongside your database, or a fully durable, persistent in-memory database such as Amazon MemoryDB.`],{newer:[`elasticache-valkey`]})]},{id:`3.3-S5`,concepts:[n(`Integrate the cache by deciding what to cache and how to keep it fresh. Lazy loading caches only requested data and node failures are not fatal for the application, but a miss costs three trips and data in the cache can become stale; write-through keeps the cache current but caches data that may never be read; adding a time to live (TTL) value can minimize wasted space.`,`elasticache-strategies`,[`The advantages of lazy loading are as follows: Only requested data is cached.`,`Node failures aren't fatal for your application.`,`If data is written to the cache only when there is a cache miss, data in the cache can become stale.`,`Each cache miss results in three trips: Initial request for data from the cacheQuery of the database for the dataWriting the data to the cache`,`The advantages of write-through are as follows: Data in the cache is never stale.`,`By adding a time to live (TTL) value, you can minimize wasted space.`]),n(`ElastiCache offers serverless caching, which eliminates the need to provision instances or configure nodes or clusters. For these serverless caches, reading from replicas can significantly improve performance compared with reading only from the primary cache node.`,[`elasticache-what-is`,`elasticache-strategies`],[`elasticache-what-is|ElastiCache Serverless enables you to create a highly available cache in under a minute, and eliminates the need to provision instances or configure nodes or clusters.`,`elasticache-strategies|You can often significantly improve performance for ElastiCache serverless caches by reading from replicas instead of the primary cache node.`],{newer:[`elasticache-serverless`]}),n(`DAX write operations (BatchWriteItem, UpdateItem, DeleteItem and PutItem) are write-through: the data is first written to the DynamoDB table and then to the DAX cluster, so writes still go to DynamoDB. DAX also supports server-side encryption.`,[`dax-concepts`,`dax`],[`dax-concepts|Write operations The following DAX API operations are considered "write-through": BatchWriteItem UpdateItem DeleteItem PutItem With these operations, data is first written to the DynamoDB table, and then to the DAX cluster.`,`dax|DAX supports server-side encryption.`])],services:[`Amazon ElastiCache`,`Amazon DynamoDB`],design:[n(`Cue: cached data that would otherwise waste space → add a TTL; data must never be stale → write-through; cache must survive restarts as the system of record → MemoryDB rather than a cache.`,[`elasticache-strategies`,`memorydb`],[`elasticache-strategies|By adding a time to live (TTL) value, you can minimize wasted space.`,`elasticache-strategies|The advantages of write-through are as follows: Data in the cache is never stale.`,`memorydb|Amazon MemoryDB is a durable, in-memory database service that delivers ultra-fast performance.`,`memorydb|MemoryDB also stores data durably across multiple Availability Zones (AZs) using a Multi-AZ transactional log to enable fast failover, database recovery, and node restarts.`])]}],cues:[e(`cache for RDS/Aurora queries, session store, Redis- or Memcached-compatible`,`Amazon ElastiCache`,n(`ElastiCache is a managed in-memory data store or cache that works with Valkey, Memcached and Redis OSS.`,`elasticache-what-is`,[`NoteAmazon ElastiCache works with the Valkey, Memcached, and Redis OSS engines.`],{newer:[`elasticache-valkey`]})),e(`simple object cache, multithreaded nodes, scale out by adding nodes`,`ElastiCache for Memcached`,n(`Choose Memcached for the simplest model, large multi-core nodes, scaling by adding nodes and caching objects.`,`elasticache-engines`,[`Choose Memcached if the following apply for you: You need the simplest model possible. You need to run large nodes with multiple cores or threads. You need the ability to scale out and in, adding and removing nodes as demand on your system increases and decreases. You need to cache objects.`])),e(`DynamoDB reads must be served in microseconds with minimal code changes`,`DynamoDB Accelerator (DAX)`,n(`DAX is API-compatible with DynamoDB so it needs only minimal functional changes.`,`dax`,[`Therefore, it requires only minimal functional changes to use with an existing application.`])),e(`in-memory store that must be durable, used as the primary database`,`Amazon MemoryDB`,n(`MemoryDB stores data durably across multiple Availability Zones using a Multi-AZ transactional log.`,`memorydb`,[`MemoryDB also stores data durably across multiple Availability Zones (AZs) using a Multi-AZ transactional log to enable fast failover, database recovery, and node restarts.`])),e(`reduce over-provisioned DynamoDB read capacity for repeated reads of the same keys`,`DAX`,n(`DAX can reduce the need to overprovision read capacity units for read-heavy or bursty workloads.`,`dax`,[`For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`]))],examples:[],confuse:[],azure:[{concept:`Azure Managed Redis`,aws:`Amazon ElastiCache`,mapping:n(`Learn pairs ElastiCache with Azure Managed Redis, a managed service based on Redis Enterprise for caching, sessions, messaging and other low-latency temporary-data patterns.`,[`learn-databases`,`elasticache-what-is`],[`learn-databases|For in-memory caching and temporary data, Azure Managed Redis provides a managed service based on Redis Enterprise.`,`learn-databases|Use Azure Managed Redis for caching, sessions, messaging, and other low-latency temporary-data patterns.`,`elasticache-what-is|Amazon ElastiCache is a web service that makes it easy to set up, manage, and scale a distributed in-memory data store or cache environment in the cloud.`]),breaks:n(`Learn says not to use Azure Managed Redis as the authoritative persistent database for a workload, and lists no direct Azure equivalent for Amazon MemoryDB. On AWS, ElastiCache is the cache, MemoryDB is the durable in-memory database, and DAX is a caching service built for DynamoDB.`,[`learn-databases`,`memorydb`,`dax`],[`learn-databases|Don't use it as the authoritative persistent database for a workload.`,`learn-databases|Durable Redis-compatible database Amazon MemoryDB No direct equivalent Amazon MemoryDB is designed as a durable primary database.`,`memorydb|Amazon MemoryDB is a durable, in-memory database service that delivers ultra-fast performance.`,`dax|DAX is a DynamoDB-compatible caching service that enables you to benefit from fast in-memory performance for demanding applications.`])}]},i={building:`container-yard`,overview:[n(`Serverless Mill and Container Dock introduced Lambda, Fargate, ECS and EKS. This building is about how they perform under load: how a function avoids cold starts and how many copies of it run, and how container services add and remove tasks or nodes automatically.`,[`lambda-provisioned`,`ecs-autoscaling`],[`lambda-provisioned|Provisioned concurrency is useful for reducing cold start latencies for functions and designed to make functions available with double-digit millisecond response times.`,`ecs-autoscaling|Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`])],beyondProject:[n(`Your Lambda function works, so the SAA-level questions are about load: Lambda concurrency is the number of in-flight requests your function is handling at once, and two controls shape it. Reserved concurrency sets both the maximum and the minimum number of concurrent instances allocated to a function, so it reserves capacity for the function and also caps it. Provisioned concurrency keeps pre-initialised execution environments ready to respond immediately, which is how you reduce cold-start latency.`,[`lambda-reserved`,`lambda-provisioned`,`lambda-concurrency`],[`lambda-concurrency|To summarize, your Event Function's concurrency is the number of concurrent requests that it's handling at the same time.`,`lambda-reserved|Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`,`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`],{allow:[`two`]})],bullets:[{id:`3.2-K5`,concepts:[n(`Lambda runs each invocation independently and scales horizontally to match demand. By default the account has a total concurrency limit of 1,000 concurrent executions across all functions in a Region, and reserved concurrency dedicates part of it to one function so that no other function can use it; functions without reserved concurrency share the remaining pool.`,[`lambda-welcome`,`lambda-concurrency`],[`lambda-welcome|Each invocation runs independently with no shared state, scaling horizontally to match demand.`,`lambda-concurrency|By default, Lambda provides your account with a total concurrency limit of 1,000 concurrent executions across all Event Functions in an AWS Region.`,`lambda-concurrency|When you dedicate reserved concurrency to an Event Function, no other Event Function can use that concurrency.`,`lambda-concurrency|Functions that don't have reserved concurrency share the remaining pool of unreserved concurrency.`]),n(`Provisioned concurrency is useful for reducing cold start latencies, with interactive workloads (web and mobile applications) benefiting most, while asynchronous workloads such as data processing pipelines are often less latency sensitive and do not usually need it. Configuring provisioned concurrency incurs additional charges; reserved concurrency has no charge.`,[`lambda-provisioned`,`lambda-concurrency`],[`lambda-provisioned|Provisioned concurrency is useful for reducing cold start latencies for functions and designed to make functions available with double-digit millisecond response times.`,`lambda-provisioned|Generally, interactive workloads benefit the most from the feature.`,`lambda-provisioned|Asynchronous workloads, such as data processing pipelines, are often less latency sensitive and so do not usually need provisioned concurrency.`,`lambda-concurrency|There is no charge for configuring reserved concurrency for an Event Function.`,`lambda-provisioned|Configuring provisioned concurrency incurs additional charges to your AWS account.`]),n(`Lambda SnapStart is the other cold start option: Lambda initialises your function when you publish a function version and takes a snapshot of the initialised execution environment, which can bring startup down to as low as sub-second. SnapStart supports the Java 11 and later, Python 3.12 and later, and .NET 8 and later managed runtimes, and for Java managed runtimes there is no additional cost for SnapStart.`,`lambda-snapstart`,[`Use SnapStart to reduce this latency from several seconds to as low as sub-second, in optimal scenarios.`,`SnapStart supports the following Lambda managed runtimes and the corresponding AWS Lambda base images across ZIP and container image deployment format: Java 11 and later Python 3.12 and later .NET 8 and later.`,`For Java managed runtimes, there's no additional cost for SnapStart.`],{newer:[`lambda-snapstart`]}),n(`Fargate removes the need to choose server types, decide when to scale clusters or optimise cluster packing, and each task has its own isolation boundary.`,`fargate-ecs`,[`This removes the need to choose server types, decide when to scale your clusters, or optimize cluster packing.`,`Each Fargate task has its own isolation boundary and does not share the underlying kernel, CPU resources, memory resources, or elastic network interface with another task.`])],services:[`AWS Lambda`,`AWS Fargate`],design:[n(`Cue: first requests are slow after idle periods → provisioned concurrency; a critical function must always have capacity, or one function must be capped → reserved concurrency; functions throttled during a spike → the account concurrency limit, which you can ask to have raised.`,[`lambda-provisioned`,`lambda-reserved`,`lambda-concurrency`],[`lambda-provisioned|Provisioned concurrency is useful for reducing cold start latencies for functions and designed to make functions available with double-digit millisecond response times.`,`lambda-reserved|Reserved concurrency is useful for ensuring that your most critical functions always have enough concurrency to handle incoming requests.`,`lambda-reserved|Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`,`lambda-concurrency|To support your specific account needs, you can request a quota increase and configure function-level concurrency controls so that your critical Event Functions don't experience throttling.`])]},{id:`3.2-K6`,concepts:[n(`Amazon ECS service auto scaling increases or decreases the desired number of tasks automatically, using Application Auto Scaling. ECS publishes CloudWatch metrics with your service's average CPU and memory usage, which you can use to scale out at peak times and scale in to reduce cost when utilisation is low.`,`ecs-autoscaling`,[`Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`,`Amazon ECS leverages the Application Auto Scaling service to provide this functionality.`,`You can use these and other CloudWatch metrics to scale out your service (add more tasks) to deal with high demand at peak times, and to scale in your service (run fewer tasks) to reduce costs during periods of low utilization.`]),n(`ECS service auto scaling supports scaling to a target metric value (like a thermostat), scaling by step adjustments that vary with the size of a CloudWatch alarm breach, and scheduled actions.`,`ecs-autoscaling`,[`Use a target metric to scale Amazon ECS services— Increase or decrease the number of tasks that your service runs based on a target value for a specific metric.`,`Use predefined increments based on CloudWatch alarms to scale Amazon ECS services— Increase or decrease the number of tasks that your service runs based on a set of scaling adjustments, known as step adjustments, that vary based on the size of the alarm breach.`]),n(`On Amazon EKS, autoscaling is a major Kubernetes function. EKS Auto Mode automatically scales cluster compute resources: if a pod cannot fit onto existing nodes, it creates a new one, and it also consolidates workloads and deletes nodes. It builds upon Karpenter, and EKS also supports Cluster Autoscaler.`,`eks-autoscaling`,[`Autoscaling is a function that automatically scales your resources out and in to meet changing demands.`,`EKS Auto Mode Amazon EKS Auto Mode automatically scales cluster compute resources.`,`If a pod can’t fit onto existing nodes, EKS Auto Mode creates a new one.`,`EKS Auto Mode builds upon Karpenter.`],{newer:[`eks-auto-mode`]})],services:[`Amazon ECS`,`Amazon EKS`,`AWS Fargate`],design:[n(`Cue: scale the number of containers (ECS tasks) with load → ECS service auto scaling; scale Kubernetes worker capacity as pods are added → EKS Auto Mode, Karpenter or Cluster Autoscaler; no choosing server types or scaling clusters yourself → Fargate.`,[`ecs-autoscaling`,`eks-autoscaling`,`fargate-ecs`],[`fargate-ecs|This removes the need to choose server types, decide when to scale your clusters, or optimize cluster packing.`,`ecs-autoscaling|Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`,`eks-autoscaling|If a pod can’t fit onto existing nodes, EKS Auto Mode creates a new one.`],{newer:[`eks-auto-mode`]})]}],cues:[e(`first request after idle is slow (cold start) for a latency-sensitive API`,`Lambda provisioned concurrency`,n(`Provisioned concurrency reduces cold start latencies; interactive workloads benefit most.`,`lambda-provisioned`,[`Provisioned concurrency is useful for reducing cold start latencies for functions and designed to make functions available with double-digit millisecond response times.`])),e(`guarantee or cap the concurrent executions of one function`,`Lambda reserved concurrency`,n(`Reserved concurrency sets both the maximum and the minimum number of concurrent instances for a function and dedicates them to it.`,`lambda-reserved`,[`Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`])),e(`add or remove ECS tasks automatically based on CPU or memory`,`ECS service auto scaling (Application Auto Scaling)`,n(`ECS publishes CPU and memory metrics used to scale a service out and in.`,`ecs-autoscaling`,[`You can use these and other CloudWatch metrics to scale out your service (add more tasks) to deal with high demand at peak times, and to scale in your service (run fewer tasks) to reduce costs during periods of low utilization.`])),e(`Kubernetes pods cannot be scheduled for lack of nodes`,`EKS Auto Mode / Karpenter / Cluster Autoscaler`,n(`EKS Auto Mode creates a new node if a pod cannot fit onto existing nodes.`,`eks-autoscaling`,[`If a pod can’t fit onto existing nodes, EKS Auto Mode creates a new one.`],{newer:[`eks-auto-mode`]}))],examples:[],confuse:[],azure:[{concept:`Azure Kubernetes Service (AKS)`,aws:`Amazon EKS`,mapping:n(`Learn pairs AKS with Amazon EKS and notes AKS has two modes, AKS Standard for full control and customisation and AKS Automatic for simplified, production-ready deployments. EKS has a comparable split between standard EKS and EKS Auto Mode.`,[`learn-compute`,`eks-what-is`],[`learn-compute|Azure Kubernetes Service (AKS) provides two modes: AKS Standard for full control and customization and AKS Automatic for simplified, production-ready deployments with built-in best practices.`,`eks-what-is|Choose between standard EKS or fully automated EKS Auto Mode`],{newer:[`eks-auto-mode`],allow:[`two`]}),breaks:n(`On the AWS side, EKS Auto Mode builds on Karpenter to scale cluster compute resources. Learn pairs Amazon EKS with AKS for orchestrating containerized deployments with Kubernetes, and pairs AWS Auto Scaling with Azure virtual machine scale sets and App Service autoscaling; Karpenter has no Learn pairing.`,[`eks-autoscaling`,`learn-compute`],[`eks-autoscaling|EKS Auto Mode builds upon Karpenter.`,`learn-compute|AWS service Azure service Description AWS Auto Scaling Azure Virtual Machine Scale Sets, Azure App Service autoscaling`,`learn-compute|Amazon Elastic Kubernetes Service (Amazon EKS) Azure Kubernetes Service (AKS) You can use Amazon EKS and Azure Kubernetes Service (AKS) to orchestrate Docker containerized application deployments with Kubernetes.`],{newer:[`eks-auto-mode`]})},{concept:`Azure Container Apps`,aws:`Amazon ECS (and AWS Fargate)`,mapping:n(`Learn pairs Amazon ECS and AWS Fargate with Azure Container Apps, a managed container platform that provides built-in scaling, service discovery and traffic management.`,[`learn-compute`,`ecs-autoscaling`],[`learn-compute|Azure Container Apps is a managed container platform that provides built-in scaling, service discovery, and traffic management.`,`ecs-autoscaling|Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`]),breaks:n(`Learn lists AWS Fargate against two Azure services, Azure Container Instances and Azure Container Apps, while it pairs ECS with Container Apps alone. On AWS, Fargate is one serverless compute engine that you use with both ECS and EKS, and ECS service scaling is configured on the service through Application Auto Scaling.`,[`ecs-autoscaling`,`container-decision`,`learn-compute`],[`ecs-autoscaling|Amazon ECS leverages the Application Auto Scaling service to provide this functionality.`,`container-decision|You can use Fargate with both Amazon ECS and Amazon EKS.`,`learn-compute|AWS Fargate Azure Container Instances, Azure Container Apps AWS Fargate is a serverless compute engine that provides compute capacity for Amazon ECS tasks and Amazon EKS pods.`],{allow:[`two`]})}]},a={building:`data-lake-reservoir`,overview:[n(`A {{term:data-lake}} keeps raw data in one place and lets many tools analyse it. One combination on AWS is Amazon S3 for storage, AWS Glue Data Catalog for metadata, AWS Lake Formation for governance, Amazon Athena for SQL queries and {{rename:quick}} for dashboards.`,[`what-is-data-lake`,`lake-formation`,`athena-what-is`,`quick-what-is`],[`what-is-data-lake|You can store your data as-is, without having to first structure the data, and run different types of analytics—from dashboards and visualizations to big data processing, real-time analytics, and machine learning to guide better decisions.`,`lake-formation|With Lake Formation, you can manage fine-grained access control for your data lake data on Amazon Simple Storage Service (Amazon S3) and its metadata in AWS Glue Data Catalog.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`quick-what-is|Connect to data sources, build dashboards, and embed analytics in applications.`])],bullets:[{id:`3.5-K1`,concepts:[n(`Amazon Athena is an interactive query service that analyses data directly in S3 using standard SQL: you point it at the data and run ad-hoc queries. It is serverless, so there is no infrastructure to set up or manage, and it scales automatically by running queries in parallel.`,`athena-what-is`,[`Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`With a few actions in the AWS Management Console, you can point Athena at your data stored in Amazon S3 and begin using standard SQL to run ad-hoc queries and get results in seconds.`,`Athena scales automatically—running queries in parallel—so results are fast, even with large datasets and complex queries.`]),n(`AWS Lake Formation helps you centrally govern, secure and share data for analytics and machine learning. It provides its own permissions model that augments IAM, with fine-grained access at the column, row and cell levels enforced across analytics services such as Athena, Quick, Redshift Spectrum, EMR and Glue.`,`lake-formation`,[`AWS Lake Formation helps you centrally govern, secure, and globally share data for analytics and machine learning.`,`Lake Formation provides its own permissions model that augments the IAM permissions model.`,`Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`]),n(`AWS Glue is a serverless data integration service for discovering, preparing, moving and integrating data from multiple sources, with a centralised data catalog. (Refinery covers transformation.)`,`glue-what-is`,[`AWS Glue is a serverless data integration service that makes it easy for analytics users to discover, prepare, move, and integrate data from multiple sources.`]),n(`{{rename:quick}} includes Amazon Quick Sight, the feature for interactive data visualisation and business intelligence: connect to data sources, build dashboards and embed analytics in applications. Quick Sight continues as a feature within Quick.`,`quick-what-is`,[`Amazon Quick Sight – Interactive data visualization and business intelligence.`,`Connect to data sources, build dashboards, and embed analytics in applications.`,`QuickSight continues as Amazon Quick Sight, a feature within Quick.`])],services:[`Amazon Athena`,`AWS Lake Formation`,`Amazon Quick`],design:[n(`Cue: ad-hoc SQL on files in S3 with nothing to provision → Athena; fine-grained access control to data in the lake → Lake Formation; dashboards and BI → Quick (Quick Sight).`,[`athena-what-is`,`lake-formation`,`quick-what-is`],[`athena-what-is|With a few actions in the AWS Management Console, you can point Athena at your data stored in Amazon S3 and begin using standard SQL to run ad-hoc queries and get results in seconds.`,`lake-formation|With Lake Formation, you can manage fine-grained access control for your data lake data on Amazon Simple Storage Service (Amazon S3) and its metadata in AWS Glue Data Catalog.`,`quick-what-is|Amazon Quick Sight – Interactive data visualization and business intelligence.`])]},{id:`3.5-S1`,concepts:[n(`Building a data lake: you can store your data as-is, without first structuring it, and then understand what is in the lake through crawling, cataloging and indexing. Amazon S3 can be used to store data for data lakes, and AWS lists data lakes among its use cases.`,[`what-is-data-lake`,`s3-what-is`],[`what-is-data-lake|You can store your data as-is, without having to first structure the data`,`what-is-data-lake|They also give you the ability to understand what data is in the lake through crawling, cataloging, and indexing of data.`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`]),n(`Securing it: Lake Formation manages fine-grained access to data lake data in S3 and its metadata in the Glue Data Catalog with a simple grant or revoke mechanism, much like a relational database, and can share data across AWS accounts and organizations. Layer S3 Block Public Access underneath: its settings override bucket policies and permissions so that you can limit public access.`,[`lake-formation`,`s3-block-public-access`],[`lake-formation|Lake Formation permissions model enables fine-grained access to data stored in data lakes as well as external data sources such as Amazon Redshift data warehouses, Amazon DynamoDB databases, and third-party data sources through a simple grant or revoke mechanism, much like a relational database management system (RDBMS).`,`lake-formation|Lake Formation also allows you to share data internally and externally across multiple AWS accounts, AWS organizations or directly with IAM principals in another account providing fine-grained access to the Data Catalog metadata and underlying data.`,`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`]),n(`Make queries cheaper and faster by storing the data in a columnar format and partitioning it. Apache Parquet and ORC are columnar formats optimised for fast retrieval, both provide good compression, and predicate pushdown lets queries fetch only the blocks they need; partitioning lets a query restrict the amount of data scanned, improving performance and reducing cost.`,[`athena-columnar`,`athena-partitions`],[`athena-columnar|Apache Parquet and ORC are columnar storage formats that are optimized for fast retrieval of data and used in AWS analytical applications.`,`athena-columnar|Compression – Both Parquet and ORC provide good compression, but the best format for you can depend on your specific use case.`,`athena-columnar|Predicate pushdown in Parquet and ORC enables Athena queries to fetch only the blocks it needs, improving query performance.`,`athena-partitions|By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`])],services:[`Amazon S3`,`AWS Lake Formation`,`Amazon Athena`],design:[n(`Reference design: raw data lands in S3, Glue crawlers or jobs catalogue and transform it (Refinery), Lake Formation governs access, Athena queries it, Quick visualises it.`,[`glue-what-is`,`lake-formation`,`athena-what-is`,`s3-what-is`,`quick-what-is`],[`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`glue-what-is|Use AWS Glue crawlers to automatically infer schema information and integrate it into your AWS Glue Data Catalog.`,`glue-what-is|These include data discovery, modern ETL, cleansing, transforming, and centralized cataloging.`,`lake-formation|AWS Lake Formation helps you centrally govern, secure, and globally share data for analytics and machine learning.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`quick-what-is|Amazon Quick Sight – Interactive data visualization and business intelligence.`])]},{id:`3.5-S4`,concepts:[n(`Visualisation strategy: choose the BI tool and connect it to the governed data. Amazon Quick Sight connects to data sources, builds dashboards and embeds analytics in applications, and Lake Formation permissions are enforced when Quick reads the lake.`,[`quick-what-is`,`lake-formation`],[`quick-what-is|Connect to data sources, build dashboards, and embed analytics in applications.`,`lake-formation|Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`]),n(`{{rename:quick}} is an AI-powered service for automating tasks, analysing data, building web applications and conducting research.`,`quick-what-is`,[`Amazon Quick is an AI-powered service for automating tasks, analyzing data, building web applications, and conducting research.`,`NoteAmazon Quick evolved from Amazon QuickSight.`])],services:[`Amazon Quick`],design:[n(`Cue: business users need dashboards and embedded analytics on lake data → Quick Sight; they need row-level restrictions on the lake data → Lake Formation, whose permissions are enforced at the row level across services such as Athena and Quick.`,[`quick-what-is`,`lake-formation`],[`quick-what-is|Connect to data sources, build dashboards, and embed analytics in applications.`,`quick-what-is|Amazon Quick Sight – Interactive data visualization and business intelligence.`,`lake-formation|Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`])]}],cues:[e(`run SQL queries directly on data in S3 with no servers to manage`,`Amazon Athena`,n(`Athena queries data in S3 with standard SQL and is serverless.`,`athena-what-is`,[`Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`])),e(`column-level or row-level access control on data lake data`,`AWS Lake Formation`,n(`Lake Formation enforces column, row and cell-level permissions.`,`lake-formation`,[`Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`])),e(`reduce the amount of data Athena scans`,`Partition the data and store it in a columnar format such as Parquet`,n(`Partitioning restricts the data scanned, and columnar formats let queries fetch only the blocks they need.`,[`athena-partitions`,`athena-columnar`],[`athena-partitions|By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`,`athena-columnar|Predicate pushdown in Parquet and ORC enables Athena queries to fetch only the blocks it needs, improving query performance.`])),e(`interactive dashboards and BI over data sources`,`Amazon Quick (Quick Sight)`,n(`Quick Sight provides interactive visualisation and business intelligence.`,`quick-what-is`,[`Amazon Quick Sight – Interactive data visualization and business intelligence.`])),e(`store all data as-is, structured and unstructured, at any scale`,`Data lake on Amazon S3`,n(`A data lake is a centralised repository for structured and unstructured data at any scale.`,`what-is-data-lake`,[`A data lake is a centralized repository that allows you to store all your structured and unstructured data at any scale.`]))],examples:[],confuse:[],azure:[{concept:`Azure Data Lake Storage`,aws:`Amazon S3`,mapping:n(`Learn pairs Amazon S3 with Azure Data Lake Storage: both provide durable object storage for analytical data, and Data Lake Storage provides object storage with a hierarchical namespace.`,[`learn-analytics`,`s3-what-is`],[`learn-analytics|Amazon S3 Azure Data Lake Storage Both provide durable object storage for analytical data.`,`learn-analytics|Data Lake Storage provides object storage with a hierarchical namespace.`,`s3-what-is|Amazon S3 is an object storage service that stores data as objects, hierarchical data, or tabular data within buckets.`]),breaks:n(`Learn says to compare namespace behaviour, security, lifecycle management, replication, ecosystem integration and data-transfer costs. On the AWS side, Lake Formation manages fine-grained access control for data lake data on Amazon S3.`,[`learn-analytics`,`lake-formation`],[`learn-analytics|Compare namespace behavior, security, lifecycle management, replication, ecosystem integration, and data-transfer costs.`,`lake-formation|With Lake Formation, you can manage fine-grained access control for your data lake data on Amazon Simple Storage Service (Amazon S3) and its metadata in AWS Glue Data Catalog.`])},{concept:`OneLake security and Microsoft Purview in Fabric`,aws:`AWS Lake Formation`,mapping:n(`Learn pairs AWS Lake Formation, which manages access to S3-based data lakes, with OneLake security and Microsoft Purview in Fabric.`,[`learn-analytics`,`lake-formation`],[`learn-analytics|AWS Lake Formation manages access to S3-based data lakes.`,`lake-formation|Lake Formation provides its own permissions model that augments the IAM permissions model.`]),breaks:n(`Learn warns that Fabric separates storage permissions, item permissions and governance capabilities, and says not to assume a single-service equivalent. On the AWS side, Lake Formation provides its own permissions model that augments the IAM permissions model.`,[`learn-analytics`,`lake-formation`],[`learn-analytics|Fabric separates storage permissions, item permissions, and governance capabilities.`,`learn-analytics|Map authorization and governance requirements instead of assuming a single-service equivalent.`,`lake-formation|Lake Formation provides its own permissions model that augments the IAM permissions model.`])},{concept:`Fabric lakehouse SQL analytics endpoint / Azure Databricks SQL`,aws:`Amazon Athena`,mapping:n(`Learn pairs Amazon Athena, serverless SQL over data in S3, with a Fabric lakehouse SQL analytics endpoint or Azure Databricks SQL.`,[`learn-analytics`,`athena-what-is`],[`learn-analytics|Athena Fabric lakehouse SQL analytics endpoint or Azure Databricks SQL Athena is serverless SQL over data in S3.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`]),breaks:n(`Learn says the Azure options differ in storage, metadata, compute and billing, and tells you to select based on data location, SQL compatibility, latency, concurrency and governance. Learn pairs Athena with either a Fabric lakehouse SQL analytics endpoint or Azure Databricks SQL, not with a single Azure service.`,[`learn-analytics`,`athena-what-is`],[`learn-analytics|Azure options differ in storage, metadata, compute, and billing.`,`learn-analytics|Select based on data location, SQL compatibility, latency, concurrency, and governance.`,`athena-what-is|Athena scales automatically—running queries in parallel—so results are fast, even with large datasets and complex queries.`])},{concept:`Power BI`,aws:`Amazon Quick (Quick Sight)`,mapping:n(`Learn pairs {{rename:quick}} with Power BI: both provide semantic modelling, reports, dashboards, sharing and embedded analytics, and Learn says to compare licensing, capacity, identity, governance, authoring and embedding requirements.`,[`learn-analytics`,`quick-what-is`],[`learn-analytics|Amazon QuickSight Power BI Both provide semantic modeling, reports, dashboards, sharing, and embedded analytics.`,`learn-analytics|Compare licensing, capacity, identity, governance, authoring, and embedding requirements.`,`quick-what-is|Amazon Quick Sight – Interactive data visualization and business intelligence.`]),breaks:n(`On the AWS side, {{rename:quick}} evolved from the earlier service, which continues as Amazon Quick Sight, a feature within Quick; the Microsoft comparison page lists it as QuickSight.`,[`quick-what-is`,`learn-analytics`],[`quick-what-is|Amazon Quick evolved from Amazon QuickSight.`,`quick-what-is|QuickSight continues as Amazon Quick Sight, a feature within Quick.`,`learn-analytics|Amazon QuickSight Power BI Both provide semantic modeling, reports, dashboards, sharing, and embedded analytics.`])}]},o={building:`database-registry`,overview:[n(`Choosing a database is choosing a data model and an engine. AWS offers a growing number of database options with diverse data models: relational, key-value, document, in-memory, graph, time series, vector and wide-column. The first cut is relational versus non-relational; the second is which engine or service inside that group, and whether you are migrating from an existing engine.`,`database-decision`,[`AWS offers a growing number of database options (15+) with diverse data models to support a variety of workloads.`,`These include relational, key-value, document, in-memory, graph, time series, vector, and wide-column.`])],beyondProject:[n(`Your project already uses DynamoDB, a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale. The SAA question is whether DynamoDB is the right type at all: AWS suggests it for key-value workloads such as session stores or shopping carts, and a workload that needs joins or rich relational queries points to a relational engine instead. You also choose the capacity mode: on-demand or provisioned.`,[`dynamodb-what-is`,`database-decision`,`dynamodb-capacity`],[`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`,`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`dynamodb-capacity|In Amazon DynamoDB, you can choose between on-demand mode and provisioned mode for your tables to accommodate different workload requirements.`],{allow:[`two`]})],bullets:[{id:`3.3-K6`,concepts:[n(`AWS DMS migrates relational databases, data warehouses, NoSQL databases and other data stores into the AWS Cloud or between cloud and on-premises setups. You can discover source data stores, convert source schemas and migrate the data.`,`dms-what-is`,[`AWS Database Migration Service (AWS DMS) is a cloud service that makes it possible to migrate relational databases, data warehouses, NoSQL databases, and other types of data stores.`,`With AWS DMS, you can discover your source data stores, convert your source schemas, and migrate your data.`]),n(`A {{term:homogeneous-migration}} keeps the same engine (AWS DMS supports it for moving away from old infrastructure), while a {{term:heterogeneous-migration}} changes engine: AWS DMS supports fully heterogeneous migrations between supported engines, and DMS Schema Conversion (or the AWS Schema Conversion Tool) converts the source schemas to the new target engine first.`,`dms-what-is`,[`dms-what-is|Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`,`dms-what-is|AWS DMS supports fully heterogeneous data migrations between the supported engines.`,`dms-what-is|To migrate to a different database engine, you can use DMS Schema Conversion.`,`dms-what-is|Alternatively, you can download the AWS Schema Conversion Tool (AWS SCT) to your local PC to convert your source schemas.`],{newer:[`dms-schema-conversion`]}),n(`After converting the schema, you can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`,`dms-what-is`,[`You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]),n(`Targets AWS names include Amazon RDS and Aurora (managed relational services), Amazon Redshift (managed data warehouse), Amazon DynamoDB (NoSQL) and Amazon S3 (low-cost storage).`,`dms-what-is`,[`For example, AWS DMS can help you take advantage of the managed database services provided by Amazon Relational Database Service (Amazon RDS) or Amazon Aurora. Or it can help you move to the managed data warehouse service provided by Amazon Redshift, NoSQL platforms like Amazon DynamoDB, or low-cost storage platforms like Amazon Simple Storage Service (Amazon S3).`])],services:[`AWS DMS`,`Amazon RDS`,`Amazon Aurora`],design:[n(`Cue: same engine, move to AWS → homogeneous migration with DMS; different engine → schema conversion first, then DMS; keep the source live while migrating → ongoing replication.`,`dms-what-is`,[`You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`])]},{id:`3.3-K8`,concepts:[n(`Relational databases are still very popular for structured data and business objects, but are not designed for endless scale. NoSQL databases favour scalability, performance and availability over the consistency of relational databases, and typically do not enforce a strict schema.`,`msa-data-store`,[`Relational databases are still very popular to store structured data and business objects.`,`Relational databases, however, are not designed for endless scale, which can make it difficult and time intensive to apply techniques to support a high number of queries.`,`NoSQL databases have been designed to favor scalability, performance, and availability over the consistency of relational databases.`]),n(`There are two high-level categories of AWS OLTP databases, relational and non-relational. If you need to store and analyse massive amounts of data quickly (an OLAP requirement), AWS offers Amazon Redshift.`,`database-decision`,[`There are two high-level categories of AWS OLTP databases—relational and non-relational.`,`If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`],{allow:[`two`]}),n(`Serverless database options include Aurora DSQL, Aurora Serverless, DynamoDB, ElastiCache, Keyspaces, Timestream for LiveAnalytics and Neptune Serverless. Aurora serverless is an on-demand, autoscaling configuration that adjusts capacity based on application demand.`,[`database-decision`,`aurora-serverless`],[`database-decision|AWS serverless offerings include Amazon Aurora DSQL, Amazon Aurora Serverless, Amazon DynamoDB, Amazon ElastiCache, Amazon Keyspaces (for Apache Cassandra), Amazon Timestream for LiveAnalytics, and Amazon Neptune Serverless.`,`aurora-serverless|Aurora serverless is an on-demand, autoscaling configuration for Amazon Aurora.`],{newer:[`elasticache-serverless`,`aurora-dsql`]}),n(`AWS has closed new customer access to Amazon Timestream for LiveAnalytics (not on the exam guide's in-scope list, so context only) and recommends that new customers evaluate Amazon Timestream for InfluxDB instead.`,[`timestream-availability`],[`timestream-availability|After careful consideration, we have made the decision to close new customer access to Amazon Timestream for LiveAnalytics, effective 6/20/25.`,`timestream-availability|We recommend that new customers evaluate Amazon Timestream for InfluxDB as an alternative due to its similar functionality.`],{status:`closed`,allow:[`6/20/25`]}),n(`In-memory: for microsecond response times use an in-memory cache such as ElastiCache alongside your database, or Amazon MemoryDB when you need a fully durable, persistent in-memory database.`,`database-decision`,[`If your workload requires extremely high read performance with a response time measured in microseconds (rather than single-digit milliseconds), you might want to consider using in- memory caching solutions such as Amazon ElastiCache alongside your database, or a fully durable, persistent in-memory database such as Amazon MemoryDB.`])],services:[`Amazon RDS`,`Amazon DynamoDB`,`Amazon ElastiCache`,`Amazon Aurora`],design:[n(`Cue: structured data and business objects → relational; large amounts of data and very high request throughput → key-value (DynamoDB); complex networks of objects such as social networks or fraud detection → graph (Neptune); JSON-like documents → DocumentDB; analysing massive amounts of data → Redshift.`,`database-decision`,[`Key-value databases can scale to large amounts of data and extremely high throughput of requests, while servicing millions of simultaneous users through distributed processing and storage.`,`Amazon Neptune Graph Use when you have to model complex networks of objects, such as social networks, fraud detection, and recommendation engine use cases.`,`Amazon DocumentDB (with MongoDB compatibility) Document Use when you want to store JSON-like documents with rich querying abilities across the fields of the documents.`,`If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`])]},{id:`3.3-S3`,concepts:[n(`Amazon RDS offers a choice of engines (PostgreSQL, MySQL, MariaDB, SQL Server, Oracle and Db2), and Aurora is compatible with MySQL and PostgreSQL. AWS DMS supports a migration that keeps the same database engine as well as fully heterogeneous migrations between supported engines.`,[`database-decision`,`aurora-overview`,`dms-what-is`],[`database-decision|Amazon RDS Relational Use when you need a fully managed relational database with your choice of six popular engines: PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`,`dms-what-is|Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`,`dms-what-is|AWS DMS supports fully heterogeneous data migrations between the supported engines.`]),n(`The code, tools and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`,`aurora-overview`,[`The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`])],services:[`Amazon RDS`,`Amazon Aurora`,`AWS DMS`],design:[n(`Cue: "the application uses Oracle/SQL Server and cannot change" → RDS with that engine; "MySQL or PostgreSQL application being migrated or modernised, or with less predictable query patterns" → Aurora.`,`database-decision`,[`Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`])]},{id:`3.3-S4`,concepts:[n(`Aurora is the relational choice for migrating or modernising an on-premises relational workload, or one with less predictable query patterns; DynamoDB is the key-value choice for session stores or shopping carts; DocumentDB, Neptune, Timestream and Keyspaces cover document, graph, time series and Cassandra-compatible wide-column needs.`,`database-decision`,[`Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`,`Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`Amazon DocumentDB (with MongoDB compatibility) Document Use when you want to store JSON-like documents with rich querying abilities across the fields of the documents.`,`Amazon Timestream Time series Use when you have a large amount of time series data, potentially from a number of sources, such as Internet of Things (IoT) data, application metrics, and asset tracking.`]),n(`DynamoDB capacity is chosen as on-demand mode or provisioned mode, and the throughput mode determines how capacity is managed and how reads and writes are charged. (Capacity planning detail is in Tuning Bay.)`,`dynamodb-capacity`,[`A table’s throughput mode determines how the capacity of a table is managed.`,`Throughput mode also determines how you're charged for the read and write operations on your tables.`])],services:[`Amazon Aurora`,`Amazon DynamoDB`,`Amazon RDS`],design:[n(`Decision cue from the question: needs a relational database → Aurora or RDS; needs single-digit-millisecond performance at any scale with no servers to manage → DynamoDB. The Aurora vs RDS comparison below covers the first branch.`,[`dynamodb-what-is`,`database-decision`],[`database-decision|Amazon RDS Relational Use when you need a fully managed relational database with your choice of six popular engines: PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`])]}],cues:[e(`keep the same database engine while moving to AWS`,`Homogeneous migration with AWS DMS`,n(`AWS DMS supports migrating away from old infrastructure while continuing to use the same engine.`,`dms-what-is`,[`Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`])),e(`migrate to a different database engine`,`Heterogeneous migration: schema conversion plus AWS DMS`,n(`DMS Schema Conversion converts source schemas to a new target engine before DMS migrates the data.`,`dms-what-is`,[`To migrate to a different database engine, you can use DMS Schema Conversion.`],{newer:[`dms-schema-conversion`]})),e(`MySQL- or PostgreSQL-compatible with data copies across three AZs`,`Amazon Aurora`,n(`Aurora is compatible with MySQL and PostgreSQL and keeps copies of the data across three Availability Zones.`,[`aurora-storage`,`aurora-overview`],[`aurora-storage|A cluster volume consists of copies of the data across three Availability Zones in a single AWS Region.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`])),e(`Oracle, SQL Server, MariaDB or Db2`,`Amazon RDS (not Aurora)`,n(`Those are RDS engines.`,`database-decision`,[`Amazon RDS Relational Use when you need a fully managed relational database with your choice of six popular engines: PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`])),e(`unpredictable load, database capacity should scale on demand`,`Aurora serverless or DynamoDB on-demand`,n(`Aurora serverless adjusts capacity automatically based on application demand.`,`aurora-serverless`,[`Capacity is adjusted automatically based on application demand.`])),e(`key-value lookups at massive scale with single-digit millisecond latency`,`Amazon DynamoDB`,n(`DynamoDB is a serverless NoSQL database with single-digit millisecond performance at any scale.`,`dynamodb-what-is`,[`Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`]))],examples:[],confuse:[`aurora-vs-rds`],azure:[{concept:`Azure SQL Database, Azure Database for MySQL/PostgreSQL`,aws:`Amazon RDS`,mapping:n(`Learn pairs Amazon RDS with Azure SQL Database, Azure Database for MySQL and Azure Database for PostgreSQL as managed relational database services, and notes you can also run SQL Server on Azure Virtual Machines.`,[`learn-databases`,`rds-what-is`],[`learn-databases|Azure provides managed services for several database engines that correspond to engines available through Amazon Relational Database Service (Amazon RDS).`,`learn-databases|These services include: Azure SQL Database Azure Database for MySQL Azure Database for PostgreSQL SQL Database in Microsoft Fabric`,`learn-databases|You can deploy other database engines, such as SQL Server, Oracle, and MySQL, on Azure Virtual Machine instances.`,`rds-what-is|Amazon Relational Database Service (Amazon RDS) is a web service that makes it easier to set up, operate, and scale a relational database in the AWS Cloud.`]),breaks:n(`Learn says to select by database engine first, then compare high availability, read replicas, scaling, maintenance, extensions and migration support. On AWS, RDS offers a choice of engines and Aurora is a separate MySQL- and PostgreSQL-compatible engine. Learn also pairs Aurora Serverless with SQL Database serverless and says these services use different scaling and billing models.`,[`learn-databases`,`aurora-serverless`,`database-decision`,`aurora-overview`],[`learn-databases|Select by database engine first. Then compare high availability, read replicas, scaling, maintenance, extensions, and migration support.`,`database-decision|Amazon RDS Relational Use when you need a fully managed relational database with your choice of six popular engines: PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`,`learn-databases|These services use different scaling and billing models.`,`learn-databases|SQL Database serverless can automatically scale compute and pause during inactivity.`,`aurora-serverless|Capacity is adjusted automatically based on application demand.`])},{concept:`Azure Cosmos DB for NoSQL`,aws:`Amazon DynamoDB`,mapping:n(`Learn pairs DynamoDB with Azure Cosmos DB for NoSQL: both distribute data by partition key and provide change streams.`,[`learn-databases`,`dynamodb-what-is`],[`learn-databases|Both services distribute data by partition key and provide change streams.`,`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`]),breaks:n(`Learn states that the consistency, indexing, query, transaction, capacity and pricing models differ, and says to plan application and data-model changes instead of assuming API compatibility. Consistency is a concrete example: Learn's Cosmos DB page says Cosmos DB offers five well-defined consistency levels, from strongest to weakest, while DynamoDB tables and local secondary indexes provide two read consistency options, eventually consistent (the default) and strongly consistent.`,[`learn-databases`,`dynamodb-capacity`,`learn-cosmos-consistency`,`dynamodb-read-consistency`],[`learn-databases|Their consistency, indexing, query, transaction, capacity, and pricing models differ.`,`learn-databases|Plan application and data-model changes instead of assuming API compatibility.`,`learn-cosmos-consistency|Cosmos DB offers five well-defined levels. From strongest to weakest, the levels are: Strong Bounded staleness Session Consistent prefix Eventual`,`dynamodb-read-consistency|Both tables and LSIs provide two read consistency options: eventually consistent (default) and strongly consistent reads.`,`dynamodb-capacity|In Amazon DynamoDB, you can choose between on-demand mode and provisioned mode for your tables to accommodate different workload requirements.`])},{concept:`Azure Database Migration Service`,aws:`AWS Database Migration Service (AWS DMS)`,mapping:n(`Learn pairs AWS DMS with Azure Database Migration Service, and says support varies by source, target and online or offline migration mode.`,[`learn-databases`,`dms-what-is`],[`learn-databases|Support varies by source, target, and online or offline migration mode.`,`dms-what-is|AWS DMS supports fully heterogeneous data migrations between the supported engines.`]),breaks:n(`Learn adds that database migration requires more than moving data: inventory engine features, stored procedures, extensions, indexes and consistency assumptions. The AWS side has a matching separate step: for a different engine, you use DMS Schema Conversion to convert the source schemas.`,[`learn-databases`,`dms-what-is`],[`learn-databases|Database migration requires more than moving data.`,`dms-what-is|To migrate to a different database engine, you can use DMS Schema Conversion.`],{newer:[`dms-schema-conversion`]})}]},s={building:`edge-link-terminal`,overview:[n(`This building is about where traffic enters your architecture and how outside networks reach it. Edge services (CloudFront and Global Accelerator) improve performance for users; connection options (Site-to-Site VPN, Direct Connect and PrivateLink) join your own networks or services to AWS; and the placement options (Regions, Local Zones, Outposts and Wavelength) are covered in the last section.`,[`cloudfront-what-is`,`ga-what-is`,`s2s-vpn`,`dx-what-is`,`privatelink-what-is`],[`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`ga-what-is|AWS Global Accelerator is a service in which you create accelerators to improve the performance of your applications for local and global users.`,`s2s-vpn|You can enable access to your remote devices from your VPC by creating an AWS Site-to-Site VPN (Site-to-Site VPN) connection`,`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`privatelink-what-is|AWS PrivateLink is a highly available, scalable technology that you can use to privately connect your VPC to services and resources as if they were in your VPC.`])],beyondProject:[n(`Your static site already uses CloudFront. The SAA step is knowing what CloudFront is for and where AWS Global Accelerator fits instead. CloudFront speeds up distribution of static and dynamic web content. Global Accelerator improves performance for applications over TCP or UDP by proxying packets at the edge to applications running in one or more AWS Regions, and AWS calls it a good fit for non-HTTP use cases and for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover. They are compared in the Don't confuse section below.`,[`cloudfront-what-is`,`ga-faq`],[`cloudfront-what-is|Amazon CloudFront is a web service that speeds up distribution of your static and dynamic web content, such as .html, .css, .js, and image files, to your users.`,`ga-faq|Global Accelerator improves performance for a wide range of applications over TCP or UDP by proxying packets at the edge to applications running in one or more AWS Regions.`,`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`])],bullets:[{id:`3.4-K1`,concepts:[n(`CloudFront caches content at edge locations and routes each request to the edge location with the lowest latency; it can serve origins such as S3 buckets, Elastic Load Balancing or API Gateway, and data transfer from your origin to CloudFront is always free when the origin is an AWS origin such as S3, Elastic Load Balancing or API Gateway.`,`cloudfront-what-is`,[`When a user requests content that you're serving with CloudFront, the request is routed to the edge location that provides the lowest latency (time delay), so that content is delivered with the best possible performance.`,`The data transfer from your origin to CloudFront is always free when using AWS origins like Amazon Simple Storage Service (Amazon S3), Elastic Load Balancing, or Amazon API Gateway.`]),n(`Global Accelerator provides static anycast IP addresses as fixed entry points and routes traffic over the AWS global network to the optimal regional endpoint based on health, client location and configured policies. It is a global service that supports endpoints in multiple Regions.`,[`ga-what-is`,`ga-how`],[`ga-how|The static IP addresses provided by AWS Global Accelerator serve as single fixed entry points for your clients.`,`ga-what-is|Global Accelerator is a global service that supports endpoints in multiple AWS Regions.`,`ga-what-is|For standard accelerators, Global Accelerator uses the AWS global network to route traffic to the optimal regional endpoint based on health, client location, and policies that you configure, which increases the availability of your applications.`]),n(`A custom routing accelerator lets you map one or more users to a specific destination among many destinations, for example a fleet of game servers.`,[`ga-what-is`,`ga-product`],[`ga-what-is|With a custom routing accelerator, you can map one or more users to a specific destination among many destinations.`,`ga-product|Low-latency gaming and media workloads Use custom routing to deterministically route traffic to a fleet of EC2 instances.`])],services:[`Amazon CloudFront`,`AWS Global Accelerator`],design:[n(`Cue: cache, lower origin load, static and dynamic web content → CloudFront; static IPs for allow-listing, deterministic routing independent of DNS, fast regional failover, or non-HTTP traffic over TCP or UDP → Global Accelerator.`,[`ga-product`,`ga-faq`,`cloudfront-expiration`,`cloudfront-what-is`],[`cloudfront-expiration|A longer duration also reduces the load on your origin.`,`cloudfront-what-is|Amazon CloudFront is a web service that speeds up distribution of your static and dynamic web content, such as .html, .css, .js, and image files, to your users.`,`ga-product|Global static IP Simplify allowlisting in enterprise firewalling and IoT use cases.`,`ga-product|Users can access your application endpoints through static IP addresses to enjoy deterministic routing independent of DNS.`,`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`])]},{id:`3.4-K4`,concepts:[n(`AWS Site-to-Site VPN connects a VPC to a remote network or device over IPsec VPN connections (AWS's Direct Connect page calls these internet-based VPN connections); each VPN connection includes two tunnels you can use simultaneously for high availability.`,[`s2s-vpn`,`dx-encryption`],[`s2s-vpn|You can enable access to your remote devices from your VPC by creating an AWS Site-to-Site VPN (Site-to-Site VPN) connection, and configuring routing to pass traffic through the connection.`,`s2s-vpn|Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`,`s2s-vpn|Each VPN connection includes two VPN tunnels which you can simultaneously use for high availability.`,`dx-encryption|This combination provides an IPsec-encrypted private connection that also reduces network costs, increases bandwidth throughput, and provides a more consistent network experience than internet-based VPN connections.`],{allow:[`two`]}),n(`AWS Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable, and you create virtual interfaces directly to public AWS services or to Amazon VPC, bypassing internet service providers in your network path. Direct Connect does not encrypt your traffic in transit by default; you can combine a Direct Connect connection with the Site-to-Site VPN when you need encryption.`,[`dx-what-is`,`dx-encryption`],[`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`dx-what-is|With this connection, you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`,`dx-encryption|With AWS Direct Connect and AWS Site-to-Site VPN, you can combine one or more AWS Direct Connect dedicated network connections with the Amazon VPC VPN.`]),n(`AWS PrivateLink privately connects a VPC to services and resources as if they were in the VPC, without an internet gateway, NAT device, public IP address, Direct Connect or Site-to-Site VPN connection. The full Direct Connect vs VPN comparison is in Transit Tariff, and Customs House covers VPC endpoints.`,`privatelink-what-is`,[`AWS PrivateLink is a highly available, scalable technology that you can use to privately connect your VPC to services and resources as if they were in your VPC.`,`You do not need to use an internet gateway, NAT device, public IP address, Direct Connect connection, or AWS Site-to-Site VPN connection to allow communication with the service or resource from your private subnets.`]),n(`AWS Transit Gateway is a network transit hub used to interconnect VPCs and on-premises networks; you can attach VPCs, a Direct Connect gateway and VPN connections to it (Grid Planning Office).`,`tgw-what-is`,[`AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`Attachments — You can attach the following: One or more VPCs A Connect SD-WAN/third-party network appliance An AWS Direct Connect gateway A peering connection with another transit gateway A VPN connection to a transit gateway`])],services:[`AWS Site-to-Site VPN`,`AWS Direct Connect`,`AWS PrivateLink`],design:[n(`Cue: IPsec-encrypted connection over the internet → Site-to-Site VPN; a connection that bypasses internet service providers → Direct Connect (add a VPN when the traffic must also be encrypted); private access to a service without an internet gateway, NAT device or public IP address → PrivateLink.`,[`s2s-vpn`,`dx-what-is`,`privatelink-what-is`,`dx-encryption`],[`s2s-vpn|Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`,`dx-what-is|With this connection, you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`,`privatelink-what-is|You do not need to use an internet gateway, NAT device, public IP address, Direct Connect connection, or AWS Site-to-Site VPN connection to allow communication with the service or resource from your private subnets.`])]},{id:`3.4-S3`,concepts:[n(`Placement starts with the Region: choose it for the users, the services available and the requirements; a Region close to the majority of your users lowers network latency.`,`regions-and-azs`,[`Also, you can lower network latency when you select a Region that is close to the majority of your users.`]),n(`AWS Outposts extends AWS infrastructure, services, APIs and tools to customer premises, for applications that need local access to AWS managed infrastructure for lower latency and local data processing.`,`outposts-what-is`,[`AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`,`By providing local access to AWS managed infrastructure, AWS Outposts enables customers to build and run applications on premises using the same programming interfaces as in AWS Regions, while using local compute and storage resources for lower latency and local data processing needs.`]),n(`AWS Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' networks, to deliver low latency to mobile devices and end users; you extend a VPC to one or more Wavelength Zones.`,`wavelength-what-is`,[`AWS Wavelength enables developers to build applications that require edge computing infrastructure to deliver low latency to mobile devices and end users or increase the resiliency of their existing edge applications.`,`Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`]),n(`AWS Local Zones places compute, storage, database and other select AWS resources close to large population and industry centers, so you can give your users low-latency access to your applications. AWS Outposts, by contrast, extends AWS infrastructure, services, APIs and tools to customer premises.`,[`local-zones`,`outposts-what-is`],[`local-zones|AWS Local Zones places compute, storage, database, and other select AWS resources close to large population and industry centers.`,`local-zones|You can use Local Zones to provide your users with low-latency access to your applications.`,`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`]),n(`Spread across Availability Zones inside the Region for resilience, and use Global Accelerator or Route 53 latency routing when users or resources are in several Regions.`,[`waf-multi-location`,`route53-routing`,`ga-what-is`],[`waf-multi-location|Distribute workload data and resources across multiple Availability Zones or, where necessary, across AWS Regions.`,`route53-routing|Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`,`ga-what-is|With a standard accelerator, you can improve availability of your internet applications that are used by a global audience.`])],services:[`Amazon CloudFront`,`AWS Global Accelerator`],design:[n(`Cue: a Region near most users → choose that Region for latency, and CloudFront for cacheable content; local data processing on premises → Outposts; low latency to users near large population and industry centers → Local Zones; mobile devices on a carrier network → Wavelength; non-HTTP traffic (gaming, IoT, VoIP) or HTTP that needs static IP addresses or fast regional failover → Global Accelerator.`,[`outposts-what-is`,`wavelength-what-is`,`local-zones`,`regions-and-azs`,`ga-faq`],[`outposts-what-is|By providing local access to AWS managed infrastructure, AWS Outposts enables customers to build and run applications on premises using the same programming interfaces as in AWS Regions, while using local compute and storage resources for lower latency and local data processing needs.`,`wavelength-what-is|AWS Wavelength enables developers to build applications that require edge computing infrastructure to deliver low latency to mobile devices and end users or increase the resiliency of their existing edge applications.`,`local-zones|You can use Local Zones to provide your users with low-latency access to your applications.`,`regions-and-azs|Also, you can lower network latency when you select a Region that is close to the majority of your users.`,`ga-faq|CloudFront improves performance for both cacheable content (such as images and videos) and dynamic content (such as API acceleration and dynamic site delivery).`,`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`])]}],cues:[e(`cache static content close to users and reduce origin load`,`Amazon CloudFront`,n(`Content is cached at edge locations, and a longer cache duration reduces the load on your origin.`,`cloudfront-expiration`,[`A longer duration also reduces the load on your origin.`])),e(`static IP addresses to allow-list, fast regional failover, or non-HTTP traffic such as gaming (UDP) or VoIP`,`AWS Global Accelerator`,n(`Global Accelerator suits non-HTTP use cases and HTTP use cases that require static IP addresses or deterministic, fast regional failover.`,`ga-faq`,[`Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`])),e(`low latency to users near a large population or industry center`,`AWS Local Zones`,n(`Local Zones place compute, storage and database resources close to large population and industry centers.`,`local-zones`,[`AWS Local Zones places compute, storage, database, and other select AWS resources close to large population and industry centers.`])),e(`dedicated private connection bypassing internet providers`,`AWS Direct Connect`,n(`Direct Connect bypasses internet service providers in your network path.`,`dx-what-is`,[`With this connection, you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`])),e(`IPsec VPN to AWS over the internet`,`AWS Site-to-Site VPN`,n(`Site-to-Site VPN supports IPsec VPN connections.`,`s2s-vpn`,[`Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`])),e(`compute and storage on premises with the same AWS APIs`,`AWS Outposts`,n(`Outposts extends AWS infrastructure, services, APIs and tools to customer premises.`,`outposts-what-is`,[`AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`])),e(`ultra-low latency for mobile devices at the carrier edge`,`AWS Wavelength`,n(`Wavelength deploys AWS compute and storage to the edge of communications service providers' networks.`,`wavelength-what-is`,[`Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`]))],examples:[],confuse:[`cloudfront-vs-global-accelerator`],azure:[{concept:`Azure Front Door`,aws:`Amazon CloudFront`,mapping:n(`Learn pairs CloudFront with Azure Front Door as content delivery network services, and lists Front Door against Global Accelerator for global anycast entry points on the provider's backbone network.`,[`learn-networking`,`cloudfront-what-is`],[`learn-networking|Content delivery networks CloudFront Azure Front Door Azure Front Door is a modern cloud content delivery network (CDN) service that provides high performance, scalability, and secure user experiences for your content and applications.`,`learn-networking|These services provide global anycast entry points on the provider's backbone network to improve application performance and availability across regions.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`]),breaks:n(`Learn describes Azure Front Door as operating at layer 7 with integrated CDN and WAF, while the Azure cross-region Load Balancer operates at layer 4 and closely matches the layer-4 behaviour of Global Accelerator.`,[`learn-networking`,`ga-what-is`],[`learn-networking|Azure Front Door operates at layer 7 (HTTP/HTTPS) with integrated CDN and WAF.`,`learn-networking|Azure cross-region Load Balancer operates at layer 4 for TCP/UDP, which closely matches AWS Global Accelerator's layer-4 behavior.`,`ga-what-is|Global Accelerator is a global service that supports endpoints in multiple AWS Regions.`])},{concept:`ExpressRoute and VPN Gateway`,aws:`AWS Direct Connect and AWS Site-to-Site VPN`,mapping:n(`Learn pairs Direct Connect with ExpressRoute, a dedicated private network connection from your local network to Azure, and notes both Azure and AWS offer site-to-site VPN connections.`,[`learn-networking`,`dx-what-is`],[`learn-networking|AWS Direct Connect can link a network directly to AWS. Azure provides similar site-to-site dedicated connections through ExpressRoute.`,`learn-networking|Both Azure and AWS offer site-to-site VPN connections.`,`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`]),breaks:n(`Learn says VPN Gateway offers higher throughput for certain configurations than Site-to-Site VPN. AWS documents its limits per tunnel (see Transit Tariff).`,[`learn-networking`,`vpn-tunnels`,`s2s-vpn`],[`learn-networking|They provide similar features, but there's a notable difference with performance.`,`learn-networking|VPN Gateway offers higher throughput for certain configurations`,`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default)`,`vpn-tunnels|Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel`])}]},c={building:`engine-works`,overview:[n(`Choosing compute for performance means matching the shape of the workload to the compute option and then sizing it. Amazon EC2 instance types are grouped in families by their compute, memory and storage capabilities; Lambda lets you size a function by its memory setting; AWS Batch and Amazon EMR cover batch and big-data processing; Fargate removes the servers from container workloads.`,[`ec2-instance-types`,`lambda-memory`,`batch-what-is`,`emr-what-is`,`fargate-ecs`],[`ec2-instance-types|Each instance type offers different compute, memory, and storage capabilities, and is grouped in an instance family based on these capabilities.`,`lambda-memory|Lambda allocates CPU power in proportion to the amount of memory configured.`,`batch-what-is|AWS Batch helps you to run batch computing workloads on the AWS Cloud.`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`])],beyondProject:[n(`Your visitor counter runs on Lambda. The SAA question is how to size it: Lambda allocates CPU power in proportion to the memory you configure, so memory is the setting that also controls CPU. You can configure memory between 128 MB and 10,240 MB, and at 1,769 MB a function has the equivalent of one vCPU.`,`lambda-memory`,[`Lambda allocates CPU power in proportion to the amount of memory configured.`,`You can configure memory between 128 MB and 10,240 MB in 1-MB increments.`,`At 1,769 MB, a function has the equivalent of one vCPU (one vCPU-second of credits per second).`])],bullets:[{id:`3.2-K1`,concepts:[n(`AWS Batch runs batch computing workloads on AWS. It removes the heavy lifting of configuring and managing the infrastructure, provisions resources in response to submitted jobs to eliminate capacity constraints, and automatically provisions compute and optimises the workload distribution based on the quantity and scale of the workloads.`,`batch-what-is`,[`AWS Batch helps you to run batch computing workloads on the AWS Cloud.`,`This service can efficiently provision resources in response to jobs submitted in order to eliminate capacity constraints, reduce compute costs, and deliver results quickly.`,`AWS Batch automatically provisions compute resources and optimizes the workload distribution based on the quantity and scale of the workloads.`]),n(`Amazon EMR is a managed cluster platform that simplifies running big data frameworks such as Apache Hadoop and Apache Spark to process and analyse vast amounts of data, and can also transform and move large amounts of data into and out of stores like Amazon S3 and Amazon DynamoDB.`,`emr-what-is`,[`Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`Amazon EMR also lets you transform and move large amounts of data into and out of other AWS data stores and databases, such as Amazon Simple Storage Service (Amazon S3) and Amazon DynamoDB.`]),n(`AWS Fargate lets you run containers without provisioning, configuring or scaling clusters of virtual machines: you package the application in containers, specify the CPU and memory requirements and launch it. (See Container Dock for ECS and EKS.)`,`fargate-ecs`,[`With AWS Fargate, you no longer have to provision, configure, or scale clusters of virtual machines to run containers.`,`When you run your tasks and services with Fargate, you package your application in containers, specify the CPU and memory requirements, define networking and IAM policies, and launch the application.`]),n(`The compute decision guide lists the choices: Amazon EC2 for resizable virtual servers, Elastic Beanstalk for deploying web applications, Lambda for serverless computing, ECS and EKS for container orchestration, and Fargate for serverless containers.`,`compute-decision`,[`These include Amazon EC2 for resizable virtual servers, Elastic Beanstalk for deploying web applications on your choice of a number of popular platforms, AWS Lambda for serverless computing, Amazon ECS and EKS for container orchestration, and AWS Fargate for serverless containers.`])],services:[`AWS Batch`,`Amazon EMR`,`AWS Fargate`,`Amazon EC2`,`AWS Lambda`],design:[n(`Cue to service: queued batch jobs that need compute provisioned for them → AWS Batch; Hadoop or Spark big-data processing → EMR; containers without servers → Fargate; serverless computing → Lambda; resizable virtual servers where you manage the instance → EC2.`,[`batch-what-is`,`emr-what-is`,`compute-decision`],[`compute-decision|These include Amazon EC2 for resizable virtual servers, Elastic Beanstalk for deploying web applications on your choice of a number of popular platforms, AWS Lambda for serverless computing, Amazon ECS and EKS for container orchestration, and AWS Fargate for serverless containers.`,`batch-what-is|AWS Batch removes the undifferentiated heavy lifting of configuring and managing the required infrastructure`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`])]},{id:`3.2-S3`,concepts:[n(`General purpose instances provide a balance of compute, memory and networking resources, ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`,`ec2-gp`,[`General purpose instances provide a balance of compute, memory, and networking resources.`,`These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`]),n(`Compute optimized instances are for compute intensive applications that benefit from high performance processors: batch processing, media transcoding, high performance web servers, high performance computing (HPC), scientific modelling, dedicated gaming servers, ad server engines and machine learning inference.`,`ec2-co`,[`Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`,`These instances are ideal for batch processing workloads, media transcoding, high performance web servers, high performance computing (HPC), scientific modeling, dedicated gaming servers, ad server engines, and machine learning inference.`]),n(`Memory optimized instances deliver fast performance for workloads that process large data sets in memory.`,`ec2-mo`,[`Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`]),n(`Storage optimized instances are for workloads that need high, sequential read and write access to very large data sets on local storage, and are optimised to deliver tens of thousands of low-latency random I/O operations per second (IOPS).`,`ec2-so`,[`Storage optimized instances are designed for workloads that require high, sequential read and write access to very large data sets on local storage.`,`They are optimized to deliver tens of thousands of low-latency, random I/O operations per second (IOPS) to applications.`]),n(`Accelerated computing instances use hardware accelerators or co-processors for functions such as floating point calculations, graphics processing or data pattern matching, more efficiently than software on CPUs.`,`ec2-ac`,[`Accelerated computing instances use hardware accelerators, or co-processors, to perform functions, such as floating point number calculations, graphics processing, or data pattern matching, more efficiently than is possible in software running on CPUs.`]),n(`Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline, governed by CPU credits. The baseline is designed for the majority of general purpose workloads such as web servers, small and medium databases and development and test environments.`,`ec2-instance-types`,[`Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline.`,`The baseline utilization and ability to burst are governed by CPU credits.`])],services:[`Amazon EC2`],design:[n(`Read the resource that limits the workload: CPU-bound → compute optimized; large in-memory data set → memory optimized; local disk I/O → storage optimized; GPUs or specialised hardware → accelerated; resources used in equal proportions → general purpose; a modest baseline with occasional bursts → burstable (T).`,[`ec2-instance-types`,`ec2-co`,`ec2-mo`,`ec2-so`,`ec2-ac`,`ec2-gp`],[`ec2-instance-types|Select an instance type based on the requirements of the application or software that you plan to run on your instance.`,`ec2-co|Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`,`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`,`ec2-so|Storage optimized instances are designed for workloads that require high, sequential read and write access to very large data sets on local storage.`,`ec2-ac|Accelerated computing instances use hardware accelerators, or co-processors, to perform functions, such as floating point number calculations, graphics processing, or data pattern matching, more efficiently than is possible in software running on CPUs.`,`ec2-gp|These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`,`ec2-instance-types|Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline.`])]},{id:`3.2-S4`,concepts:[n(`For Lambda, memory is the performance setting. Lambda allocates CPU power in proportion to the amount of memory configured, and you can increase or decrease memory and CPU power with the Memory setting. Raise memory when a function is CPU-bound or slow, and measure to find the right size.`,`lambda-memory`,[`Lambda allocates CPU power in proportion to the amount of memory configured.`,`You can increase or decrease the memory and CPU power allocated to your function using the Memory setting.`]),n(`Lambda also has a time limit: a single invocation can run for up to 15 minutes (a Lambda quota), or up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through event source mappings other than Amazon MQ and Amazon DocumentDB. Work that needs more time belongs elsewhere (Batch, Fargate or a workflow).`,`lambda-quotas`,[`Code can run for up to 15 minutes in a single invocation (up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through any event source mapping except Amazon MQ and Amazon DocumentDB)`],{newer:[`lambda-managed-instances`,`lambda-managed-instances-90min`]}),n(`For EC2 sizing, changing the instance type resizes the instance (the vertical-scaling move from Scaling Floodgate), and you start paying the rate of the new type.`,`ec2-resize`,[`If this is the case, you can resize your instance by changing its instance type.`,`When you change the instance type, you'll start paying the rate of the new instance type.`])],services:[`AWS Lambda`,`Amazon EC2`],design:[n(`Cue: Lambda function is CPU-bound and slow → increase its memory, which also increases CPU.`,`lambda-memory`,[`If a function is CPU, network or memory-bound, then increasing the memory setting can dramatically improve its performance.`,`Lambda allocates CPU power in proportion to the amount of memory configured.`])]}],cues:[e(`large data sets processed in memory`,`Memory optimized EC2 instances`,n(`Memory optimized instances are designed for workloads that process large data sets in memory.`,`ec2-mo`,[`Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`])),e(`compute-intensive: batch processing, transcoding, HPC, scientific modelling`,`Compute optimized EC2 instances`,n(`Compute optimized instances suit batch processing, media transcoding and HPC.`,`ec2-co`,[`These instances are ideal for batch processing workloads, media transcoding, high performance web servers, high performance computing (HPC), scientific modeling, dedicated gaming servers, ad server engines, and machine learning inference.`])),e(`high sequential read/write to very large local data sets, tens of thousands of IOPS`,`Storage optimized EC2 instances`,n(`Storage optimized instances target high sequential access to very large local data sets and low-latency random I/O.`,`ec2-so`,[`They are optimized to deliver tens of thousands of low-latency, random I/O operations per second (IOPS) to applications.`])),e(`GPUs, graphics processing, floating point calculations`,`Accelerated computing EC2 instances`,n(`Accelerated computing instances use hardware accelerators or co-processors.`,`ec2-ac`,[`Accelerated computing instances use hardware accelerators, or co-processors, to perform functions, such as floating point number calculations, graphics processing, or data pattern matching, more efficiently than is possible in software running on CPUs.`])),e(`balanced CPU, memory and networking, web servers`,`General purpose EC2 instances`,n(`General purpose instances balance compute, memory and networking.`,`ec2-gp`,[`General purpose instances provide a balance of compute, memory, and networking resources.`])),e(`job queue of batch workloads, provision compute automatically`,`AWS Batch`,n(`AWS Batch provisions resources in response to submitted jobs.`,`batch-what-is`,[`This service can efficiently provision resources in response to jobs submitted in order to eliminate capacity constraints, reduce compute costs, and deliver results quickly.`])),e(`Hadoop or Spark big data processing on managed clusters`,`Amazon EMR`,n(`EMR runs frameworks such as Hadoop and Spark on managed clusters.`,`emr-what-is`,[`Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`])),e(`Lambda function is CPU-bound or slow`,`Increase the function's memory setting`,n(`Lambda allocates CPU in proportion to memory.`,`lambda-memory`,[`Lambda allocates CPU power in proportion to the amount of memory configured.`]))],examples:[],confuse:[],azure:[{concept:`Azure Virtual Machines`,aws:`Amazon EC2 instance types`,mapping:n(`Learn pairs EC2 instance types with Azure Virtual Machines and says AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU and storage capabilities differ.`,[`learn-compute`,`ec2-instance-types`],[`learn-compute|AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU, and storage capabilities differ.`,`ec2-instance-types|Each instance type offers different compute, memory, and storage capabilities, and is grouped in an instance family based on these capabilities.`]),breaks:n(`Learn says AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU and storage capabilities differ. AWS defines the categories by family, such as general purpose instances that balance compute, memory and networking.`,[`learn-compute`,`ec2-gp`],[`learn-compute|AWS instance types and Azure VM sizes have similar categories, but the RAM, CPU, and storage capabilities differ.`,`ec2-gp|General purpose instances provide a balance of compute, memory, and networking resources.`])},{concept:`Azure Batch`,aws:`AWS Batch`,mapping:n(`Learn pairs AWS Batch with Azure Batch: managing compute-intensive work across a scalable collection of VMs.`,[`learn-compute`,`batch-what-is`],[`learn-compute|Azure Batch helps you manage compute-intensive work across a scalable collection of VMs.`,`batch-what-is|AWS Batch automatically provisions compute resources and optimizes the workload distribution based on the quantity and scale of the workloads.`]),breaks:n(`Learn pairs AWS Batch with Azure Batch for large-scale parallel and HPC applications; Amazon EMR has no Learn pairing. EMR is a managed cluster platform for big data frameworks such as Hadoop and Spark.`,[`emr-what-is`,`learn-compute`],[`learn-compute|Batch processing runs large-scale parallel and HPC applications efficiently in the cloud.`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`learn-compute|Azure Batch helps you manage compute-intensive work across a scalable collection of VMs.`])}]},l={building:`express-interchange`,overview:[n(`Elastic Load Balancing offers different load balancers for different traffic. Scaling Floodgate and Single-Point Watch explained why you use one; this building is about choosing among them. AWS describes each type by the layer of the Open Systems Interconnection (OSI) model it works at, and by features such as static IP addresses and PrivateLink support.`,[`elb-what-is`,`alb-intro`,`elb-features`],[`elb-what-is|Elastic Load Balancing automatically distributes your incoming traffic across multiple targets, such as EC2 instances, containers, and IP addresses, in one or more Availability Zones.`,`elb-features|Load Balancer type Layer 7 Layer 4 Layer 3 Gateway + Layer 4 Load Balancing Layer 4/7`,`alb-intro|Elastic Load Balancing supports the following load balancers: Application Load Balancers, Network Load Balancers, Gateway Load Balancers, and Classic Load Balancers.`])],bullets:[{id:`3.4-K3`,concepts:[n(`A Network Load Balancer works through listeners and target groups. A listener checks for connection requests from clients using the protocol and port you configure, and forwards them to a target group, which routes requests to one or more registered targets using the protocol and port you specify; health checks are configured per target group.`,`nlb-intro`,[`A listener checks for connection requests from clients, using the protocol and port that you configure, and forwards requests to a target group.`,`A target group routes requests to one or more registered targets, such as EC2 instances, using the protocol and the port number that you specify.`,`You can configure health checks on a per target group basis.`]),n(`An Application Load Balancer evaluates listener rules in priority order and can route requests to different target groups based on the content of the application traffic. Path conditions let you structure an application as smaller services and route to the correct service based on the URL; host conditions route on the host field in the HTTP header.`,`alb-intro`,[`After the load balancer receives a request, it evaluates the listener rules in priority order to determine which rule to apply, and then selects a target from the target group for the rule action.`,`This enables you to structure your application as smaller services, and route requests to the correct service based on the content of the URL.`,`You can configure rules for your listener that forward requests based on the host field in the HTTP header.`]),n(`Application Load Balancers provide native support for WebSockets and can use ACM-provided certificates for HTTPS listeners; they work with AWS WAF. WebSockets are not a reason to rule out a Network Load Balancer, since AWS lists WebSocket support for the Network Load Balancer as well.`,[`alb-listeners`,`alb-intro`,`elb-what-is`,`elb-features`],[`alb-listeners|Application Load Balancers provide native support for WebSockets.`,`elb-features|Preserve Source IP address ✔ ✔ ✔ - WebSockets ✔ ✔ ✔ -`,`alb-intro|AWS Certificate Manager — When you create an HTTPS listener, you can specify certificates provided by ACM.`,`elb-what-is|AWS WAF — You can use AWS WAF with your Application Load Balancer to allow or block requests based on the rules in a web access control list (web ACL).`]),n(`A Network Load Balancer node distributes traffic, by default, across the registered targets in its own Availability Zone only; if you enable cross-zone load balancing each node distributes across targets in all enabled zones. Enable more than one zone to increase fault tolerance.`,`nlb-intro`,[`By default, each load balancer node distributes traffic across the registered targets in its Availability Zone only.`,`If you enable cross-zone load balancing, each load balancer node distributes traffic across the registered targets in all enabled Availability Zones.`]),n(`The previous-generation Classic Load Balancer is still documented, but AWS recommends that you migrate to a current generation load balancer.`,`elb-what-is`,[`Classic Load Balancers are the previous generation of load balancers from Elastic Load Balancing.`,`We recommend that you migrate to a current generation load balancer.`])],services:[`Elastic Load Balancing (ELB)`],design:[n(`Cue: content-based rules (path, host), redirects or user authentication on the load balancer → Application Load Balancer; a fixed IP address or Elastic IP, raw TCP or UDP at very high volume → Network Load Balancer; a fleet of virtual appliances such as firewalls placed inline → Gateway Load Balancer.`,[`alb-intro`,`nlb-intro`,`gwlb-intro`,`elb-features`],[`alb-intro|This enables you to structure your application as smaller services, and route requests to the correct service based on the content of the URL.`,`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`,`nlb-intro|Network Load Balancer target groups support the TCP, UDP, TCP_UDP, TLS, QUIC, and TCP_QUIC protocols.`,`nlb-intro|It can handle millions of requests per second.`,`elb-features|If extreme performance and static IP is needed for your application, we recommend that you use a Network Load Balancer.`,`elb-features|Redirects ✔ - - - Fixed Response ✔ - - -`,`elb-features|User Authentication ✔ - - -`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`])]},{id:`3.4-S4`,concepts:[n(`Select by traffic type. Application Load Balancer: seventh-layer content-based routing, microservices behind paths or hosts, WAF. Network Load Balancer: fourth-layer TCP, UDP or TLS traffic at very high volume, and static IP addresses per zone with optional Elastic IPs. Gateway Load Balancer: third-layer, transparent insertion of firewalls, intrusion prevention and deep packet inspection appliances.`,[`alb-intro`,`nlb-intro`,`gwlb-intro`,`elb-what-is`],[`alb-intro|An Application Load Balancer functions at the application layer, the seventh layer of the Open Systems Interconnection (OSI) model.`,`nlb-intro|Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`nlb-intro|When you create an Internet-facing load balancer, you can optionally associate one Elastic IP address per subnet.`,`gwlb-intro|A Gateway Load Balancer operates at the third layer of the Open Systems Interconnection (OSI) model, the network layer.`,`elb-what-is|AWS WAF — You can use AWS WAF with your Application Load Balancer to allow or block requests based on the rules in a web access control list (web ACL).`]),n(`A Network Load Balancer can handle millions of requests per second and gives each enabled zone a network interface with a static IP address.`,`nlb-intro`,[`It can handle millions of requests per second.`,`Each load balancer node in the Availability Zone uses this network interface to get a static IP address.`]),n(`A Gateway Load Balancer endpoint is a VPC endpoint that provides private connectivity between virtual appliances in the service provider VPC and application servers in the service consumer VPC.`,`gwlb-intro`,[`A Gateway Load Balancer endpoint is a VPC endpoint that provides private connectivity between virtual appliances in the service provider VPC and application servers in the service consumer VPC.`]),n(`Two more selection facts. When extreme performance and static IP are needed, AWS recommends the Network Load Balancer; Global Accelerator also provides static IP addresses (anycast from the AWS edge network). A PrivateLink endpoint service requires either a Network Load Balancer or a Gateway Load Balancer in front of it.`,[`elb-features`,`ga-what-is`,`privatelink-service`],[`elb-features|If extreme performance and static IP is needed for your application, we recommend that you use a Network Load Balancer.`,`ga-what-is|By default, Global Accelerator provides you with static IP addresses that you associate with your accelerator.`,`ga-what-is|The static IP addresses are anycast from the AWS edge network.`,`privatelink-service|Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`],{allow:[`two`]}),n(`A Gateway Load Balancer maintains flow stickiness to a specific target appliance using 5-tuple (default), 3-tuple or 2-tuple, and it scales the virtual appliances with demand.`,`gwlb-intro`,[`It maintains flow stickiness to a specific target appliance using 5-tuple (default), 3-tuple, or 2-tuple.`,`It combines a transparent network gateway (that is, a single entry and exit point for all traffic) and distributes traffic while scaling your virtual appliances with the demand.`],{allow:[`two`]})],services:[`Elastic Load Balancing (ELB)`],design:[n(`Cue chain: HTTP/HTTPS with routing rules or WAF → ALB; TCP/UDP, extreme performance or static IPs → NLB; inline third-party appliance fleet → GWLB; exposing a service to other VPCs or accounts through PrivateLink → an NLB (or GWLB) in front of it. If two answers seem possible, compare the layer each operates at and the features above.`,[`alb-intro`,`nlb-intro`,`gwlb-intro`,`privatelink-service`],[`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`,`nlb-intro|Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`,`privatelink-service|Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`])]}],cues:[e(`route /images to one target group and /api to another`,`Application Load Balancer path-based routing`,n(`Path conditions route requests to the correct service based on the URL.`,`alb-intro`,[`This enables you to structure your application as smaller services, and route requests to the correct service based on the content of the URL.`])),e(`route by host name (api.example.com vs www.example.com)`,`Application Load Balancer host-based routing`,n(`Host conditions forward requests based on the host field in the HTTP header.`,`alb-intro`,[`You can configure rules for your listener that forward requests based on the host field in the HTTP header.`])),e(`static IP addresses / Elastic IP for the load balancer; TCP or UDP`,`Network Load Balancer`,n(`A Network Load Balancer gives each enabled zone a static IP address and allows Elastic IPs on internet-facing balancers.`,`nlb-intro`,[`When you create an Internet-facing load balancer, you can optionally associate one Elastic IP address per subnet.`])),e(`millions of requests per second, fourth layer`,`Network Load Balancer`,n(`A Network Load Balancer works at the fourth layer and can handle millions of requests per second.`,`nlb-intro`,[`It can handle millions of requests per second.`])),e(`expose your service to other VPCs through AWS PrivateLink`,`A Network Load Balancer (or Gateway Load Balancer) as the endpoint service front end`,n(`Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`,`privatelink-service`,[`Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`])),e(`deploy firewall or intrusion detection virtual appliances behind a transparent gateway`,`Gateway Load Balancer`,n(`Gateway Load Balancers deploy, scale and manage virtual appliances.`,`gwlb-intro`,[`Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`])),e(`integrate AWS WAF with the load balancer`,`Application Load Balancer`,n(`AWS WAF can be used with an Application Load Balancer.`,`elb-what-is`,[`AWS WAF — You can use AWS WAF with your Application Load Balancer to allow or block requests based on the rules in a web access control list (web ACL).`])),e(`WebSocket connections combined with path or host routing rules`,`Application Load Balancer`,n(`Application Load Balancers provide native support for WebSockets, and their listener rules route on content.`,[`alb-listeners`,`alb-intro`],[`alb-listeners|Application Load Balancers provide native support for WebSockets.`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`]))],examples:[],confuse:[`alb-nlb-gwlb`],azure:[{concept:`Azure Load Balancer`,aws:`Network Load Balancer`,mapping:n(`Learn pairs the AWS Network Load Balancer with Azure Load Balancer, which provides the same network-level capabilities for TCP or UDP traffic.`,[`learn-networking`,`nlb-intro`],[`learn-networking|Load Balancer provides the same network layer 4 capabilities as the AWS Network Load Balancer, so you can distribute traffic for multiple VMs at the network level.`,`learn-networking|Azure Load Balancer load balances traffic at layer 4 (TCP or UDP).`,`nlb-intro|Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`]),breaks:n(`Learn's networking comparison pairs Azure Load Balancer with the Network Load Balancer and Application Gateway with the Application Load Balancer, and has no pairing for the AWS Gateway Load Balancer. Azure documents a Gateway Load Balancer SKU of Azure Load Balancer for third-party network virtual appliances; the AWS Gateway Load Balancer deploys, scales and manages virtual appliances such as firewalls.`,[`gwlb-intro`,`learn-networking`,`learn-azure-gwlb`],[`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`,`learn-networking|Load Balancer provides the same network layer 4 capabilities as the AWS Network Load Balancer, so you can distribute traffic for multiple VMs at the network level.`,`learn-networking|Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`,`learn-azure-gwlb|Gateway Load Balancer is a SKU of the Azure Load Balancer portfolio designed for high performance and high availability scenarios with third-party Network Virtual Appliances (NVAs).`])},{concept:`Azure Application Gateway`,aws:`Application Load Balancer`,mapping:n(`Learn pairs Azure Application Gateway with the AWS Application Load Balancer for application-level rule-based routing.`,[`learn-networking`,`alb-intro`],[`learn-networking|Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`,`alb-intro|An Application Load Balancer functions at the application layer, the seventh layer of the Open Systems Interconnection (OSI) model.`]),breaks:n(`The AWS Application Load Balancer works at the application layer, the seventh layer, and can forward requests on listener rules such as the host field in the HTTP header. Learn describes Azure Application Gateway as application-level rule-based routing comparable to that of the Application Load Balancer.`,[`alb-intro`,`learn-networking`],[`alb-intro|An Application Load Balancer functions at the application layer, the seventh layer of the Open Systems Interconnection (OSI) model.`,`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`,`learn-networking|Application Gateway provides application-level rule-based routing comparable to that of the AWS Application Load Balancer.`])}]},u={building:`express-rail-hub`,overview:[n(`A queue between components lets each side scale at its own pace. The queue decouples sending and receiving, and a pool of consumers drains it; you scale the consumers on the work waiting in the queue. Publish/subscribe adds the other shape: one message pushed to many receivers. Message Quay compares SQS, SNS, EventBridge and Kinesis; this building is about scaling with them.`,[`sns-sqs-fanout`,`asg-sqs`],[`sns-sqs-fanout|It decouples sending and receiving components—without requiring each component to be available at the same time.`,`sns-sqs-fanout|Amazon SNS lets applications send time-critical messages to multiple subscribers through a “push” mechanism.`,`asg-sqs|You can scale your Auto Scaling group in response to changes in system load in an Amazon Simple Queue Service (Amazon SQS) queue.`,`asg-sqs|To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`])],bullets:[{id:`3.2-K3`,concepts:[n(`Queuing: Amazon SQS is a message queue service that distributed applications use to exchange messages through a polling model. It decouples sending and receiving components without requiring each component to be available at the same time. Standard queues give at-least-once delivery, may deliver more than one copy of a message, and messages may occasionally arrive out of order; FIFO queues strictly preserve order and deliver each message once.`,[`sns-sqs-fanout`,`sqs-standard`,`sqs-fifo`],[`sns-sqs-fanout|Amazon SQS is a message queue service that distributed applications use to exchange messages through a polling model.`,`sqs-standard|Standard queues ensure at-least-once message delivery, but due to the highly distributed architecture, more than one copy of a message might be delivered, and messages may occasionally arrive out of order.`,`sqs-fifo|The order in which messages are sent and received is strictly preserved and a message is delivered once and remains unavailable until a consumer processes and deletes it.`]),n(`Publish/subscribe: Amazon SNS lets applications send time-critical messages to multiple subscribers through a push mechanism, which removes the need to check or poll for updates.`,`sns-sqs-fanout`,[`Amazon SNS lets applications send time-critical messages to multiple subscribers through a “push” mechanism.`,`This removes the need to check or “poll” for updates.`]),n(`Using SNS and SQS together, messages reach applications that need instant notification of an event, and the messages also persist in an SQS queue for other consumers to process later. This is the fanout pattern.`,`sns-sqs-fanout`,[`When you use Amazon SNS and Amazon SQS together, messages reach applications that need instant notification of an event.`,`The messages also persist in an Amazon SQS queue for other applications to process later.`]),n(`Some SQS settings matter for consumers. The {{term:visibility-timeout}} hides a received message from other consumers while you work on it. Long polling queries all servers and responds once a message is available, which can reduce the number of empty responses and potentially lower costs, compared with short polling (the default).`,[`sqs-visibility`,`sqs-polling`],[`sqs-visibility|This invisibility is controlled by the visibility timeout, which ensures that other consumers cannot process the same message while you are working on it.`,`sqs-polling|Long polling – ReceiveMessage queries all servers for messages, sending a response once at least one message is available, up to the specified maximum.`,`sqs-polling|This option can reduce the number of empty responses and potentially lower costs.`,`sqs-polling|Short polling (default) – The ReceiveMessage request queries a subset of servers (based on a weighted random distribution) to find available messages and sends an immediate response, even if no messages are found.`])],services:[`Amazon SQS`,`Amazon SNS`],design:[n(`Cue: workers pull when ready and the order does not matter → standard queue; order and no duplicates matter → FIFO queue; many systems must react to the same event → SNS (fanning out to SQS queues subscribed to the topic).`,[`sqs-standard`,`sqs-fifo`,`sns-sqs-fanout`],[`sqs-standard|Standard queues ensure at-least-once message delivery, but due to the highly distributed architecture, more than one copy of a message might be delivered, and messages may occasionally arrive out of order.`,`sqs-fifo|FIFO (First-In-First-Out) queues have all the capabilities of the standard queues, but are designed to enhance messaging between applications when the order of operations and events is critical, or where duplicates can't be tolerated.`,`sns-sqs-fanout|When you subscribe an Amazon SQS queue to an Amazon SNS topic, you can publish a message to the topic and Amazon SNS sends an Amazon SQS message to the subscribed queue.`])]},{id:`3.2-S1`,concepts:[n(`Decoupling lets a producer tier and a consumer tier scale independently. The AWS example is a web app that accepts image uploads and places the raw data in an SQS queue, while an Auto Scaling group of EC2 instances processes and publishes the images. If the number of uploads varies over time, use dynamic scaling on the consumer group.`,`asg-sqs`,[`The app places the raw bitmap data of the images in an SQS queue for processing.`,`The architecture for this scenario works well if the number of image uploads doesn't vary over time. But if the number of uploads changes over time, you might consider using dynamic scaling to scale the capacity of your Auto Scaling group.`]),n(`The scaling metric for queue consumers is the backlog per instance, not the raw queue length, because a policy that targets only the number of messages in the queue does not account for the number of instances available. A target tracking policy based on a custom SQS queue metric lets dynamic scaling adjust to the demand curve more effectively.`,`asg-sqs`,[`A policy that targets only the number of messages in the queue does not account for the number of instances available.`,`Set the target value to the acceptable backlog per instance that you want to maintain.`,`To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`,`If you use a target tracking scaling policy based on a custom Amazon SQS queue metric, dynamic scaling can adjust to the demand curve of your application more effectively.`]),n(`Amazon SQS stores each message redundantly in multiple Availability Zones before acknowledging it, and the queue decouples sending and receiving without requiring each component to be available at the same time, so a burst of messages waits in the queue until consumers have capacity.`,[`sqs-standard`,`sns-sqs-fanout`],[`sqs-standard|Amazon SQS redundantly stores the message in multiple availability zones (AZs) before acknowledging it.`,`sns-sqs-fanout|It decouples sending and receiving components—without requiring each component to be available at the same time.`]),n(`Messages that are not processed successfully can be moved to a dead-letter queue (DLQ), and the idempotent processing principle keeps retries safe.`,[`sqs-dlq`,`waf-idempotent`],[`sqs-dlq|Amazon SQS supports dead-letter queues (DLQs), which source queues can target for messages that are not processed successfully.`,`waf-idempotent|To do this, clients can issue API requests with an idempotency token, which is used whenever the request is repeated.`])],services:[`Amazon SQS`,`Amazon SNS`,`Amazon EC2 Auto Scaling`],design:[n(`Pattern for "components must scale independently" or "traffic spikes overwhelm the processing tier": put an SQS queue between the tiers and scale the consumers on queue backlog.`,`asg-sqs`,[`There are some scenarios where you might think about scaling in response to activity in an Amazon SQS queue.`,`To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`])]}],cues:[e(`spikes in requests overwhelm the processing tier; tiers should scale independently`,`Insert an SQS queue and scale consumers on queue backlog`,n(`The AWS scaling example puts image data in an SQS queue and scales the processing group dynamically.`,`asg-sqs`,[`The app places the raw bitmap data of the images in an SQS queue for processing.`])),e(`order of operations is critical and duplicates cannot be tolerated`,`SQS FIFO queue`,n(`FIFO queues preserve order and avoid duplicates.`,`sqs-fifo`,[`FIFO (First-In-First-Out) queues have all the capabilities of the standard queues, but are designed to enhance messaging between applications when the order of operations and events is critical, or where duplicates can't be tolerated.`])),e(`push one message to many subscribers`,`Amazon SNS (fanning out to SQS queues)`,n(`SNS pushes time-critical messages to multiple subscribers.`,`sns-sqs-fanout`,[`Amazon SNS lets applications send time-critical messages to multiple subscribers through a “push” mechanism.`])),e(`reduce empty receives and polling cost`,`SQS long polling`,n(`Long polling can reduce empty responses and potentially lower costs.`,`sqs-polling`,[`This option can reduce the number of empty responses and potentially lower costs.`])),e(`two consumers must not process the same message at once`,`SQS visibility timeout`,n(`The visibility timeout stops other consumers processing a message you are working on.`,`sqs-visibility`,[`This invisibility is controlled by the visibility timeout, which ensures that other consumers cannot process the same message while you are working on it.`]))],examples:[],confuse:[]},d={building:`freight-depot`,overview:[n(`This building turns the storage types of Cargo Hall into performance and scale decisions: which service meets the I/O demand, which one grows with the business, and how on-premises systems reach AWS storage through a gateway. The detailed EBS, EFS and FSx comparison is in Storage Market.`,[`storage-decision`,`s3-performance`,`efs-what-is`],[`storage-decision|You can select from block, file, and object storage services as well as cloud data migration options for your workload.`,`s3-performance|There are no limits to the number of prefixes in a bucket.`,`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`])],beyondProject:[n(`Your static site uses S3 as object storage. SAA asks how it behaves at scale: S3 performance scales by spreading requests across prefixes, and S3 can store any amount of data. It also asks when S3 is the wrong tool: block storage (EBS) is direct-attached to a compute instance, and a file system that many clients mount and share needs file storage (EFS or FSx).`,[`s3-performance`,`s3-what-is`,`storage-decision`,`efs-what-is`],[`s3-performance|For example, your application can achieve at least 3,500 PUT/COPY/POST/DELETE or 5,500 GET/HEAD requests per second per partitioned Amazon S3 prefix.`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`storage-decision|Block storage offers high-performance storage that is direct-attached to a compute instance with low-latency access`,`storage-decision|File-based storage is natively mountable from virtually any operating system using industry-standard protocols like NFS and SMB.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`])],bullets:[{id:`3.1-K1`,concepts:[n(`AWS Storage Gateway connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure. It offers file-based (S3 File Gateway and FSx File Gateway), volume-based (Volume Gateway) and tape-based (Tape Gateway) solutions. FSx File Gateway is no longer available to new customers, so the file gateway to choose for a new design is S3 File Gateway.`,[`storage-gateway-docs`,`sgw-volume`,`sgw-fsx-file`],[`storage-gateway-docs|AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`,`sgw-volume|AWS Storage Gateway offers file-based (S3 File Gateway and FSx File Gateway), volume-based (Volume Gateway), and tape-based (Tape Gateway) storage solutions.`,`sgw-fsx-file|Amazon FSx File Gateway is no longer available to new customers.`]),n(`S3 File Gateway supports a file interface into Amazon S3: applications store and retrieve files directly using NFS version 3 or 4.1, or using SMB version 2 and 3, and you can think of it as a file system mount on S3. It provides a cost-effective alternative to on-premises storage.`,`sgw-file-s3`,[`With a S3 File Gateway, you can do the following: You can store and retrieve files directly using the NFS version 3 or 4.1 protocol.`,`You can store and retrieve files directly using the SMB file system version, 2 and 3 protocol.`,`You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`A S3 File Gateway simplifies file storage in Amazon S3, integrates to existing applications through industry-standard file system protocols, and provides a cost-effective alternative to on-premises storage.`]),n(`Volume Gateway provides cloud-backed storage volumes that you can mount as iSCSI devices from your on-premises application servers. Tape Gateway provides cloud-backed virtual tape storage, so you can archive backup data durably in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`,[`sgw-volume`,`sgw-tape`],[`sgw-volume|Volume Gateway provides cloud-backed storage volumes that you can mount as Internet Small Computer System Interface (iSCSI) devices from your on-premises application servers.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`,`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`]),n(`Amazon FSx File Gateway is no longer available to new customers; existing customers can continue to use it normally. Do not choose it for a new design.`,`sgw-fsx-file`,[`Amazon FSx File Gateway is no longer available to new customers.`,`Existing customers of FSx File Gateway can continue to use the service normally.`],{status:`closed`})],services:[`AWS Storage Gateway`],design:[n(`Match the on-premises protocol to the gateway: NFS or SMB file shares backed by S3 → S3 File Gateway; block volumes over iSCSI → Volume Gateway; virtual tape storage for archiving backup data → Tape Gateway. Bulk transfers are covered in Transfer Dock.`,[`sgw-file-s3`,`sgw-volume`,`sgw-tape`],[`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`sgw-volume|Volume Gateway provides cloud-backed storage volumes that you can mount as Internet Small Computer System Interface (iSCSI) devices from your on-premises application servers.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`,`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`])]},{id:`3.1-K2`,concepts:[n(`Amazon S3 stores any amount of data as objects for uses such as data lakes, websites, mobile applications, backup and restore, archive and big data analytics. Amazon EFS provides serverless, elastic file storage shared over NFS. Amazon EBS provides block volumes attached to EC2 instances.`,[`s3-what-is`,`efs-what-is`,`ebs-what-is`],[`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`,`ebs-what-is|Amazon Elastic Block Store (Amazon EBS) provides scalable, high-performance block storage resources that can be used with Amazon Elastic Compute Cloud (Amazon EC2) instances.`]),n(`For container workloads on Amazon EKS you can attach file and block storage through Container Storage Interface (CSI) drivers, such as the Amazon EFS CSI driver and the Amazon EBS CSI driver.`,`storage-decision`,[`For container workloads, you can provide file, block, and object access to workloads on Amazon EKS: Attach file and block storage through Container Storage Interface (CSI) drivers, such as the Amazon EFS CSI driver and the Amazon EBS CSI driver.`]),n(`Amazon FSx for Lustre is a high-performance file system for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing and financial modeling, and you can link its file systems to data repositories on Amazon S3. EBS Multi-Attach is an exception to one-instance block storage: it lets you attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances in the same Availability Zone.`,[`fsx-lustre`,`ebs-multi-attach`],[`fsx-lustre|You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`,`fsx-lustre|You can link FSx for Lustre file systems to data repositories on Amazon S3 or to on-premises data stores.`,`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`],design:[n(`Pick the service by access method first (API objects, mounted shared files, attached disk), then tune with the performance and scale facts below.`,`storage-decision`,[`Protocols play a crucial role when considering AWS storage services as they determine how data is accessed, transferred, and managed within the storage environment.`])]},{id:`3.1-K3`,concepts:[n(`Object, file and block are the storage types: object storage manages data as objects accessed through an API and suits read-heavy workloads, block storage is direct-attached high-performance storage with low-latency access, and file storage is a hierarchy of files and folders mountable over NFS or SMB. Cargo Hall has the full definitions.`,`storage-decision`,[`Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`,`Block storage offers high-performance storage that is direct-attached to a compute instance with low-latency access, making it suitable for applications that require fast and consistent I/O operations.`,`File-based storage is natively mountable from virtually any operating system using industry-standard protocols like NFS and SMB.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`],design:[n(`The characteristics to compare: access method, latency, shareability (usually one instance for block, with EBS Multi-Attach as the exception for io1 and io2 volumes in one Availability Zone; many clients for file; many applications by API for object), and scale.`,[`storage-decision`,`ebs-multi-attach`],[`storage-decision|Applications and workloads requiring shared read and write access across multiple Amazon EC2 instances or containers, or from multiple on-premises servers, such as team file shares, highly available enterprise applications, analytics workloads, and ML training.`,`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`])]},{id:`3.1-S1`,concepts:[n(`S3 request performance scales by prefix: an application can achieve at least 3,500 PUT/COPY/POST/DELETE or 5,500 GET/HEAD requests per second per partitioned prefix, there are no limits to the number of prefixes in a bucket, and you can scale writes and reads by using multiple prefixes in parallel. "At least" matters: AWS documents these as floors, not ceilings.`,`s3-performance`,[`For example, your application can achieve at least 3,500 PUT/COPY/POST/DELETE or 5,500 GET/HEAD requests per second per partitioned Amazon S3 prefix.`,`There are no limits to the number of prefixes in a bucket.`,`Similarly, you can scale write operations by writing to multiple prefixes.`]),n(`Multipart upload and S3 Transfer Acceleration both help S3 transfer performance. Multipart upload is a best practice for objects that are 100 MB or larger, and parts can be uploaded in parallel to improve throughput. S3 Transfer Acceleration is a bucket-level feature for fast transfers of files over long distances between a client and an S3 general purpose bucket.`,[`s3-multipart`,`s3-transfer-acceleration`],[`s3-multipart|It's a best practice to use multipart upload for objects that are 100 MB or larger instead of uploading them in a single operation.`,`s3-multipart|Improved throughput – You can upload parts in parallel to improve throughput.`,`s3-transfer-acceleration|Amazon S3 Transfer Acceleration is a bucket-level feature that enables fast, easy, and secure transfers of files over long distances between your client and an S3 general purpose bucket.`]),n(`EBS SSD volume types: General Purpose SSD (gp3) suits transactional workloads, virtual desktops, medium-sized single-instance databases, low-latency interactive applications, boot volumes and development and test. Provisioned IOPS SSD (io2 Block Express) is for workloads that need consistent sub-millisecond latency, sustained IOPS performance, and I/O-intensive database workloads.`,`ebs-volume-types`,[`Transactional workloadsVirtual desktopsMedium-sized, single-instance databasesLow-latency interactive applicationsBoot volumesDevelopment and test environments`,`Consistent sub-millisecond latency with average latency under 500 microseconds`,`I/O-intensive database workloads`]),n(`EBS HDD volume types are optimised for large streaming workloads where throughput is the dominant performance attribute: Throughput Optimized HDD (st1) for big data, data warehouses and log processing, and Cold HDD (sc1) for infrequently accessed data where the lowest storage cost matters.`,`ebs-volume-types`,[`HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`,`Big data Data warehouses Log processing Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`]),n(`EFS performance is shaped by the file system type (Regional or One Zone), the performance mode (General Purpose or Max I/O) and the throughput mode (Elastic, Provisioned or Bursting). Max I/O has higher per-operation latencies than General Purpose, and AWS recommends General Purpose for faster performance.`,`efs-performance`,[`The following configurations impact the performance of an Amazon EFS file system: File system type – Regional or One ZonePerformance mode – General Purpose or Max I/O ImportantMax I/O performance mode has higher per-operation latencies than General Purpose performance mode.`,`For faster performance, we recommend always using General Purpose performance mode.`,`Throughput mode – Elastic, Provisioned, or Bursting`],{newer:[`efs-elastic-throughput`]})],services:[`Amazon S3`,`Amazon EBS`,`Amazon EFS`],design:[n(`Cue to configuration: an I/O-intensive database on EC2 → Provisioned IOPS SSD; a general boot or dev volume → General Purpose SSD; sequential big-data, data warehouse or log-processing throughput → st1; infrequently accessed data where the lowest storage cost matters → sc1; very many requests to S3 → spread across prefixes.`,[`ebs-volume-types`,`s3-performance`],[`ebs-volume-types|I/O-intensive database workloads`,`ebs-volume-types|Transactional workloadsVirtual desktopsMedium-sized, single-instance databasesLow-latency interactive applicationsBoot volumesDevelopment and test environments`,`s3-performance|Similarly, you can scale write operations by writing to multiple prefixes.`,`s3-performance|You can increase your read or write performance by using parallelization.`])]},{id:`3.1-S2`,concepts:[n(`S3 stores any amount of data, and EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files. EBS volumes have a defined size range per type, and with Elastic Volumes you can increase the volume size, change the volume type or adjust performance of an EBS volume.`,[`s3-what-is`,`efs-what-is`,`ebs-volume-types`,`ebs-modify`],[`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`,`ebs-volume-types|Volume size 1 GiB - 64 TiB 1 GiB - 16 TiB 4 GiB - 64 TiB 4 GiB - 16 TiB`,`ebs-modify|With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`]),n(`Planning for future needs also means choosing storage that does not need provisioning ahead of time: EFS lets you share file data without provisioning or managing storage capacity and performance.`,`efs-what-is`,[`Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`])],services:[`Amazon S3`,`Amazon EFS`,`Amazon EBS`],design:[n(`Cue: capacity unknown and growing, shared by many clients → EFS or S3; a sized volume attached to an instance → EBS (Elastic Volumes lets you increase its size when needed).`,[`efs-what-is`,`ebs-modify`],[`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`,`ebs-modify|With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`])]}],cues:[e(`on-premises application mounts NFS or SMB shares that are stored in S3`,`S3 File Gateway`,n(`S3 File Gateway lets applications store and retrieve files over NFS or SMB directly in S3.`,`sgw-file-s3`,[`With a S3 File Gateway, you can do the following: You can store and retrieve files directly using the NFS version 3 or 4.1 protocol.`,`You can store and retrieve files directly using the SMB file system version, 2 and 3 protocol.`])),e(`on-premises servers need iSCSI block volumes backed by the cloud`,`Volume Gateway`,n(`Volume Gateway provides cloud-backed storage volumes mounted as iSCSI devices.`,`sgw-volume`,[`Volume Gateway provides cloud-backed storage volumes that you can mount as Internet Small Computer System Interface (iSCSI) devices from your on-premises application servers.`])),e(`replace a physical tape library for backups`,`Tape Gateway`,n(`Tape Gateway provides cloud-backed virtual tape storage for archiving backup data.`,`sgw-tape`,[`Tape Gateway provides cloud-backed virtual tape storage.`])),e(`I/O-intensive database on EC2 needs sustained IOPS and low latency`,`EBS Provisioned IOPS SSD (io2)`,n(`Provisioned IOPS SSD is for workloads that need consistent sub-millisecond latency and sustained IOPS.`,`ebs-volume-types`,[`I/O-intensive database workloads`])),e(`big-data scans, data warehouse or log processing, throughput-oriented`,`EBS Throughput Optimized HDD (st1)`,n(`HDD volumes are optimised for large streaming workloads where throughput is dominant; st1 use cases are big data, data warehouses and log processing.`,`ebs-volume-types`,[`HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`,`Use cases Big data Data warehouses Log processing`])),e(`infrequently accessed data on EBS, lowest storage cost is important`,`EBS Cold HDD (sc1)`,n(`Cold HDD suits throughput-oriented storage for infrequently accessed data and scenarios where the lowest storage cost is important.`,`ebs-volume-types`,[`Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`])),e(`very high S3 request rate`,`Spread requests across multiple prefixes`,n(`S3 performance scales per prefix and a bucket can have any number of prefixes.`,`s3-performance`,[`There are no limits to the number of prefixes in a bucket.`])),e(`shared storage that grows automatically without provisioning`,`Amazon EFS`,n(`EFS grows and shrinks automatically as you add and remove files.`,`efs-what-is`,[`Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`]))],examples:[],confuse:[],azure:[{concept:`Azure Blob storage`,aws:`Amazon S3`,mapping:n(`Learn compares Azure Blob Storage (any type of text or binary data) with S3 and lists S3 uses such as cloud applications, content distribution, backup, archive, immutable storage, disaster recovery and big data analytics.`,[`learn-storage`,`s3-what-is`],[`learn-storage|Azure Blob Storage stores any type of text or binary data, such as a document, media file, or application installer.`,`learn-storage|Simple Storage Service (S3) Blob Storage Object storage service for use cases that include cloud applications, content distribution, backup, archive, immutable storage, disaster recovery, and big data analytics.`,`s3-what-is|Amazon S3 is an object storage service that stores data as objects, hierarchical data, or tabular data within buckets.`]),breaks:n(`Learn says Blob Storage serves the same purpose as AWS S3, and that the Azure equivalent of EBS is managed disks, which are not part of a storage account. On AWS, S3 performance is described per partitioned prefix, at least 3,500 write or 5,500 read requests per second.`,[`s3-performance`,`learn-storage`],[`s3-performance|For example, your application can achieve at least 3,500 PUT/COPY/POST/DELETE or 5,500 GET/HEAD requests per second per partitioned Amazon S3 prefix.`,`learn-storage|Blob Storage is object storage, so it serves the same purpose as AWS S3.`,`learn-storage|The Azure equivalent of EBS is managed disks, which aren't part of a storage account.`])},{concept:`Azure Files`,aws:`Amazon EFS`,mapping:n(`Learn pairs Azure Files with Amazon EFS and FSx as shared storage: Azure Files provides shared storage for applications, and Learn says to use it in a way similar to EFS or FSx for Windows File Server.`,[`learn-storage`,`efs-what-is`],[`learn-storage|Azure Files provides shared storage for applications.`,`learn-storage|Use Azure Files in a way that's similar to how you use EFS or FSx for Windows File Server.`,`learn-storage|Various shared storage services that AWS provides, like Amazon Elastic File System (EFS) and the Amazon FSx family of managed file systems.`,`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`]),breaks:n(`Learn pairs S3 File Gateway with Azure Data Box Gateway and Azure File Sync (on-premises, locally cached NFS and SMB file shares that are cloud-backed), not with EFS. Amazon FSx File Gateway has no Learn pairing, and AWS says it is no longer available to new customers.`,[`learn-storage`,`sgw-file-s3`,`sgw-fsx-file`],[`learn-storage|Hybrid storage AWS service Azure service Description AWS Storage Gateway: S3 File Gateway Azure Data Box Gateway, Azure File Sync Provides on-premises, locally cached NFS and SMB file shares that are cloud-backed.`,`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`sgw-fsx-file|Amazon FSx File Gateway is no longer available to new customers.`])},{concept:`Azure managed disks`,aws:`Amazon EBS`,mapping:n(`Learn pairs EBS volume types with Azure managed disk types by use: gp2/gp3 with Standard SSD for web servers and dev/test, gp2 with Premium SSD, gp3 with Premium SSD v2, and io2 with Ultra Disk for IO-intensive workloads.`,[`learn-storage`,`ebs-volume-types`],[`learn-storage|gp2/gp3 Standard SSD Web servers and lightly used application servers or dev/test environments Yes`,`learn-storage|gp2 Premium SSD Production and performance-sensitive workloads Yes`,`learn-storage|gp3 Premium SSD v2 Performance-sensitive workloads or workloads that require high IOPS and low latency No`,`learn-storage|io2 Ultra Disk Storage IO-intensive workloads, performance-demanding databases, and high-transaction workloads`,`ebs-volume-types|I/O-intensive database workloads`]),breaks:n(`EBS also has HDD-backed types (st1 and sc1), which are optimized for large streaming workloads where throughput is the dominant performance attribute; Learn pairs gp2, gp3 and io2 with Azure managed disks and has no pairing for the HDD-backed types.`,[`ebs-volume-types`,`learn-storage`],[`ebs-volume-types|HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`,`learn-storage|Comparing block storage choices Both platforms provide different types of disks to meet particular performance needs.`])}]},f={building:`grid-planning-office`,overview:[n(`Network design is decided mostly before anything is deployed: how the address space is carved up, which subnets are public or private, how traffic is routed, and how separate networks connect. Address ranges matter early: you cannot create a VPC peering connection between VPCs that have matching or overlapping CIDR blocks. This building covers the design questions; Surveyor's Grid explains CIDR notation, and Gatehouse covers the route tables, security groups and network ACLs that control traffic inside a VPC.`,[`vpc-cidr-blocks`,`peering-basics`],[`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`,`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`])],bullets:[{id:`3.4-K2`,concepts:[n(`IP addressing: a VPC must have an IPv4 CIDR block, between /16 (65,536 addresses) and /28 (16 addresses), and AWS recommends choosing from the private IPv4 ranges in RFC 1918. After creation you can associate additional IPv4 CIDR blocks and one or more IPv6 CIDR blocks, which is how a VPC gets room to grow.`,`vpc-cidr-blocks`,[`When you create a VPC, you must specify an IPv4 CIDR block for the VPC.`,`The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`,`After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`,`When you create a VPC, we recommend that you specify a CIDR block from the private IPv4 address ranges as specified in RFC 1918.`]),n(`Subnet tiers: a public subnet has a direct route to an internet gateway and its resources can reach the public internet; a private subnet does not. The common layout puts a public subnet and a private subnet in each Availability Zone.`,`vpc-subnets`,[`Public subnet – The subnet has a direct route to an internet gateway.`,`Resources in a public subnet can access the public internet.`,`Each Availability Zone has a public subnet and a private subnet.`]),n(`Routing: each route table contains routes that direct subnet or gateway traffic, each route has a destination and a target (internet gateway, NAT gateway, VPC peering connection, VPN connection and so on), and AWS uses the most specific matching route.`,[`vpc-route-tables`,`vpc-route-priority`],[`vpc-route-tables|Each route specifies a destination (CIDR block or prefix list) and a target (such as an internet gateway, NAT gateway, VPC peering connection, or VPN connection).`,`vpc-route-priority|In general, we direct traffic using the most specific route that matches the traffic.`])],services:[`Amazon VPC`],design:[n(`Plan the address space with every network you will ever connect in mind: VPCs that will be peered need non-overlapping CIDR blocks. If the VPCs already have overlapping ranges, AWS notes that PrivateLink is a good solution.`,[`peering-basics`,`connectivity-privatelink`],[`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`connectivity-privatelink|Alternatively, AWS PrivateLink is a good solution when the VPCs have overlapped IP addresses.`])]},{id:`3.4-S1`,concepts:[n(`Subnet topology: a public subnet has a direct route to an internet gateway, and the common layout gives each Availability Zone a public subnet and a private subnet. (Blueprint Hall covers the tiers; Gatehouse covers the controls between them.)`,`vpc-subnets`,[`Public subnet – The subnet has a direct route to an internet gateway.`,`Each Availability Zone has a public subnet and a private subnet.`]),n(`Connecting two VPCs: a VPC peering connection routes traffic between them using private addresses, across accounts and Regions, but it is not transitive and needs non-overlapping CIDR blocks.`,[`peering-what-is`,`peering-basics`],[`peering-what-is|The VPCs can be in different Regions (also known as an inter-Region VPC peering connection).`,`peering-basics|VPC peering does not support transitive peering relationships.`],{allow:[`two`]}),n(`Connecting many VPCs and on-premises networks (hybrid or global): AWS Transit Gateway is a network transit hub that interconnects VPCs and on-premises networks, scales elastically based on the volume of network traffic, can be peered intra-Region and inter-Region by creating a peering attachment, and can use several transit gateway route tables, associations and propagations to segment traffic.`,[`tgw-what-is`,`tgw-how`,`tgw-peering`,`connectivity-tgw`],[`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`tgw-how|A transit gateway scales elastically based on the volume of network traffic.`,`tgw-peering|You can peer both intra-Region and inter-Region transit gateways, and route traffic between them, which includes IPv4 and IPv6 traffic.`,`connectivity-tgw|You can take advantage of several Transit Gateway route tables, associations, and propagations to segment your traffic within the same Transit Gateway.`]),n(`Reaching a specific service privately: AWS PrivateLink connects a VPC to services and resources as if they were in the VPC, across VPC and account boundaries, without an internet gateway, NAT device or public IP address.`,`privatelink-what-is`,[`AWS PrivateLink is a highly available, scalable technology that you can use to privately connect your VPC to services and resources as if they were in your VPC.`,`You can create AWS PrivateLink-based VPC endpoints to access services, resources, and network segments across VPC and account boundaries.`])],services:[`Amazon VPC`,`AWS Transit Gateway`],design:[n(`Cue to design: hub-and-spoke across many VPCs and on-premises → Transit Gateway; two VPCs only → peering; single shared service → PrivateLink; hybrid links are covered in Edge & Link Terminal.`,[`tgw-what-is`,`peering-what-is`,`privatelink-what-is`],[`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`peering-what-is|VPC peering connection is a networking connection between two VPCs that enables you to route traffic between them using private IPv4 addresses or IPv6 addresses.`,`privatelink-what-is|Therefore, you control the specific API endpoints, sites, services, and resources that are reachable from your VPC.`])]},{id:`3.4-S2`,concepts:[n(`Room to scale: an IPv4 CIDR block can be between a /16 and a /28 netmask, and you can associate additional IPv4 CIDR blocks with a VPC after creating it. A transit gateway scales elastically based on traffic, while peering is not transitive, so enabling traffic between VPC B and VPC C requires its own peering connection.`,[`vpc-cidr-blocks`,`tgw-how`,`peering-basics`],[`vpc-cidr-blocks|After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`,`tgw-how|A transit gateway scales elastically based on the volume of network traffic.`,`peering-basics|If you want to enable routing of traffic between VPC B and VPC C, you must create a unique VPC peering connection between them.`,`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`]),n(`The common layout gives each Availability Zone its own public subnet and private subnet, and a VPC can also have one or more IPv6 CIDR blocks associated with it.`,[`vpc-subnets`,`vpc-cidr-blocks`],[`vpc-subnets|Each Availability Zone has a public subnet and a private subnet.`,`vpc-cidr-blocks|You can optionally associate additional IPv4 CIDR blocks and one or more IPv6 CIDR blocks.`])],services:[`Amazon VPC`,`AWS Transit Gateway`],design:[n(`Cue: "dozens of VPCs will be added" → Transit Gateway rather than a mesh of peering connections; "the VPC needs more address space" → add a CIDR block.`,[`tgw-how`,`connectivity-tgw`,`vpc-cidr-blocks`],[`tgw-how|A transit gateway scales elastically based on the volume of network traffic.`,`connectivity-tgw|With a large number of VPCs, Transit Gateway provides simpler VPC-to-VPC communication management over VPC Peering`,`vpc-cidr-blocks|After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`])]}],cues:[e(`connect two VPCs privately, no overlapping CIDR blocks`,`VPC peering`,n(`Peering routes traffic between two VPCs using private addresses.`,`peering-what-is`,[`VPC peering connection is a networking connection between two VPCs that enables you to route traffic between them using private IPv4 addresses or IPv6 addresses.`])),e(`VPC A is peered with B and C and B must talk to C`,`Peering is not transitive: create B–C peering or use a transit gateway`,n(`VPC peering does not support transitive peering relationships.`,`peering-basics`,[`VPC peering does not support transitive peering relationships.`])),e(`hub for many VPCs and on-premises networks`,`AWS Transit Gateway`,n(`Transit Gateway is a hub that interconnects VPCs and on-premises networks.`,`tgw-what-is`,[`AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`])),e(`private access to one service across accounts without exposing the network`,`AWS PrivateLink`,n(`PrivateLink gives access to specific services across VPC and account boundaries.`,`privatelink-what-is`,[`You can create AWS PrivateLink-based VPC endpoints to access services, resources, and network segments across VPC and account boundaries.`])),e(`overlapping CIDR blocks prevent a connection`,`Peering is impossible; PrivateLink works when the VPCs have overlapping IP addresses`,n(`Peering requires non-overlapping CIDR blocks, while AWS describes PrivateLink as a good solution when the VPCs have overlapped IP addresses.`,[`peering-basics`,`connectivity-privatelink`],[`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`connectivity-privatelink|Alternatively, AWS PrivateLink is a good solution when the VPCs have overlapped IP addresses.`])),e(`VPC is running out of IP addresses`,`Associate an additional CIDR block`,n(`You can associate additional IPv4 CIDR blocks with an existing VPC.`,`vpc-cidr-blocks`,[`After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`]))],examples:[],confuse:[`peering-tgw-privatelink`],azure:[{concept:`Virtual Network`,aws:`Amazon VPC`,mapping:n(`Learn describes Azure virtual networks and AWS VPCs as similar: both provide isolated, logically defined network spaces within their cloud platforms.`,[`learn-networking`,`vpc-cidr-blocks`],[`learn-networking|Azure virtual networks and AWS virtual private clouds (VPCs) are similar in that they both provide isolated, logically defined network spaces within their respective cloud platforms.`,`vpc-cidr-blocks|When you create a VPC, you must specify an IPv4 CIDR block for the VPC.`]),breaks:n(`Subnet placement differs, and it shapes the design. In AWS each subnet is bound to a single Availability Zone, so zonal redundancy needs one subnet per zone; in Azure a subnet is a regional construct that spans all availability zones.`,[`learn-networking`,`vpc-subnets`],[`learn-networking|In AWS, each subnet is bound to a single Availability Zone, so achieving zonal redundancy requires creating one subnet per Availability Zone.`,`learn-networking|In Azure, a subnet is a regional construct that spans all availability zones in the region.`,`vpc-subnets|Each subnet must reside entirely within one Availability Zone and cannot span zones.`])},{concept:`Virtual network peering and Azure Virtual WAN`,aws:`VPC peering and AWS Transit Gateway`,mapping:n(`Learn says both Azure and AWS support virtual network / VPC peering, and that more complex peering is done via Azure Virtual WAN or AWS Transit Gateway.`,[`learn-networking`,`tgw-what-is`],[`learn-networking|Both Azure and AWS support virtual network / VPC peering.`,`learn-networking|Both technologies allow more complex peering via Azure Virtual WAN or AWS Transit Gateway.`,`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`]),breaks:n(`Learn also lists Azure Private Link as similar to AWS PrivateLink, providing private connectivity from a virtual network to an Azure platform service, a customer-owned service or a partner service. On the AWS side, PrivateLink lets you control the specific services and resources reachable from your VPC, whereas VPC peering needs non-overlapping CIDR blocks and is not transitive.`,[`privatelink-what-is`,`peering-basics`,`learn-networking`],[`privatelink-what-is|Therefore, you control the specific API endpoints, sites, services, and resources that are reachable from your VPC.`,`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`peering-basics|VPC peering does not support transitive peering relationships.`,`learn-networking|Private Link is similar to AWS PrivateLink.`,`learn-networking|Azure Private Link provides private connectivity from a virtual network to an Azure platform as a service (PaaS) solution, a customer-owned service, or a Microsoft partner service.`])}]},p={building:`ingestion-gate`,overview:[n(`An ingestion access point is where producers send data into AWS, for example a Kinesis data stream. Securing it means answering: who may send (IAM), over which network path (the public internet or private through an interface VPC endpoint), and how the data is protected at rest (server-side encryption with AWS KMS keys). Streaming Canal explains the services; this building is about locking the door.`,[`kinesis-iam`,`kinesis-vpc`,`kinesis-sse`],[`kinesis-iam|AWS Identity and Access Management (IAM) enables you to do the following: Create users and groups under your AWS account`,`kinesis-vpc|You can use an interface VPC endpoint to prevent traffic between your Amazon VPC and Kinesis Data Streams from leaving the Amazon network.`,`kinesis-sse|Server-side encryption using AWS Key Management Service (AWS KMS) keys makes it easy for you to meet strict data management requirements by encrypting your data at rest within Amazon Kinesis Data Streams.`])],bullets:[{id:`3.5-K5`,concepts:[n(`Who may write: access to Kinesis Data Streams is controlled with IAM, so permissions are granted through users, groups and roles. Roles define the users or services that can assume them, and users in another AWS account can be allowed to share your resources.`,`kinesis-iam`,[`Create users and groups under your AWS account Assign unique security credentials to each user under your AWS account Control each user's permissions to perform tasks using AWS resources Allow the users in another AWS account to share your AWS resources Create roles for your AWS account and define the users or services that can assume them`]),n(`Which path: an interface VPC endpoint, powered by AWS PrivateLink, keeps traffic between your VPC and Kinesis Data Streams (and likewise Firehose) on the Amazon network, with no internet gateway, NAT device, VPN connection or Direct Connect connection needed.`,[`kinesis-vpc`,`firehose-vpc`],[`kinesis-vpc|Interface VPC endpoints don't require an internet gateway, NAT device, VPN connection, or Direct Connect connection.`,`kinesis-vpc|Interface VPC endpoints are powered by AWS PrivateLink, an AWS technology that enables private communication between AWS services using an elastic network interface with private IPs in your Amazon VPC.`,`firehose-vpc|You can use an interface VPC endpoint (AWS PrivateLink) to access Amazon Data Firehose from your VPC without requiring an Internet Gateway or NAT Gateway.`]),n(`Data protection at rest: Kinesis Data Streams supports server-side encryption with AWS KMS keys, which encrypts your data at rest within the stream.`,`kinesis-sse`,[`Server-side encryption using AWS Key Management Service (AWS KMS) keys makes it easy for you to meet strict data management requirements by encrypting your data at rest within Amazon Kinesis Data Streams.`]),n(`Amazon MSK clients can authenticate with IAM, which also allows or denies Apache Kafka actions, or with mutual TLS or SASL/SCRAM and Apache Kafka ACLs. Mutual TLS client authentication needs an AWS Private CA, and MSK provides encryption options that it renews certificates for automatically.`,[`msk-clientauth`,`msk-mtls`,`msk-encryption`],[`msk-clientauth|You can use IAM to authenticate clients and to allow or deny Apache Kafka actions.`,`msk-clientauth|Alternatively, you can use TLS or SASL/SCRAM to authenticate clients, and Apache Kafka ACLs to allow or deny actions.`,`msk-mtls|To use client authentication, you need an AWS Private CA.`,`msk-encryption|Amazon MSK provides data encryption options that you can use to meet strict data management requirements.`,`msk-encryption|Amazon MSK automatically renews these certificates for all clusters.`]),n(`File-based ingestion points can also be private: a Transfer Family server endpoint can be hosted inside a VPC for transferring data to and from an S3 bucket or EFS file system without going over the public internet. For new servers the endpoint type to use is VPC.`,`transfer-vpc`,[`You can host your server's endpoint inside a virtual private cloud (VPC) to use for transferring data to and from an Amazon S3 bucket or Amazon EFS file system without going over the public internet.`,`After this date, use EndpointType=VPC.`]),n(`The older Transfer Family endpoint type VPC_ENDPOINT can no longer be used to create a server in an account that had not already used it before May 19, 2021.`,`transfer-vpc`,[`After May 19, 2021, you won't be able to create a server using EndpointType=VPC_ENDPOINT in your AWS account if your account hasn't already done so before May 19, 2021.`,`Discontinuing the use of VPC_ENDPOINT`],{status:`deprecated`})],services:[`Amazon Kinesis`,`Amazon Data Firehose`,`Amazon MSK`,`AWS PrivateLink`,`AWS Transfer Family`],design:[n(`Cue: producers in a private subnet must send to the stream without internet access → interface VPC endpoint (PrivateLink); "restrict which accounts or roles can put records" → IAM policy or role; "encrypt data in the stream" → KMS server-side encryption.`,[`kinesis-iam`,`kinesis-vpc`,`kinesis-sse`],[`kinesis-iam|Create users and groups under your AWS account Assign unique security credentials to each user under your AWS account Control each user's permissions to perform tasks using AWS resources Allow the users in another AWS account to share your AWS resources Create roles for your AWS account and define the users or services that can assume them`,`kinesis-vpc|You can use an interface VPC endpoint to prevent traffic between your Amazon VPC and Kinesis Data Streams from leaving the Amazon network.`,`kinesis-sse|Server-side encryption using AWS Key Management Service (AWS KMS) keys makes it easy for you to meet strict data management requirements by encrypting your data at rest within Amazon Kinesis Data Streams.`])]},{id:`3.5-S6`,concepts:[n(`Ingestion configuration for streams: Kinesis Data Streams capacity is a function of shards, or you can choose on-demand capacity mode; Firehose lets you set a buffer size and buffer interval, and it can capture, transform and load streaming data.`,[`kinesis-concepts`,`firehose`,`firehose-faqs`],[`kinesis-concepts|The data capacity of your stream is a function of the number of shards that you specify for the stream.`,`kinesis-concepts|Currently, in Kinesis Data Streams, you can choose between an on-demand mode and a provisioned mode for your data streams.`,`firehose|Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`,`firehose|Buffer Size is in MBs and Buffer Interval is in seconds.`,`firehose-faqs|It can capture, transform, and load streaming data into Amazon S3, Amazon Redshift, Amazon OpenSearch Service, Snowflake, Apache Iceberg tables and Splunk, enabling near real-time analytics with existing business intelligence tools and dashboards you’re already using today.`],{allow:[`two`]}),n(`Retention is part of the configuration: a Kinesis stream's retention period defaults to 24 hours and can be increased up to 8760 hours (365 days), with additional charges for streams set above 24 hours, so replay needs are sized here.`,`kinesis-concepts`,[`A stream’s retention period is set to a default of 24 hours after creation.`,`You can increase the retention period up to 8760 hours (365 days) using the IncreaseStreamRetentionPeriod operation`,`Additional charges apply for streams with a retention period set to more than 24 hours.`]),n(`Choose the Kafka deployment for MSK: MSK Provisioned lets you choose broker instance types, storage and number of brokers, while MSK Serverless runs Kafka without managing cluster capacity.`,[`msk-provisioned`,`msk-what-is`],[`msk-provisioned|With MSK Provisioned, you can choose the instance types, storage volumes (Standard brokers), and number of broker nodes that make up your Kafka clusters.`,`msk-what-is|Run Apache Kafka without having to manage and scale cluster capacity with MSK Serverless.`]),n(`For file ingestion, DataSync accesses your AWS storage through IAM roles and supports VPC endpoints, and Transfer Family server endpoints can be hosted inside a VPC (Transfer Dock).`,[`datasync-what-is`,`transfer-vpc`],[`datasync-what-is|DataSync accesses your AWS storage through built-in AWS security mechanisms, such as AWS Identity and Access Management (IAM) roles.`,`datasync-what-is|It also supports virtual private cloud (VPC) endpoints, giving you the option to transfer data without traversing the public internet and further increasing the security of data copied online.`,`transfer-vpc|You can host your server's endpoint inside a virtual private cloud (VPC) to use for transferring data to and from an Amazon S3 bucket or Amazon EFS file system without going over the public internet.`])],services:[`Amazon Kinesis`,`Amazon Data Firehose`,`Amazon MSK`],design:[n(`Cue: "unpredictable producer volume, no capacity planning" → Kinesis on-demand capacity mode; "deliver in larger, less frequent batches" → raise Firehose buffer size or interval; "keep records longer for reprocessing" → raise Kinesis retention.`,[`kinesis-concepts`,`firehose`],[`kinesis-concepts|A stream’s retention period is set to a default of 24 hours after creation.`,`kinesis-concepts|With the on-demand mode, Kinesis Data Streams automatically manages the shards in order to provide the necessary throughput.`,`kinesis-concepts|You can increase the retention period up to 8760 hours (365 days) using the IncreaseStreamRetentionPeriod operation`,`firehose|Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`])]}],cues:[e(`producers in private subnets must reach Kinesis or Firehose without internet`,`Interface VPC endpoint (AWS PrivateLink)`,n(`An interface VPC endpoint keeps traffic on the Amazon network and needs no internet gateway or NAT device.`,`firehose-vpc`,[`You can use an interface VPC endpoint (AWS PrivateLink) to access Amazon Data Firehose from your VPC without requiring an Internet Gateway or NAT Gateway.`])),e(`encrypt the stream's data at rest`,`Kinesis Data Streams server-side encryption with AWS KMS`,n(`Server-side encryption with KMS keys encrypts data at rest within the stream.`,`kinesis-sse`,[`Server-side encryption using AWS Key Management Service (AWS KMS) keys makes it easy for you to meet strict data management requirements by encrypting your data at rest within Amazon Kinesis Data Streams.`])),e(`Kafka clients authenticated with IAM`,`Amazon MSK IAM access control`,n(`MSK can use IAM to authenticate clients and to allow or deny Apache Kafka actions.`,`msk-clientauth`,[`You can use IAM to authenticate clients and to allow or deny Apache Kafka actions.`])),e(`SFTP endpoint reachable only from inside the VPC`,`Transfer Family server with a VPC-hosted endpoint`,n(`A Transfer Family server endpoint can be hosted inside a VPC.`,`transfer-vpc`,[`You can host your server's endpoint inside a virtual private cloud (VPC) to use for transferring data to and from an Amazon S3 bucket or Amazon EFS file system without going over the public internet.`])),e(`let a producer in another account write to your stream`,`Cross-account IAM role or resource sharing`,n(`IAM lets users in another AWS account share your resources and lets you create roles others can assume.`,`kinesis-iam`,[`Create users and groups under your AWS account Assign unique security credentials to each user under your AWS account Control each user's permissions to perform tasks using AWS resources Allow the users in another AWS account to share your AWS resources Create roles for your AWS account and define the users or services that can assume them`]))],examples:[],confuse:[]},m={building:`read-replica-annex`,overview:[n(`Database replication copies changes from one database to another. On AWS it serves different purposes: high availability inside a Region (the Multi-AZ standby) and read scaling or distance (read replicas, which can sit in another Region). Telling these apart is the point of this building.`,[`rds-multi-az-instance`,`rds-read-replicas`],[`rds-multi-az-instance|Amazon RDS provides high availability and failover support for DB instances using Multi-AZ deployments with a single standby DB instance.`,`rds-read-replicas|A read replica is a read-only copy of a DB instance.`])],bullets:[{id:`3.3-K1`,concepts:[n(`Availability Zones and Regions shape database placement. An Aurora cluster volume keeps copies of the data across three Availability Zones in a single Region. RDS Multi-AZ places a synchronous standby in a different Availability Zone from the primary, and RDS read replicas can run in the same Region or a different one.`,[`aurora-storage`,`rds-multi-az-instance`,`rds-read-replicas`],[`aurora-storage|A cluster volume consists of copies of the data across three Availability Zones in a single AWS Region.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`]),n(`An Aurora global database spans multiple Regions: it has a primary DB cluster in one Region and up to 10 secondary clusters in different Regions, and Aurora automatically synchronises changes from the primary to the secondaries. It gives fast recovery from a Region-wide outage.`,`aurora-global`,[`With the Amazon Aurora Global Database feature, you set up multiple Aurora DB clusters that span multiple AWS Regions.`,`Aurora automatically synchronizes all changes made in the primary DB cluster to one or more secondary clusters.`,`An Aurora global database has a primary DB cluster in one Region, and up to 10 secondary DB clusters in different Regions.`])],services:[`Amazon RDS`,`Amazon Aurora`],design:[n(`Region-level resilience for a relational database is a cross-Region read replica (RDS) or an Aurora global database; Availability Zone-level resilience is Multi-AZ (RDS) or the Aurora cluster volume that keeps copies of the data across three Availability Zones.`,[`rds-read-replicas`,`rds-multi-az-instance`,`aurora-storage`,`aurora-global`],[`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`aurora-storage|A cluster volume consists of copies of the data across three Availability Zones in a single AWS Region.`,`rds-read-replicas|You can promote a read replica to a standalone instance as a disaster recovery solution if the primary DB instance fails.`,`aurora-global|This multi-Region configuration provides fast recovery from the rare outage that might affect an entire AWS Region.`])]},{id:`3.3-K7`,concepts:[n(`RDS Multi-AZ replication is synchronous: the primary is synchronously replicated across Availability Zones to a standby, which provides data redundancy and minimises latency spikes during system backups. Read replica replication is asynchronous, using the engine's own asynchronous method, so a replica can lag behind its source.`,[`rds-multi-az-instance`,`rds-read-replicas`],[`rds-multi-az-instance|The primary DB instance is synchronously replicated across Availability Zones to a standby replica to provide data redundancy and minimize latency spikes during system backups.`,`rds-read-replicas|Amazon RDS then uses the asynchronous replication method for the DB engine to update the read replica whenever there is a change to the primary DB instance.`]),n(`Because a read replica serves reads while the source may be unavailable, the data on it might be stale in that case. AWS lists serving read traffic while the source is unavailable, business reporting, scaling read-heavy workloads and disaster recovery as the use cases.`,`rds-read-replicas`,[`Serving read traffic while the source DB instance is unavailable.`,`For this use case, keep in mind that the data on the read replica might be stale because the source DB instance is unavailable.`,`Business reporting or data warehousing scenarios where you might want business reporting queries to run against a read replica, rather than your production DB instance.`]),n(`Aurora replicates differently: every Aurora cluster has built-in replication between DB instances sharing one cluster volume, and the other instances are read-only Aurora Replicas that scale reads and are promoted automatically if the writer becomes unavailable.`,`aurora-replication`,[`Each Aurora DB cluster has built-in replication between multiple DB instances in the same cluster.`,`Aurora Replicas also help to increase availability.`,`If the writer instance in a cluster becomes unavailable, Aurora automatically promotes one of the reader instances to take its place as the new writer.`]),n(`An endpoint is the address an application connects to. Aurora Replicas are reached through the cluster's reader endpoint, a single address for queries, and Aurora automatically performs connection-balancing among all the Aurora Replicas behind it. An Aurora cluster can contain up to 15 Aurora Replicas.`,[`aurora-replication`,`aurora-endpoints`],[`aurora-replication|You typically do so by connecting to the reader endpoint of the cluster.`,`aurora-replication|An Aurora DB cluster can contain up to 15 Aurora Replicas.`,`aurora-endpoints|To perform queries, you can connect to the reader endpoint, with Aurora automatically performing connection-balancing among all the Aurora Replicas.`])],services:[`Amazon RDS`,`Amazon Aurora`],design:[n(`Read the replication word: synchronous standby for availability (Multi-AZ); asynchronous copy for read scaling or another Region (read replica); built-in Aurora Replicas for both reads and failover within a cluster; a read replica can also reside in a different Region.`,[`rds-multi-az-instance`,`rds-read-replicas`,`aurora-replication`],[`aurora-replication|That way, Aurora can spread the load for read-only connections across as many Aurora Replicas as you have in the cluster.`,`aurora-replication|Aurora Replicas also help to increase availability.`,`aurora-replication|If the writer instance in a cluster becomes unavailable, Aurora automatically promotes one of the reader instances to take its place as the new writer.`,`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`rds-multi-az-instance|The primary DB instance is synchronously replicated across Availability Zones to a standby replica to provide data redundancy and minimize latency spikes during system backups.`,`rds-read-replicas|When you make updates to the primary DB instance, Amazon RDS copies them asynchronously to the read replica.`])]},{id:`3.3-S1`,concepts:[n(`To configure read replicas: create one from an existing source DB instance (RDS takes a snapshot of the source and creates a read-only instance from it), then direct read-only queries from your applications to the replica. Because the replica allows only read-only connections, updates are made on the primary.`,`rds-read-replicas`,[`When you create a read replica, you specify an existing DB instance as the source.`,`Then Amazon RDS takes a snapshot of the source instance and creates a read-only instance from the snapshot.`,`The read replica operates as a DB instance that allows only read-only connections.`]),n(`Match the configuration to the requirement: reporting queries → a read replica rather than your production DB instance; high availability → Multi-AZ, and a read replica can be added to a Multi-AZ instance when you need both.`,`rds-read-replicas`,[`You can configure a read replica for a DB instance that also has a standby replica configured for high availability in a Multi-AZ deployment.`,`Business reporting or data warehousing scenarios where you might want business reporting queries to run against a read replica, rather than your production DB instance.`]),n(`Remember limits: RDS does not autoscale read replicas, and because a replica allows only read-only connections it does not take writes, so read replicas do not help a write-bound workload. For Aurora, add Aurora Replicas and use the reader endpoint; Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas.`,[`rds-read-replicas`,`aurora-replication`,`aurora-autoscaling`],[`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`,`rds-read-replicas|The read replica operates as a DB instance that allows only read-only connections.`,`aurora-replication|You typically do so by connecting to the reader endpoint of the cluster.`,`aurora-autoscaling|To meet your connectivity and workload requirements, Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas (reader DB instances) provisioned for an Aurora DB cluster.`]),n(`Failover and promotion differ in who acts. For a Multi-AZ DB instance, Amazon RDS handles failovers automatically without administrative intervention, and the failover mechanism changes the DNS record of the DB instance to point to the standby. A read replica is not switched in for you: promoting one to a standalone DB instance is a step you take, and AWS lists it as a data recovery scheme if the primary DB instance fails.`,[`rds-failover`,`rds-promote`],[`rds-failover|Amazon RDS handles failovers automatically so you can resume database operations as quickly as possible without administrative intervention.`,`rds-failover|The failover mechanism automatically changes the Domain Name System (DNS) record of the DB instance to point to the standby DB instance.`,`rds-promote|Implementing failure recovery – You can use read replica promotion as a data recovery scheme if the primary DB instance fails.`])],services:[`Amazon RDS`,`Amazon Aurora`],design:[n(`Scenario cue: "the database is slow only for reporting" → read replica; "needs automatic failover" → Multi-AZ; "needs a copy in another Region for DR or local reads" → cross-Region read replica or Aurora global database.`,[`rds-read-replicas`,`rds-multi-az`,`aurora-global`],[`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`aurora-global|Having a full copy of all your data in multiple geographic locations also enables low-latency read operations for applications that connect from widely separated locations around the world.`,`rds-read-replicas|You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`])]}],cues:[e(`automatic failover to another Availability Zone, no application change`,`RDS Multi-AZ deployment`,n(`Multi-AZ provides high availability and failover support through a standby in another Availability Zone.`,`rds-multi-az-instance`,[`Amazon RDS provides high availability and failover support for DB instances using Multi-AZ deployments with a single standby DB instance.`])),e(`offload read-heavy or reporting queries from the primary`,`RDS read replica`,n(`Routing queries to a read replica reduces load on the primary.`,`rds-read-replicas`,[`You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`])),e(`copy of the database in another Region for DR or local reads`,`Cross-Region read replica (RDS) or Aurora global database`,n(`A read replica can live in another Region and can be promoted if the primary fails.`,`rds-read-replicas`,[`You can promote a read replica to a standalone instance as a disaster recovery solution if the primary DB instance fails.`])),e(`synchronous replication`,`Multi-AZ standby`,n(`Multi-AZ replicates the primary synchronously to the standby.`,`rds-multi-az-instance`,[`The primary DB instance is synchronously replicated across Availability Zones to a standby replica to provide data redundancy and minimize latency spikes during system backups.`])),e(`asynchronous replication`,`Read replica`,n(`Read replicas are updated asynchronously.`,`rds-read-replicas`,[`When you make updates to the primary DB instance, Amazon RDS copies them asynchronously to the read replica.`])),e(`Aurora readers share storage and one is promoted if the writer fails`,`Aurora Replicas (reader endpoint)`,n(`Aurora automatically promotes a reader if the writer becomes unavailable.`,`aurora-replication`,[`If the writer instance in a cluster becomes unavailable, Aurora automatically promotes one of the reader instances to take its place as the new writer.`])),e(`multi-Region Aurora with fast regional recovery`,`Aurora global database`,n(`An Aurora global database spans Regions and provides fast recovery from a Region-wide outage.`,`aurora-global`,[`This multi-Region configuration provides fast recovery from the rare outage that might affect an entire AWS Region.`]))],examples:[],confuse:[`multi-az-vs-read-replicas`]},h={building:`refinery`,overview:[n(`Raw data is rarely ready to analyse. AWS Glue is a serverless data integration service for discovering, preparing, moving and integrating data, and Amazon EMR is a managed cluster platform for big data frameworks such as Apache Hadoop and Apache Spark.`,[`glue-what-is`,`emr-what-is`],[`glue-what-is|AWS Glue is a serverless data integration service that makes it easy for analytics users to discover, prepare, move, and integrate data from multiple sources.`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`])],bullets:[{id:`3.5-K4`,concepts:[n(`AWS Glue consolidates data integration capabilities in a single serverless service: data discovery, modern ETL, cleansing, transforming and centralised cataloguing, with no infrastructure to manage. You can visually create, run and monitor extract, transform and load (ETL) pipelines to load data into your data lakes.`,`glue-what-is`,[`AWS Glue consolidates major data integration capabilities into a single service.`,`These include data discovery, modern ETL, cleansing, transforming, and centralized cataloging.`,`It's also serverless, which means there's no infrastructure to manage.`,`You can visually create, run, and monitor extract, transform, and load (ETL) pipelines to load data into your data lakes.`]),n(`The AWS Glue Data Catalog stores metadata about data sources, transforms and targets. A crawler automatically scans your data sources and extracts metadata into the catalog, and you can also create catalog tables manually. Athena, EMR and Redshift Spectrum can then query the cataloged data.`,[`glue-components`,`glue-catalog`,`glue-what-is`],[`glue-components|AWS Glue uses the AWS Glue Data Catalog to store metadata about data sources, transforms, and targets.`,`glue-catalog|crawler, which automatically scans your data sources and extracts metadata.`,`glue-what-is|Also, you can immediately search and query cataloged data using Amazon Athena, Amazon EMR, and Amazon Redshift Spectrum.`]),n(`Amazon EMR simplifies running big data frameworks such as Apache Hadoop and Apache Spark to process and analyse vast amounts of data, and to transform and move large amounts of data into and out of stores such as S3 and DynamoDB. Amazon EMR Serverless is a deployment option that provides a serverless runtime environment so you do not configure, optimise, secure or operate clusters.`,[`emr-what-is`,`emr-serverless`],[`emr-what-is|Amazon EMR also lets you transform and move large amounts of data into and out of other AWS data stores and databases, such as Amazon Simple Storage Service (Amazon S3) and Amazon DynamoDB.`,`emr-serverless|Amazon EMR Serverless is a deployment option for Amazon EMR that provides a serverless runtime environment.`,`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`])],services:[`AWS Glue`,`Amazon EMR`],design:[n(`Cue: serverless ETL and catalog with minimal operations → Glue; a managed cluster platform for big data frameworks such as Apache Hadoop and Apache Spark → EMR (or EMR Serverless for no cluster management).`,[`glue-what-is`,`emr-what-is`,`emr-serverless`],[`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`glue-what-is|It's also serverless, which means there's no infrastructure to manage.`,`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`])]},{id:`3.5-S5`,concepts:[n(`For data processing compute, Glue is serverless and so suits ETL where you do not want to manage infrastructure. EMR is a managed cluster platform for frameworks like Hadoop and Spark, and EMR Serverless avoids over- or under-provisioning of resources for processing.`,[`glue-what-is`,`emr-what-is`,`emr-serverless`],[`glue-what-is|It's also serverless, which means there's no infrastructure to manage.`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`emr-serverless|EMR Serverless helps you avoid over- or under-provisioning resources for your data processing jobs.`]),n(`Other compute options for processing: AWS Batch for batch computing workloads, Lambda for code that fits its invocation time limit (up to 15 minutes in a single invocation, or up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through event source mappings other than Amazon MQ and Amazon DocumentDB), and Athena for SQL queries over S3 data.`,[`batch-what-is`,`lambda-quotas`,`athena-what-is`],[`batch-what-is|AWS Batch helps you to run batch computing workloads on the AWS Cloud.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation (up to 90 minutes for Lambda Managed Instances functions invoked asynchronously or through any event source mapping except Amazon MQ and Amazon DocumentDB)`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`],{newer:[`lambda-managed-instances`,`lambda-managed-instances-90min`]})],services:[`Amazon EMR`,`AWS Glue`],design:[n(`Cue: "Apache Hadoop or Apache Spark frameworks on a managed cluster platform" → EMR; "serverless ETL with a data catalog" → Glue; "run those frameworks without operating clusters" → EMR Serverless.`,[`emr-what-is`,`emr-serverless`,`glue-what-is`],[`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`,`glue-what-is|AWS Glue is a serverless data integration service that makes it easy for analytics users to discover, prepare, move, and integrate data from multiple sources.`])]},{id:`3.5-S7`,concepts:[n(`Parquet is a performance-oriented, column-based data format. Converting existing raw data from other storage formats to Parquet (or ORC) brings compression by column and predicate pushdown, so Athena queries fetch only the blocks they need, which improves query performance.`,[`glue-parquet`,`athena-columnar`],[`glue-parquet|This format is a performance-oriented, column-based data format.`,`athena-columnar|To convert your existing raw data from other storage formats to Parquet or ORC, you can run CREATE TABLE AS SELECT (CTAS) queries in Athena and specify a data storage format as Parquet or ORC, or use the AWS Glue Crawler.`,`athena-columnar|Compression by column, with compression algorithm selected for the column data type to save storage space in Amazon S3 and reduce disk space and I/O during query processing.`,`athena-columnar|Predicate pushdown in Parquet and ORC enables Athena queries to fetch only the blocks it needs, improving query performance.`]),n(`Two common ways to convert on AWS: a Glue ETL job reads files from S3 and writes Parquet to S3 (Glue supports reading Parquet from S3 and streaming sources and writing Parquet to S3), or an Athena CTAS query creates a new table in a different storage format from a source table.`,[`glue-parquet`,`athena-ctas`],[`glue-parquet|You can use AWS Glue to read Parquet files from Amazon S3 and from streaming sources as well as write Parquet files to Amazon S3.`,`athena-ctas|With CTAS, you can use a source table in one storage format to create another table in a different storage format.`],{allow:[`two`]}),n(`Partition the converted data too: partitioning restricts the amount of data scanned by each query, improving performance and reducing cost.`,`athena-partitions`,[`By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`])],services:[`AWS Glue`,`Amazon Athena`],design:[n(`Cue: "reduce Athena query cost and time on large CSV files" → convert to a columnar format (Parquet or ORC) and partition; "transform data between formats on a schedule with no servers" → Glue job.`,[`athena-columnar`,`athena-partitions`],[`athena-columnar|Apache Parquet and ORC are columnar storage formats that are optimized for fast retrieval of data and used in AWS analytical applications.`,`athena-partitions|By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`])]}],cues:[e(`serverless ETL jobs and a central metadata catalog`,`AWS Glue`,n(`Glue provides serverless ETL and cataloguing.`,`glue-what-is`,[`It's also serverless, which means there's no infrastructure to manage.`])),e(`automatically discover schemas of data in S3`,`AWS Glue crawler (Data Catalog)`,n(`A crawler scans data sources and extracts metadata.`,`glue-catalog`,[`crawler, which automatically scans your data sources and extracts metadata.`])),e(`run Hadoop or Spark at scale on managed clusters`,`Amazon EMR`,n(`EMR runs big data frameworks such as Hadoop and Spark.`,`emr-what-is`,[`Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`])),e(`Spark applications without configuring or operating clusters`,`Amazon EMR Serverless`,n(`EMR Serverless avoids cluster configuration and operation.`,`emr-serverless`,[`With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`])),e(`convert CSV to Parquet to speed up and cheapen queries`,`Glue job or Athena CTAS to a columnar format`,n(`CTAS can create a table in a different storage format from a source table.`,`athena-ctas`,[`With CTAS, you can use a source table in one storage format to create another table in a different storage format.`]))],examples:[t(`Athena CTAS: store a table as Parquet`,`other`,`
CREATE TABLE sales_parquet
WITH (
  format = 'Parquet',
  write_compression = 'SNAPPY'
) AS
SELECT * FROM sales_csv;
`,[n(`CREATE TABLE ... AS SELECT (CTAS) builds a new table from the result of a query, so the data is rewritten in the new table's format.`,`athena-ctas`,[`With CTAS, you can use a source table in one storage format to create another table in a different storage format.`]),n(`The format property sets the storage format of the new table, and write_compression sets the compression format. Here the new table is stored as Parquet with Snappy compression; the Athena documentation notes that the default compression for Parquet is GZIP.`,`athena-ctas`,[`Use the format property to specify ORC, PARQUET, AVRO, JSON, or TEXTFILE as the storage format for the new table.`,`The following example specifies that data in the table new_table be stored in Parquet format and use Snappy compression.`,`The default compression for Parquet is GZIP.`]),n(`The names sales_parquet and sales_csv are placeholders: sales_csv stands for an existing Athena table over CSV files in S3. This is an illustration of the pattern, not configuration to copy.`,`athena-ctas`,[`CREATE TABLE new_table WITH ( format = 'Parquet', write_compression = 'SNAPPY') AS SELECT * FROM old_table;`])])],confuse:[],azure:[{concept:`Data Factory in Microsoft Fabric / Azure Data Factory`,aws:`AWS Glue`,mapping:n(`Learn pairs AWS Glue with Data Factory in Microsoft Fabric or Azure Data Factory; all provide managed data integration.`,[`learn-analytics`,`glue-what-is`],[`learn-analytics|AWS Glue Data Factory in Microsoft Fabric or Azure Data Factory All three provide managed data integration.`,`glue-what-is|AWS Glue is a serverless data integration service that makes it easy for analytics users to discover, prepare, move, and integrate data from multiple sources.`]),breaks:n(`Learn says to compare connectors, transformation engines, private networking, runtime placement, orchestration features and integration with the target analytics platform. A Glue-specific point is the Data Catalog, which integrates with other AWS analytics services.`,[`learn-analytics`,`glue-catalog`],[`learn-analytics|Compare connectors, transformation engines, private networking, runtime placement, orchestration features, and integration with the target analytics platform.`,`glue-catalog|The Data Catalog integrates with other AWS analytics services, providing a unified view of data sources making it easier to manage and analyze data.`])},{concept:`Azure Databricks`,aws:`Amazon EMR`,mapping:n(`Learn pairs Amazon EMR with Azure Databricks: both support managed Apache Spark and other data engineering workloads.`,[`learn-analytics`,`emr-what-is`],[`learn-analytics|Amazon EMR Azure Databricks Both support managed Apache Spark and other data engineering workloads.`,`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`]),breaks:n(`Learn says to compare runtime compatibility, cluster control, autoscaling, governance, notebooks, jobs and ecosystem integrations. On the AWS side, EMR is a managed cluster platform for big data frameworks, EMR Serverless removes the need to operate clusters, and Glue is a separate serverless data integration service.`,[`learn-analytics`,`emr-serverless`,`glue-what-is`],[`learn-analytics|Compare runtime compatibility, cluster control, autoscaling, governance, notebooks, jobs, and ecosystem integrations.`,`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`,`glue-what-is|It's also serverless, which means there's no infrastructure to manage.`])}]},g={building:`streaming-canal`,overview:[n(`Streaming data is emitted at high volume in a continuous, incremental manner, often requiring low-latency processing. Three streaming services are easy to confuse: Kinesis Data Streams (producers push records and consumers process them), {{rename:data-firehose}} (fully managed delivery to destinations) and Amazon MSK (managed Apache Kafka).`,[`what-is-streaming-data`,`kinesis-streams`,`kinesis-concepts`,`firehose`,`msk-what-is`],[`what-is-streaming-data|Streaming data is data that is emitted at high volume in a continuous, incremental manner, often requiring low-latency processing.`,`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`,`kinesis-concepts|The producers continually push data to Kinesis Data Streams, and the consumers process the data in real time.`,`firehose|Amazon Data Firehose is a fully managed service for delivering real-time streaming data to destinations such as Amazon Simple Storage Service (Amazon S3), Amazon Redshift, Amazon OpenSearch Service`,`msk-what-is|fully managed service that enables you to build and run applications that use Apache Kafka to process streaming data.`],{allow:[`three`]})],bullets:[{id:`3.5-K2`,concepts:[n(`Streaming data is emitted at high volume in a continuous, incremental manner, often requiring low-latency processing. Traditional data processing systems capture data in a central data warehouse and process it in groups or batches; batch processing periodically completes high-volume, repetitive data jobs.`,`what-is-streaming-data`,[`Streaming data is data that is emitted at high volume in a continuous, incremental manner, often requiring low-latency processing.`,`Traditional data processing systems capture data in a central data warehouse and process it in groups or batches.`,`Batch processing is the method computers use to periodically complete high-volume, repetitive data jobs.`]),n(`Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations; buffer size is in MBs and buffer interval is in seconds. AWS describes Firehose as enabling near real-time analytics; because delivery waits for the buffer, think of it as delivery in batches rather than record-by-record processing, and note that for S3 the buffer interval can be set from 0 to 900 seconds.`,[`firehose`,`firehose-faqs`],[`firehose|Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`,`firehose|Buffer Size is in MBs and Buffer Interval is in seconds.`,`firehose-faqs|It can capture, transform, and load streaming data into Amazon S3, Amazon Redshift, Amazon OpenSearch Service, Snowflake, Apache Iceberg tables and Splunk, enabling near real-time analytics with existing business intelligence tools and dashboards you’re already using today.`,`firehose-faqs|You can configure the values for S3 buffer size (1 MB to 128 MB) or buffer interval (0 to 900 seconds), and the condition satisfied first triggers data delivery to Amazon S3.`],{newer:[`firehose-zero-buffering`]}),n(`Kinesis Data Streams lets consumers process records as they arrive in real time, with the data retained for a retention period that defaults to 24 hours and can be increased up to 8760 hours (365 days), which AWS documents on its terminology page.`,`kinesis-concepts`,[`A stream’s retention period is set to a default of 24 hours after creation.`,`You can increase the retention period up to 8760 hours (365 days) using the IncreaseStreamRetentionPeriod operation`])],services:[`Amazon Kinesis`,`Amazon Data Firehose`],design:[n(`Cue: delivering streaming data to S3 or Redshift with no code, where near real-time delivery is enough → Firehose; custom code that processes records as they arrive → Kinesis Data Streams (or MSK for Kafka).`,[`firehose`,`firehose-faqs`,`kinesis-streams`],[`firehose|You configure your data producers to send data to Amazon Data Firehose, and it automatically delivers the data to the destination that you specified.`,`firehose-faqs|It can capture, transform, and load streaming data into Amazon S3, Amazon Redshift, Amazon OpenSearch Service, Snowflake, Apache Iceberg tables and Splunk, enabling near real-time analytics with existing business intelligence tools and dashboards you’re already using today.`,`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`])]},{id:`3.5-K7`,concepts:[n(`A Kinesis data stream is a set of shards, and a shard is a uniquely identified sequence of data records; each shard provides a fixed unit of capacity, so the capacity of the stream is a function of the number of shards. A stream also has a capacity mode, on-demand or provisioned, that determines how capacity is managed and how you are charged.`,`kinesis-concepts`,[`A Kinesis data stream is a set of shards.`,`A shard is a uniquely identified sequence of data records in a stream.`,`A stream is composed of one or more shards, each of which provides a fixed unit of capacity.`,`Currently, in Kinesis Data Streams, you can choose between an on-demand mode and a provisioned mode for your data streams.`],{allow:[`two`]}),n(`Multiple consumers can read the same stream in parallel. With enhanced fan-out, consumers receive records with dedicated throughput of up to 2 MB per second per shard and records are pushed to them, so they do not contend with other consumers or need to poll.`,[`kinesis-consumers`,`kinesis-efo`],[`kinesis-consumers|allowing multiple consumers to read data from the same stream in parallel, without contending for read throughput with other consumers.`,`kinesis-efo|This feature lets consumers receive records from a stream with throughput of up to 2 MB of data per second per shard.`,`kinesis-efo|Kinesis Data Streams pushes data records from the stream to consumers that use enhanced fan-out.`]),n(`Amazon Data Firehose is a fully managed service for delivering real-time streaming data to destinations such as S3, Redshift, OpenSearch Service, Splunk, Apache Iceberg tables and HTTP endpoints. You do not write applications or manage resources, and it can capture, transform and load the data; it can also read from an existing Kinesis data stream.`,[`firehose`,`firehose-faqs`],[`Amazon Data Firehose is a fully managed service for delivering real-time streaming data to destinations such as Amazon Simple Storage Service (Amazon S3), Amazon Redshift, Amazon OpenSearch Service, Amazon OpenSearch Serverless, Splunk, Apache Iceberg Tables, and any custom HTTP endpoint`,`With Amazon Data Firehose, you don't need to write applications or manage resources.`,`You can also configure your Firehose stream to automatically read data from an existing Kinesis data stream, and load it into destinations.`,`firehose-faqs|It can capture, transform, and load streaming data into Amazon S3, Amazon Redshift, Amazon OpenSearch Service, Snowflake, Apache Iceberg tables and Splunk, enabling near real-time analytics with existing business intelligence tools and dashboards you’re already using today.`]),n(`Amazon MSK is a fully managed service for building and running applications that use Apache Kafka. It provides control-plane operations such as creating, updating and deleting clusters, lets you use Kafka data-plane operations, and runs open-source Kafka so existing applications, tooling and plugins work without code changes. MSK Provisioned lets you choose broker instance types, storage and number of brokers; MSK Serverless runs Kafka without managing cluster capacity.`,[`msk-what-is`,`msk-provisioned`],[`msk-what-is|Amazon MSK provides the control-plane operations, such as those for creating, updating, and deleting clusters.`,`msk-what-is|It lets you use Apache Kafka data-plane operations, such as those for producing and consuming data.`,`msk-what-is|It runs open-source versions of Apache Kafka.`,`msk-what-is|This means existing applications, tooling, and plugins from partners and the Apache Kafka community are supported without requiring changes to application code.`,`msk-provisioned|MSK Provisioned is an MSK cluster deployment option that allows you to manually configure and scale your Apache Kafka clusters.`,`msk-what-is|Run Apache Kafka without having to manage and scale cluster capacity with MSK Serverless.`])],services:[`Amazon Kinesis`,`Amazon Data Firehose`,`Amazon MSK`],design:[n(`Cue: existing Kafka applications or Kafka tooling must keep working → MSK; AWS-native streaming with custom consumers → Kinesis Data Streams; just deliver to a destination → Firehose.`,[`msk-what-is`,`kinesis-streams`,`firehose`],[`msk-what-is|This means existing applications, tooling, and plugins from partners and the Apache Kafka community are supported without requiring changes to application code.`,`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`,`firehose|With Amazon Data Firehose, you don't need to write applications or manage resources.`])]},{id:`3.5-S2`,concepts:[n(`A typical streaming architecture: producers send to a stream (Kinesis Data Streams or MSK); consumers such as Lambda or Managed Service for Apache Flink process records; Firehose delivers to S3, Redshift or OpenSearch for analysis. A Kinesis data stream can feed Firehose, and Firehose is itself one of the consumer options for Kinesis Data Streams.`,[`kinesis-consumers`,`firehose`],[`kinesis-consumers|You can also develop consumers using other AWS services such as AWS Lambda, Amazon Managed Service for Apache Flink, and Amazon Data Firehose.`,`firehose|You can also configure your Firehose stream to automatically read data from an existing Kinesis data stream, and load it into destinations.`]),n(`Scale a stream deliberately: capacity is a function of the number of shards, or choose on-demand capacity mode so that capacity is managed for you.`,`kinesis-concepts`,[`The data capacity of your stream is a function of the number of shards that you specify for the stream.`,`A data stream capacity mode determines how capacity is managed and how you are charged for the usage of your data stream.`,`With the on-demand mode, Kinesis Data Streams automatically manages the shards in order to provide the necessary throughput.`]),n(`In distributed systems events might be delivered multiple times due to retries, so design applications to handle this.`,`msa-distributed-data`,[`Remember, in distributed systems, events might be delivered multiple times due to retries, so it's important to design your applications to handle this.`])],services:[`Amazon Kinesis`,`Amazon Data Firehose`,`Amazon MSK`],design:[n(`Pattern for clickstream or IoT telemetry: producers → Kinesis Data Streams → (Lambda or Flink for real-time processing) and Firehose → S3 data lake → Athena. Choose MSK instead of Kinesis if Kafka compatibility is a stated requirement.`,[`kinesis-streams`,`firehose`],[`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`,`firehose|Amazon Data Firehose is a fully managed service for delivering real-time streaming data to destinations such as Amazon Simple Storage Service (Amazon S3), Amazon Redshift, Amazon OpenSearch Service`])]}],cues:[e(`custom real-time processing, several independent consumers of the same stream`,`Kinesis Data Streams (enhanced fan-out for dedicated throughput)`,n(`Multiple consumers can read the same stream in parallel without contending for throughput.`,`kinesis-consumers`,[`allowing multiple consumers to read data from the same stream in parallel, without contending for read throughput with other consumers.`])),e(`load streaming data into S3, Redshift or OpenSearch with no code to manage`,`Amazon Data Firehose`,n(`Firehose delivers automatically to the configured destination without applications to write.`,`firehose`,[`With Amazon Data Firehose, you don't need to write applications or manage resources.`])),e(`Apache Kafka compatible, existing Kafka clients`,`Amazon MSK`,n(`MSK runs open-source Apache Kafka so existing applications and tooling work without code changes.`,`msk-what-is`,[`This means existing applications, tooling, and plugins from partners and the Apache Kafka community are supported without requiring changes to application code.`])),e(`Kafka without managing cluster capacity`,`MSK Serverless`,n(`MSK Serverless runs Apache Kafka without managing and scaling cluster capacity.`,`msk-what-is`,[`Run Apache Kafka without having to manage and scale cluster capacity with MSK Serverless.`])),e(`stream capacity should be managed automatically`,`Kinesis Data Streams on-demand capacity mode`,n(`A stream capacity mode determines how capacity is managed; on-demand is one of two modes.`,`kinesis-concepts`,[`A data stream capacity mode determines how capacity is managed and how you are charged for the usage of your data stream.`],{allow:[`two`]})),e(`buffer streaming data by size or time before delivery`,`Amazon Data Firehose (buffer size and interval)`,n(`Firehose buffers by size and interval before delivering.`,`firehose`,[`Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`]))],examples:[],confuse:[`kds-vs-firehose`],azure:[{concept:`Azure Event Hubs`,aws:`Amazon Kinesis Data Streams`,mapping:n(`Learn pairs Kinesis Data Streams with Azure Event Hubs: both ingest and retain high-throughput event streams for independent consumers.`,[`learn-analytics`,`kinesis-streams`],[`learn-analytics|Amazon Kinesis Data Streams Azure Event Hubs Both ingest and retain high-throughput event streams for independent consumers.`,`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`]),breaks:n(`Learn lists partitioning, retention, replay, throughput, protocols and scaling as the points to compare. On the AWS side a stream is made of shards, each a fixed unit of capacity. Amazon Data Firehose has no Learn pairing.`,[`learn-analytics`,`kinesis-concepts`],[`learn-analytics|Compare partitioning, retention, replay, throughput, protocols, and scaling.`,`kinesis-concepts|A stream is composed of one or more shards, each of which provides a fixed unit of capacity.`])},{concept:`Event Hubs for Apache Kafka`,aws:`Amazon MSK`,mapping:n(`Learn pairs Amazon MSK with Event Hubs for Apache Kafka.`,[`learn-analytics`,`msk-what-is`],[`learn-analytics|Amazon Managed Streaming for Apache Kafka Event Hubs for Apache Kafka`,`msk-what-is|It runs open-source versions of Apache Kafka.`]),breaks:n(`Learn states that Amazon MSK runs open-source Apache Kafka whereas Event Hubs provides a Kafka-compatible endpoint and is not an Apache Kafka cluster; a Kafka-compatible endpoint does not provide every Apache Kafka broker feature.`,[`learn-analytics`,`msk-what-is`],[`learn-analytics|Amazon MSK runs open-source Apache Kafka. Event Hubs provides a Kafka-compatible endpoint and isn't an Apache Kafka cluster.`,`learn-analytics|A Kafka-compatible endpoint doesn't provide every Apache Kafka broker feature.`,`msk-what-is|It runs open-source versions of Apache Kafka.`])}]},_={building:`transfer-dock`,overview:[n(`Moving data into AWS is a choice between online and offline paths, and the deciding inputs are how much data there is, how fast the network really is, and whether the transfer is a one-time move or an ongoing sync. Storage Gateway (Freight Depot) is for continuing hybrid access; this building covers moving the data itself.`,[`datasync-what-is`,`snowball-edge`,`transfer-what-is`],[`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`snowball-edge|Each Snowball Edge device can transport data at speeds faster than the internet.`,`transfer-what-is|AWS Transfer Family is a secure transfer service that enables you to transfer files into and out of AWS storage services.`])],bullets:[{id:`3.5-K3`,concepts:[n(`AWS DataSync is a high-speed file transfer service for file or object data to, from and between AWS storage services. It works with on-premises NFS, SMB, HDFS and object storage, with AWS storage services (S3, EFS and the FSx file systems), and with storage in other clouds. A DataSync agent copies data from an on-premises storage system, and data moving into AWS is encrypted with TLS.`,[`datasync-what-is`,`datasync-how`],[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`datasync-what-is|DataSync works with the following AWS storage services: Amazon S3 Amazon EFS Amazon FSx for Windows File Server Amazon FSx for Lustre Amazon FSx for OpenZFS Amazon FSx for NetApp ONTAP`,`datasync-how|Data moving into AWS, encrypted using Transport Layer Security (TLS).`]),n(`AWS Transfer Family offers fully managed support for transferring files over SFTP, AS2, FTPS and FTP, and browser-based transfers, directly into and out of AWS storage. Use it when partners or applications must keep using those protocols.`,`transfer-what-is`,[`AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`]),n(`AWS Storage Gateway connects an on-premises appliance to cloud storage for ongoing hybrid access, with S3 File Gateway, Volume Gateway and Tape Gateway options (Freight Depot).`,`sgw-volume`,[`AWS Storage Gateway offers file-based (S3 File Gateway and FSx File Gateway), volume-based (Volume Gateway), and tape-based (Tape Gateway) storage solutions.`]),n(`The offline-transfer pattern ships storage devices instead of sending the data over the network. Snowball Edge is a device with on-board storage and compute that can transfer data to or from the AWS Cloud; the data is moved by shipping the devices through a regional carrier, which AWS says can be faster than the internet.`,`snowball-edge`,[`Snowball Edge is a device with on-board storage and compute power for select AWS capabilities.`,`Each Snowball Edge device can transport data at speeds faster than the internet.`,`This transport is done by shipping the data in the devices through a regional carrier.`]),n(`AWS now states that Snowball Edge is no longer available to new customers and points new customers to AWS DataSync for online transfers, AWS Data Transfer Terminal for secure physical transfers, or AWS Partner solutions.`,`snowball-edge`,[`AWS Snowball Edge is no longer available to new customers.`,`New customers should explore AWS DataSync for online transfers, AWS Data Transfer Terminal for secure physical transfers, or AWS Partner solutions.`],{status:`closed`}),n(`AWS Data Transfer Terminal is a network-ready physical location where you bring your own storage devices for fast data transfer to and from your AWS Cloud services; you schedule a reservation from the console, and at this time it is available only to AWS Enterprise Support customers.`,`dtt`,[`AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices for fast data transfer to and from your AWS Cloud service.`,`Schedule a reservation at one of our physical Data Transfer Terminal facilities from the AWS Management Console`,`dtt|AWS Data Transfer Terminal is available only to AWS Enterprise Support customers at this time.`])],services:[`AWS DataSync`,`AWS Storage Gateway`,`AWS Transfer Family`,`AWS Snow Family`],design:[n(`Cue: moving file or object data over the network into AWS storage → DataSync; partners using file-transfer protocols such as SFTP → Transfer Family; an on-premises software appliance connected to cloud-based storage → Storage Gateway; bringing storage devices to a physical location instead of using the network → Data Transfer Terminal.`,[`datasync-what-is`,`transfer-what-is`,`storage-gateway-docs`,`dtt`],[`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`,`transfer-what-is|AWS Transfer Family is a secure transfer service that enables you to transfer files into and out of AWS storage services.`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`storage-gateway-docs|AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`,`dtt|AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices for fast data transfer to and from your AWS Cloud service.`])]},{id:`3.5-K6`,concepts:[n(`Sizes and speeds decide online versus offline. When moving the data over the network would take too long, the offline options apply: a Snowball Edge device (shipped, and no longer offered to new customers) or a Data Transfer Terminal location where you bring your own storage devices.`,[`snowball-edge`,`dtt`],[`snowball-edge|Each Snowball Edge device can transport data at speeds faster than the internet.`,`dtt|AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices for fast data transfer to and from your AWS Cloud service.`]),n(`DataSync is described as a high-speed transfer service that handles the movement for you; use it when the network is fast enough to finish within the required window, and add Transfer Family or Storage Gateway when the protocol or continuing access dictates.`,`datasync-what-is`,[`AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`]),n(`Direct Connect is a network option rather than a shipped device: it links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable, and its virtual interfaces bypass internet service providers in your network path (see Edge & Link Terminal and Transit Tariff).`,`dx-what-is`,[`Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`With this connection, you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`])],services:[`AWS DataSync`,`AWS Snow Family`,`AWS Direct Connect`],design:[n(`Estimate the network transfer time as the amount of data divided by the bandwidth you can really sustain. Cue: "deadline is shorter than the network can manage" or "link is slow and the data set is very large" → an offline device; "ongoing small changes" → an online service such as DataSync.`,[`snowball-edge`,`datasync-what-is`],[`snowball-edge|Each Snowball Edge device can transport data at speeds faster than the internet.`,`datasync-what-is|Migrate data – Transfer active datasets rapidly over the network into AWS storage services.`])]},{id:`3.5-S3`,concepts:[n(`A transfer design names the source, the protocol, the destination and the path: NFS, SMB, HDFS or object storage source → DataSync (agent on premises) → S3, EFS or FSx; SFTP or FTPS partners → Transfer Family → S3 or EFS; physical media for huge or slow-link data → offline option.`,[`datasync-what-is`,`transfer-what-is`],[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`]),n(`Secure the transfer: DataSync data moving into AWS is encrypted with Transport Layer Security (TLS). With Transfer Family, FTP uses clear text and does not support encryption of traffic, so if data must traverse the public network you must use secure protocols such as SFTP or FTPS. Choose the destination storage type to match later use (object for a data lake, file for shared access).`,[`datasync-how`,`transfer-ftp`],[`datasync-how|Data moving into AWS, encrypted using Transport Layer Security (TLS).`,`transfer-ftp|FTP uses clear text and does not support encryption of traffic.`,`transfer-ftp|If you need your server to have data traverse the public network, you must use secure protocols, such as SFTP or FTPS.`])],services:[`AWS DataSync`,`AWS Transfer Family`,`AWS Storage Gateway`],design:[n(`Pattern: a very large one-time data set on a slow link → an offline path first, then DataSync for the changes that follow; data that on-premises applications keep using → Storage Gateway.`,[`sgw-file-s3`,`datasync-what-is`],[`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`,`datasync-what-is|Migrate data – Transfer active datasets rapidly over the network into AWS storage services.`])]}],cues:[e(`migrate NFS or SMB file data to S3, EFS or FSx over the network`,`AWS DataSync`,n(`DataSync works with on-premises NFS and SMB and with S3, EFS and FSx.`,`datasync-what-is`,[`DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`])),e(`trading partners send files by SFTP or FTPS into S3`,`AWS Transfer Family`,n(`Transfer Family supports SFTP, AS2, FTPS and FTP into and out of AWS storage.`,`transfer-what-is`,[`AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`])),e(`very large data set and slow or no network, physical shipment`,`Offline transfer (Snowball Edge pattern; no longer available to new customers)`,n(`Snowball Edge devices move data by shipping, which can be faster than the internet.`,`snowball-edge`,[`Each Snowball Edge device can transport data at speeds faster than the internet.`])),e(`on-premises application keeps using cloud storage through a local appliance`,`AWS Storage Gateway`,n(`Storage Gateway connects an on-premises appliance to cloud-based storage.`,`storage-gateway-docs`,[`AWS Storage Gateway is a service that connects an on-premises software appliance with cloud-based storage to provide seamless and secure integration between your on-premises IT environment and the AWS storage infrastructure in the AWS Cloud.`])),e(`bring your own storage devices to an AWS location for fast upload`,`AWS Data Transfer Terminal`,n(`Data Transfer Terminal is a physical location for fast data transfer to and from AWS.`,`dtt`,[`AWS Data Transfer Terminal is a network-ready, physical location you can bring your data storage devices for fast data transfer to and from your AWS Cloud service.`]))],examples:[],confuse:[],azure:[{concept:`Azure Data Box`,aws:`AWS Snowball Edge`,mapping:n(`Learn pairs Snowball Edge with Azure Data Box: a petabyte-scale to exabyte-scale data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`,[`learn-storage`,`snowball-edge`],[`learn-storage|AWS Snowball Edge Azure Data Box Petabyte-scale to exabyte-scale data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`,`snowball-edge|Snowball Edge is a device with on-board storage and compute power for select AWS capabilities.`]),breaks:n(`AWS states that Snowball Edge is no longer available to new customers and suggests DataSync, Data Transfer Terminal or partner solutions, while Learn pairs Snowball Edge with Azure Data Box.`,[`snowball-edge`,`learn-storage`],[`snowball-edge|AWS Snowball Edge is no longer available to new customers.`,`learn-storage|AWS Snowball Edge Azure Data Box Petabyte-scale to exabyte-scale data transport solution that uses enhanced-security data storage devices to transfer large amounts of data to and from the cloud.`])},{concept:`Azure Data Box Gateway / Azure File Sync`,aws:`AWS DataSync and AWS Storage Gateway`,mapping:n(`Learn pairs S3 File Gateway with Azure Data Box Gateway and Azure File Sync as on-premises, locally cached NFS and SMB file shares that are cloud-backed.`,[`learn-storage`,`sgw-file-s3`],[`learn-storage|Provides on-premises, locally cached NFS and SMB file shares that are cloud-backed.`,`sgw-file-s3|You can think of a S3 File Gateway as a file system mount on Amazon S3.`]),breaks:n(`Learn pairs DataSync with Azure File Sync, but they are different tools: Azure File Sync is a cache and sync service for Azure Files, closer to S3 File Gateway, while DataSync is a transfer service that moves file or object data between storage systems.`,[`learn-storage`,`datasync-what-is`],[`learn-storage|Azure Files can be deployed in two main ways: by directly mounting the serverless Azure file shares or by caching Azure file shares on-premises with Azure File Sync.`,`datasync-what-is|AWS DataSync is a secure, reliable, high‐speed file transfer service that helps you quickly and easily transfer your file or object data to, from, and between AWS storage services.`])}]},v={building:`tuning-bay`,overview:[n(`Tuning a database starts from the access patterns your application requires and ends in a capacity decision: read and write units for DynamoDB, or the DB instance class for RDS. Connection counts matter as well, and RDS Proxy pools and shares database connections.`,[`dynamodb-partition-keys`,`rds-instance-class`,`rds-proxy`],[`dynamodb-partition-keys|You can determine the access patterns that your application requires, and read and write units that each table and secondary index requires.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-proxy|By using Amazon RDS Proxy, you can allow your applications to pool and share database connections to improve their ability to scale.`])],beyondProject:[n(`You already use DynamoDB. The SAA step is capacity: provisioned mode, where you set read and write capacity units and can use auto scaling, or on-demand mode, which scales automatically without capacity planning. The DynamoDB guidance also asks you to design your application for uniform activity across all partition keys in the table and its secondary indexes.`,[`dynamodb-provisioned`,`dynamodb-ondemand`,`dynamodb-partition-keys`],[`dynamodb-provisioned|For provisioned mode tables, you specify throughput requirements in terms of capacity units.`,`dynamodb-provisioned|You can use auto scaling to adjust your table's provisioned capacity automatically in response to traffic changes.`,`dynamodb-ondemand|Amazon DynamoDB on-demand offers a truly serverless database experience that automatically scales to accommodate the most demanding workloads without capacity planning.`,`dynamodb-partition-keys|You should design your application for uniform activity across all partition keys in the table and its secondary indexes.`])],bullets:[{id:`3.3-K3`,concepts:[n(`An access pattern is how the application reads and writes data. For DynamoDB you determine the access patterns your application requires, and the read and write units each table and secondary index needs, then design the key schema: a simple primary key (a partition key only) or a composite key (a partition key and a sort key), with uniform activity across partition keys.`,`dynamodb-partition-keys`,[`The primary key that uniquely identifies each item in an Amazon DynamoDB table can be simple (a partition key only) or composite (a partition key combined with a sort key).`,`You should design your application for uniform activity across all partition keys in the table and its secondary indexes.`,`You can determine the access patterns that your application requires, and read and write units that each table and secondary index requires.`]),n(`Read-intensive and write-intensive workloads call for different answers. A read replica operates as a DB instance that allows only read-only connections, so it can take read traffic (Read-Replica Annex) but not writes; a key-value database such as DynamoDB can scale to very high request throughput for large numbers of simultaneous users.`,[`rds-read-replicas`,`database-decision`],[`rds-read-replicas|The read replica operates as a DB instance that allows only read-only connections.`,`database-decision|Key-value databases can scale to large amounts of data and extremely high throughput of requests, while servicing millions of simultaneous users through distributed processing and storage.`])],services:[`Amazon DynamoDB`,`Amazon RDS`],design:[n(`Cue: "read-intensive" → read replicas, which allow only read-only connections, or a cache (Cache Pavilion); I/O-intensive relational workload needing low I/O latency → Provisioned IOPS storage; very high request throughput for many simultaneous users → a key-value database such as DynamoDB, with uniform activity across partition keys; "unpredictable" → DynamoDB on-demand mode, or Aurora for less predictable query patterns.`,[`rds-read-replicas`,`rds-storage`,`dynamodb-partition-keys`,`dynamodb-ondemand`,`database-decision`],[`rds-read-replicas|The read replica operates as a DB instance that allows only read-only connections.`,`rds-storage|Provisioned IOPS storage is designed to meet the needs of I/O-intensive workloads, particularly database workloads, that require low I/O latency and consistent I/O throughput.`,`dynamodb-partition-keys|You should design your application for uniform activity across all partition keys in the table and its secondary indexes.`,`database-decision|Key-value databases can scale to large amounts of data and extremely high throughput of requests, while servicing millions of simultaneous users through distributed processing and storage.`,`dynamodb-ondemand|Amazon DynamoDB on-demand offers a truly serverless database experience that automatically scales to accommodate the most demanding workloads without capacity planning.`,`database-decision|Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`])]},{id:`3.3-K4`,concepts:[n(`DynamoDB provisioned mode uses capacity units. For an item up to 4 KB, one read capacity unit (RCU) represents one strongly consistent read per second, or two eventually consistent reads per second; a write capacity unit (WCU) represents one write per second for an item up to 1 KB. You can modify them later or enable DynamoDB auto scaling.`,`dynamodb-provisioned`,[`For an item up to 4 KB, one read capacity unit (RCU) represents one strongly consistent read operation per second, or two eventually consistent read operations per second.`,`A write capacity unit (WCU) represents one write per second for an item up to 1 KB.`,`You can modify these settings later, if needed, or enable DynamoDB auto scaling to modify them automatically.`],{allow:[`two`]}),n(`DynamoDB on-demand mode needs no capacity planning: it eliminates capacity management and monitoring and scales automatically, with pay-per-request pricing so there is no idle capacity to pay for.`,`dynamodb-ondemand`,[`On-demand simplifies the setup process, eliminates capacity management and monitoring, and provides fast, automatic scaling.`,`With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`]),n(`For RDS, the DB instance class determines computation and memory capacity, and consists of a class type and a size (db.r6g is a memory-optimised class type; db.r6g.2xlarge is a class within it). Class types include general-purpose, memory-optimized, compute-optimized, burstable-performance and Optimized Reads (classes such as db.m8gd).`,[`rds-instance-class`,`rds-instance-class-types`],[`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-instance-class|A DB instance class consists of both the DB instance class type and the size.`,`rds-instance-class|For example, db.r6g is a memory-optimized DB instance class type powered by AWS Graviton2 processors.`,`rds-instance-class|Within the db.r6g instance class type, db.r6g.2xlarge is a DB instance class.`,`rds-instance-class-types|Amazon RDS supports DB instance classes for the following use cases: General-purpose Memory-optimized Compute-optimized Burstable-performance Optimized Reads`,`rds-instance-class-types|Optimized Reads instance class types The following Optimized Reads instance class types are available: db.m8gd – Instance classes powered by AWS Graviton4 processor.`]),n(`RDS storage comes in Provisioned IOPS SSD, designed for I/O-intensive database workloads that need low I/O latency and consistent throughput, and General Purpose SSD, cost-effective storage that is acceptable for most database workloads that are not latency or performance sensitive. Of the two General Purpose types, RDS recommends gp3 over gp2, and gp3 lets you customise storage performance independently of capacity. RDS notes that DB instances that use General Purpose storage can experience much longer latency than instances that use Provisioned IOPS storage. AWS describes Provisioned IOPS as best suited to production and General Purpose to development and testing.`,`rds-storage`,[`Provisioned IOPS storage is designed to meet the needs of I/O-intensive workloads, particularly database workloads, that require low I/O latency and consistent I/O throughput.`,`General Purpose SSD storage General Purpose storage offers cost-effective storage that is acceptable for most database workloads that aren't latency or performance sensitive.`,`Amazon RDS offers two types of General Purpose storage: gp3 storage (recommended) and gp2 storage (previous generation). gp3 storage (recommended) By using General Purpose gp3 storage volumes, you can customize storage performance independently of storage capacity.`,`DB instances that use General Purpose storage can experience much longer latency than instances that use Provisioned IOPS storage.`,`If you need a DB instance with minimum latency after these operations, we recommend using Provisioned IOPS SSD storage.`,`Provisioned IOPS storage is best suited for production environments.`,`General Purpose storage is best suited for development and testing environments.`],{newer:[`rds-gp3-storage`],allow:[`two`]}),n(`RDS magnetic storage is deprecated: you can no longer create new DB instances with it, RDS has migrated existing magnetic storage volumes to gp3, and since July 1, 2026 you can no longer restore a snapshot to magnetic storage. Choose General Purpose SSD or Provisioned IOPS SSD.`,`rds-storage`,[`Magnetic (deprecated) – Magnetic storage is deprecated and is no longer offered for new DB instances.`,`You can no longer create new DB instances using magnetic storage, and Amazon RDS has migrated existing magnetic storage volumes to gp3.`,`Starting July 1, 2026, you can no longer restore a snapshot to magnetic storage.`,`Use General Purpose SSD or Provisioned IOPS SSD for any new storage needs.`],{newer:[`rds-gp3-storage`],status:`deprecated`})],services:[`Amazon RDS`,`Amazon DynamoDB`,`Amazon Aurora`],design:[n(`Cue: a DynamoDB table whose capacity you want adjusted automatically as traffic changes → provisioned capacity with auto scaling; no capacity planning wanted → on-demand; production database whose question states low-latency or sustained I/O needs → Provisioned IOPS storage; a general workload with no stated latency pressure → General Purpose (gp3).`,[`dynamodb-provisioned`,`dynamodb-ondemand`,`rds-storage`],[`dynamodb-provisioned|You can modify these settings later, if needed, or enable DynamoDB auto scaling to modify them automatically.`,`dynamodb-ondemand|Amazon DynamoDB on-demand offers a truly serverless database experience that automatically scales to accommodate the most demanding workloads without capacity planning.`,`rds-storage|Provisioned IOPS storage is designed to meet the needs of I/O-intensive workloads, particularly database workloads, that require low I/O latency and consistent I/O throughput.`,`rds-storage|General Purpose SSD storage General Purpose storage offers cost-effective storage that is acceptable for most database workloads that aren't latency or performance sensitive.`])]},{id:`3.3-K5`,concepts:[n(`Each client connection costs the database resources. Amazon RDS Proxy pools and shares database connections: the proxy enables applications to open many client connections while it manages a smaller number of long-lived connections to the DB instance, which can also reduce CPU overhead for establishing connections.`,`rds-proxy-planning`,[`The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`It can also help reduce the CPU overhead for establishing connections.`]),n(`RDS Proxy makes applications more resilient to database failures by connecting to a standby instance while preserving application connections, handles unpredictable surges in database traffic, and can enforce IAM authentication, using IAM database authentication or credentials from Secrets Manager.`,`rds-proxy`,[`RDS Proxy makes applications more resilient to database failures by automatically connecting to a standby DB instance while preserving application connections.`,`Using RDS Proxy, you can handle unpredictable surges in database traffic.`,`By using RDS Proxy, you can enforce AWS Identity and Access Management (IAM) authentication for clients connecting to the proxy, and the proxy can connect to databases using either IAM database authentication or credentials stored in AWS Secrets Manager.`]),n(`A database that reports "too many connections" is a good candidate for a proxy, and so are AWS Lambda functions. (Single-Point Watch covers the resilience angle.)`,`rds-proxy-planning`,[`Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`AWS Lambda functions can also be good candidates for using a proxy.`])],services:[`Amazon RDS`,`AWS Lambda`],design:[n(`Cue: connection exhaustion from Lambda or many app servers → RDS Proxy; unpredictable surges in database traffic → RDS Proxy.`,[`rds-proxy-planning`,`rds-proxy`],[`rds-proxy-planning|AWS Lambda functions can also be good candidates for using a proxy.`,`rds-proxy|Using RDS Proxy, you can handle unpredictable surges in database traffic.`,`rds-proxy-planning|Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`])]},{id:`3.3-S2`,concepts:[n(`A database architecture combines the choices above: engine and type (Database Registry), capacity (instance class, storage, capacity units), scale-out for reads (replicas, cache), connection management (proxy) and resilience (Multi-AZ).`,[`database-decision`,`rds-proxy`,`rds-instance-class`,`rds-read-replicas`,`rds-multi-az-instance`],[`rds-read-replicas|You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`,`rds-multi-az-instance|Amazon RDS provides high availability and failover support for DB instances using Multi-AZ deployments with a single standby DB instance.`,`database-decision|If your workload requires extremely high read performance with a response time measured in microseconds (rather than single-digit milliseconds), you might want to consider using in- memory caching solutions such as Amazon ElastiCache alongside your database, or a fully durable, persistent in-memory database such as Amazon MemoryDB.`,`database-decision|Performance - Consider whether your database will need to support a high concurrency of transactions (10,000 or more), and whether it needs to be deployed in multiple geographic regions.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-proxy|By using Amazon RDS Proxy, you can allow your applications to pool and share database connections to improve their ability to scale.`]),n(`The database decision guide frames performance questions this way: whether the database must support a high concurrency of transactions and whether it needs to be deployed in multiple geographic Regions. Aurora is suggested for less predictable query patterns, and in-memory caching alongside the database for microsecond reads.`,`database-decision`,[`Performance - Consider whether your database will need to support a high concurrency of transactions (10,000 or more), and whether it needs to be deployed in multiple geographic regions.`,`Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`,`If your workload requires extremely high read performance with a response time measured in microseconds (rather than single-digit milliseconds), you might want to consider using in- memory caching solutions such as Amazon ElastiCache alongside your database, or a fully durable, persistent in-memory database such as Amazon MemoryDB.`])],services:[`Amazon RDS`,`Amazon DynamoDB`,`Amazon Aurora`],design:[n(`Build the answer step by step, from the stated access pattern and the bottleneck, adding one component per problem: pick the database type, size it for the bottleneck (instance class and storage, or capacity mode), add replicas or a cache for reads, a proxy for connections, and Multi-AZ for availability.`,[`rds-instance-class`,`rds-proxy`],[`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-proxy|By using Amazon RDS Proxy, you can allow your applications to pool and share database connections to improve their ability to scale.`])]}],cues:[e(`DynamoDB traffic is unpredictable or spiky, no capacity planning wanted`,`DynamoDB on-demand capacity mode`,n(`On-demand mode scales automatically without capacity planning.`,`dynamodb-ondemand`,[`Amazon DynamoDB on-demand offers a truly serverless database experience that automatically scales to accommodate the most demanding workloads without capacity planning.`])),e(`predictable DynamoDB traffic, set read/write capacity and adjust automatically`,`Provisioned capacity with DynamoDB auto scaling`,n(`Provisioned mode uses capacity units and can use auto scaling.`,`dynamodb-provisioned`,[`You can modify these settings later, if needed, or enable DynamoDB auto scaling to modify them automatically.`])),e(`I/O-intensive production database needing low latency and consistent throughput`,`RDS Provisioned IOPS SSD storage`,n(`Provisioned IOPS storage is designed for I/O-intensive database workloads.`,`rds-storage`,[`Provisioned IOPS storage is designed to meet the needs of I/O-intensive workloads, particularly database workloads, that require low I/O latency and consistent I/O throughput.`])),e(`general database workload, no stated latency pressure, cost-effective storage`,`RDS General Purpose SSD storage (gp3 is the recommended type)`,n(`General Purpose storage is acceptable for most database workloads that are not latency or performance sensitive, and gp3 is the recommended General Purpose type.`,`rds-storage`,[`General Purpose SSD storage General Purpose storage offers cost-effective storage that is acceptable for most database workloads that aren't latency or performance sensitive.`,`Amazon RDS offers two types of General Purpose storage: gp3 storage (recommended) and gp2 storage (previous generation). gp3 storage (recommended) By using General Purpose gp3 storage volumes, you can customize storage performance independently of storage capacity.`],{allow:[`two`]})),e(`development and test database, cost-effective storage`,`RDS General Purpose SSD storage`,n(`General Purpose storage is best suited for development and testing environments.`,`rds-storage`,[`General Purpose storage is best suited for development and testing environments.`])),e(`too many database connections`,`Amazon RDS Proxy`,n(`Any instance that encounters "too many connections" errors is a good candidate for a proxy.`,`rds-proxy-planning`,[`Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`])),e(`memory-bound database`,`Memory-optimized RDS DB instance class`,n(`Memory-optimized is one of the RDS DB instance class types.`,`rds-instance-class-types`,[`Amazon RDS supports DB instance classes for the following use cases: General-purpose Memory-optimized Compute-optimized Burstable-performance Optimized Reads`]))],examples:[],confuse:[]},y={building:`turbine-hall`,overview:[n(`Scaling for performance is two questions: which metric tells you more capacity is needed, and which kind of scaling policy acts on it. Edge services answer a third question, which is whether the work can move closer to the user so it never reaches your Region at all.`,[`asg-target-tracking`,`cloudfront-what-is`],[`asg-target-tracking|With target tracking, you select a metric and a target value to represent the ideal average utilization or throughput level for your application.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`])],bullets:[{id:`3.2-K2`,concepts:[n(`CloudFront delivers content through a worldwide network of edge locations and routes each request to the edge location with the lowest latency. If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`cloudfront-what-is`,[`CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`When a user requests content that you're serving with CloudFront, the request is routed to the edge location that provides the lowest latency (time delay), so that content is delivered with the best possible performance.`,`If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately`]),n(`Code can run at the edge too. CloudFront Functions are lightweight JavaScript functions for high-scale, latency-sensitive CDN customisations with submillisecond startup. Lambda@Edge is an extension of AWS Lambda for complex functions and full application logic closer to your viewers.`,`cf-edge-functions`,[`You can write lightweight functions in JavaScript for high-scale, latency-sensitive CDN customizations.`,`The CloudFront Functions runtime environment offers submillisecond startup times, scales immediately to handle millions of requests per second, and is highly secure.`,`Lambda@Edge is an extension of AWS Lambda that offers powerful and flexible computing for complex functions and full application logic closer to your viewers`]),n(`Distributing across Availability Zones and Regions is the other half of distributed computing: distribute workload resources across multiple Availability Zones or, where necessary, across AWS Regions (Island Charts covers Route 53 routing across zones and Regions; Charter Hall covers the Region and Availability Zone model).`,`waf-multi-location`,[`Distribute workload data and resources across multiple Availability Zones or, where necessary, across AWS Regions.`])],services:[`Amazon CloudFront`],design:[n(`Cue: personalise, redirect or rewrite requests with very low latency at scale → CloudFront Functions; heavier logic at the edge → Lambda@Edge; static and dynamic content for global users → CloudFront.`,`cf-edge-functions`,[`You can write lightweight functions in JavaScript for high-scale, latency-sensitive CDN customizations.`])]},{id:`3.2-K4`,concepts:[n(`Amazon EC2 Auto Scaling keeps the right number of instances for the load, and you can scale in several ways: manual, scheduled, dynamic and predictive scaling. (The scheduled, predictive and target tracking policies are explained in Scaling Floodgate.)`,[`asg-what-is`,`asg-scaling-overview`,`asg-target-tracking`,`asg-scheduled`,`asg-predictive`],[`asg-what-is|Amazon EC2 Auto Scaling helps you ensure that you have the correct number of Amazon EC2 instances available to handle the load for your application.`,`asg-scaling-overview|Manual scaling is the most basic way to scale your Auto Scaling group.`,`asg-scaling-overview|Scale dynamically based on demand`,`asg-target-tracking|A target tracking scaling policy automatically scales the capacity of your Auto Scaling group based on a target metric value.`,`asg-scheduled|With scheduled scaling, you can set up automatic scaling for your application based on predictable load changes.`,`asg-predictive|Predictive scaling works by analyzing historical load data to detect daily or weekly patterns in traffic flows.`]),n(`Application Auto Scaling does the same for resources of individual AWS services beyond EC2, such as DynamoDB tables and global secondary indexes, Aurora replicas, Amazon ECS services, ElastiCache, Amazon EMR clusters, Lambda provisioned concurrency, Spot Fleet requests and custom resources.`,`appas-what-is`,[`Application Auto Scaling is a web service for developers and system administrators who need a solution for automatically scaling their scalable resources for individual AWS services beyond Amazon EC2 Auto Scaling.`,`Aurora replicas Amazon Comprehend document classification and entity recognizer endpoints DynamoDB tables and global secondary indexes Amazon ECS services`,`ElastiCache replication groups (Redis OSS and Valkey) and Memcached clusters Amazon EMR clusters Amazon Keyspaces (for Apache Cassandra) tables Lambda function provisioned concurrency`,`Spot Fleet requests Pool of Amazon WorkSpaces Custom resources provided by your own applications or services.`]),n(`AWS documents how to migrate from scaling plans to EC2 Auto Scaling and Application Auto Scaling scaling policies.`,`scaling-plan-migrate`,[`You can migrate from a scaling plan to Amazon EC2 Auto Scaling and Application Auto Scaling scaling policies.`])],services:[`Amazon EC2 Auto Scaling`,`AWS Auto Scaling`],design:[n(`Cue: scale a DynamoDB table's capacity or an ECS service automatically → Application Auto Scaling; scale EC2 instances → EC2 Auto Scaling.`,`appas-what-is`,[`Amazon ECS services ElastiCache replication groups (Redis OSS and Valkey) and Memcached clusters Amazon EMR clusters`])]},{id:`3.2-S2`,concepts:[n(`Target tracking policies use predefined metrics or custom metrics. The predefined metrics are the group's average CPU utilisation (ASGAverageCPUUtilization), average network bytes in and out, and Application Load Balancer request count per target (ALBRequestCountPerTarget). Custom metrics allow scaling on other CloudWatch metrics, including high-resolution metrics.`,`asg-target-tracking`,[`You can create target tracking scaling policies with either predefined metrics or custom metrics.`,`ASGAverageCPUUtilization—Average CPU utilization of the Auto Scaling group.`,`ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`,`Custom metrics allow you to scale on other available CloudWatch metrics including high-resolution metrics that are published at finer intervals in the order of a few seconds.`]),n(`Step scaling and simple scaling policies scale the group in predefined increments based on CloudWatch alarms: you define separate policies for scaling out and scaling in when an alarm threshold is breached.`,`asg-step`,[`Step scaling and simple scaling policies scale the capacity of your Auto Scaling group in predefined increments based on CloudWatch alarms.`,`You can define separate scaling policies to handle scaling out (increasing capacity) and scaling in (decreasing capacity) when an alarm threshold is breached.`]),n(`Pick a metric that tracks the real bottleneck. The predefined metrics include average CPU utilisation and Application Load Balancer request count per target, and custom metrics let you scale on other CloudWatch metrics. A queue-based worker fleet scales on a custom backlog per instance metric (see Express Rail Hub). You can use multiple target tracking policies together, provided that each uses a different metric.`,[`asg-target-tracking`,`asg-sqs`],[`asg-target-tracking|To help optimize scaling performance, you can use multiple target tracking scaling policies together, provided that each of them uses a different metric.`,`asg-target-tracking|ASGAverageCPUUtilization—Average CPU utilization of the Auto Scaling group.`,`asg-target-tracking|ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`,`asg-sqs|To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`,`asg-sqs|before publishing it as a custom metric to CloudWatch.`,`asg-sqs|Set the target value to the acceptable backlog per instance that you want to maintain.`])],services:[`Amazon EC2 Auto Scaling`,`Amazon CloudWatch`],design:[n(`Cue: "keep average CPU at a target value" → target tracking on CPU; "add more instances the further a metric exceeds its threshold" → step scaling; "keep requests per instance steady behind an ALB" → target tracking on ALBRequestCountPerTarget.`,[`asg-target-tracking`,`asg-step`],[`asg-target-tracking|ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`,`asg-step|You can define separate scaling policies to handle scaling out (increasing capacity) and scaling in (decreasing capacity) when an alarm threshold is breached.`])]}],cues:[e(`maintain average CPU utilisation at a target value`,`Target tracking scaling policy (ASGAverageCPUUtilization)`,n(`ASGAverageCPUUtilization is the average CPU utilisation of the Auto Scaling group.`,`asg-target-tracking`,[`ASGAverageCPUUtilization—Average CPU utilization of the Auto Scaling group.`])),e(`scale based on requests per instance behind a load balancer`,`Target tracking on ALBRequestCountPerTarget`,n(`ALBRequestCountPerTarget is the average ALB request count per target for the group.`,`asg-target-tracking`,[`ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`])),e(`add capacity in steps depending on how far a CloudWatch alarm is breached`,`Step scaling policy`,n(`Step scaling scales in predefined increments based on CloudWatch alarms.`,`asg-step`,[`Step scaling and simple scaling policies scale the capacity of your Auto Scaling group in predefined increments based on CloudWatch alarms.`])),e(`automatically scale DynamoDB capacity, ECS services or Aurora replicas`,`Application Auto Scaling`,n(`Application Auto Scaling scales resources for individual AWS services beyond EC2.`,`appas-what-is`,[`Application Auto Scaling is a web service for developers and system administrators who need a solution for automatically scaling their scalable resources for individual AWS services beyond Amazon EC2 Auto Scaling.`])),e(`lightweight request rewriting at the CDN edge with submillisecond startup`,`CloudFront Functions`,n(`CloudFront Functions have submillisecond startup times and scale immediately to millions of requests per second.`,`cf-edge-functions`,[`The CloudFront Functions runtime environment offers submillisecond startup times, scales immediately to handle millions of requests per second, and is highly secure.`])),e(`complex application logic close to viewers`,`Lambda@Edge`,n(`Lambda@Edge offers computing for complex functions and full application logic closer to your viewers.`,`cf-edge-functions`,[`Lambda@Edge is an extension of AWS Lambda that offers powerful and flexible computing for complex functions and full application logic closer to your viewers`]))],examples:[],confuse:[],azure:[{concept:`Azure Virtual Machine Scale Sets / App Service autoscaling`,aws:`Amazon EC2 Auto Scaling (and Application Auto Scaling)`,mapping:n(`Learn pairs AWS Auto Scaling with Azure Virtual Machine Scale Sets and App Service autoscaling. You can use Azure App Service to automatically scale App Service applications.`,[`learn-compute`,`asg-what-is`],[`learn-compute|AWS service Azure service Description AWS Auto Scaling Azure Virtual Machine Scale Sets, Azure App Service autoscaling In Azure, you can use virtual machine scale sets to deploy and manage identical sets of VMs.`,`learn-compute|You can use Azure App Service to automatically scale Azure App Service applications.`,`asg-what-is|You create collections of EC2 instances, called Auto Scaling groups.`]),breaks:n(`Learn compares AWS Auto Scaling with Azure Virtual Machine Scale Sets and App Service autoscaling, but on AWS the scaling service you need depends on the resource: EC2 Auto Scaling groups scale instances, and Application Auto Scaling scales resources such as DynamoDB tables, ECS services and Aurora replicas.`,[`learn-compute`,`asg-what-is`,`appas-what-is`],[`learn-compute|AWS service Azure service Description AWS Auto Scaling Azure Virtual Machine Scale Sets, Azure App Service autoscaling In Azure, you can use virtual machine scale sets to deploy and manage identical sets of VMs.`,`asg-what-is|You create collections of EC2 instances, called Auto Scaling groups.`,`asg-what-is|Amazon EC2 Auto Scaling helps you ensure that you have the correct number of Amazon EC2 instances available to handle the load for your application.`,`appas-what-is|With Application Auto Scaling, you can configure automatic scaling for the following resources: WorkSpaces Applications fleets Aurora replicas Amazon Comprehend document classification and entity recognizer endpoints DynamoDB tables and global secondary indexes Amazon ECS services`])},{concept:`Azure Monitor`,aws:`Amazon CloudWatch (as the source of scaling metrics)`,mapping:n(`Learn pairs CloudWatch and X-Ray with Azure Monitor, the telemetry service. On AWS, CloudWatch metrics and alarms are what drive scaling policies.`,[`learn-hub`,`asg-step`],[`learn-hub|Azure Monitor is a comprehensive solution that you can use to collect, analyze, and act on telemetry from your cloud and on-premises environments.`,`asg-step|Step scaling and simple scaling policies scale the capacity of your Auto Scaling group in predefined increments based on CloudWatch alarms.`]),breaks:n(`Learn pairs both Amazon CloudWatch and AWS X-Ray with the single service Azure Monitor. On AWS, CloudWatch metrics and alarms drive scaling policies: step scaling responds to a CloudWatch alarm, and target tracking holds a metric at a target value.`,[`asg-target-tracking`,`asg-step`,`learn-hub`],[`asg-target-tracking|With target tracking, you select a metric and a target value to represent the ideal average utilization or throughput level for your application.`,`asg-step|Step scaling and simple scaling policies scale the capacity of your Auto Scaling group in predefined increments based on CloudWatch alarms.`,`learn-hub|DevOps and application monitoring AWS service Azure service Description Amazon CloudWatch and AWS X-Ray Azure Monitor`])}]},b=Object.values(Object.assign({"../../content/notes/express/cache-pavilion.ts":r,"../../content/notes/express/container-yard.ts":i,"../../content/notes/express/data-lake-reservoir.ts":a,"../../content/notes/express/database-registry.ts":o,"../../content/notes/express/edge-link-terminal.ts":s,"../../content/notes/express/engine-works.ts":c,"../../content/notes/express/express-interchange.ts":l,"../../content/notes/express/express-rail-hub.ts":u,"../../content/notes/express/freight-depot.ts":d,"../../content/notes/express/grid-planning-office.ts":f,"../../content/notes/express/ingestion-gate.ts":p,"../../content/notes/express/read-replica-annex.ts":m,"../../content/notes/express/refinery.ts":h,"../../content/notes/express/streaming-canal.ts":g,"../../content/notes/express/transfer-dock.ts":_,"../../content/notes/express/tuning-bay.ts":v,"../../content/notes/express/turbine-hall.ts":y}));export{b as notes};